StiJsViewer.prototype.postAction = function (action, bookmarkPage, bookmarkAnchor, componentGuid) {

    switch (action) {
        case "Refresh":
            break;

        case "Print":
            switch (this.options.toolbar.printDestination) {
                case "Pdf": this.postPrint("PrintPdf"); break;
                case "Direct": this.postPrint("PrintWithoutPreview"); break;
                case "WithPreview": this.postPrint("PrintWithPreview"); break;
                default: this.controls.menus.printMenu.changeVisibleState(!this.controls.menus.printMenu.visible); break;
            }
            return;

        case "Open":
            if (!this.checkCloudAuthorization("open")) return;
            var openReportDialog = this.InitializeOpenDialog("openReportDialog", function (fileName, filePath, content) {
                openReportDialog.jsObject.postOpen(fileName, content);
            }, ".mdc,.mdz,.mdx,.mrt,.mrz,.mrx");
            openReportDialog.action();
            return;

        case "Save":
            this.controls.menus.saveMenu.changeVisibleState(!this.controls.menus.saveMenu.visible);
            return;

        case "SendEmail":
            this.controls.menus.sendEmailMenu.changeVisibleState(!this.controls.menus.sendEmailMenu.visible);
            return;

        case "Zoom":
            this.controls.menus.zoomMenu.changeVisibleState(!this.controls.menus.zoomMenu.visible);
            return;

        case "ViewMode":
            this.controls.menus.viewModeMenu.changeVisibleState(!this.controls.menus.viewModeMenu.visible);
            return;

        case "FirstPage":
        case "PrevPage":
        case "NextPage":
        case "LastPage":
            if (action == "FirstPage") this.reportParams.pageNumber = 0;
            if (action == "PrevPage" && this.reportParams.pageNumber > 0) this.reportParams.pageNumber--;
            if (action == "NextPage" && this.reportParams.pageNumber < this.reportParams.pagesCount - 1) this.reportParams.pageNumber++;
            if (action == "LastPage") this.reportParams.pageNumber = this.reportParams.pagesCount - 1;
            if (this.controls.reportPanel.pagesNavigationIsActive()) {
                this.scrollToPage(this.reportParams.pageNumber);
                if (this.controls.toolbar) this.controls.toolbar.changeToolBarState();
                return;
            }
            break;

        case "FullScreen":
            this.changeFullScreenMode(!this.options.appearance.fullScreenMode);
            return;

        case "Zoom25": this.reportParams.zoom = 25; break;
        case "Zoom50": this.reportParams.zoom = 50; break;
        case "Zoom75": this.reportParams.zoom = 75; break;
        case "Zoom100": this.reportParams.zoom = 100; break;
        case "Zoom150": this.reportParams.zoom = 150; break;
        case "Zoom200": this.reportParams.zoom = 200; break;

        case "ZoomOnePage":
        case "ZoomPageWidth":
            if (this.options.toolbar.displayMode == "Separated") {
                this.controls.toolbar.controls.ZoomOnePage.setSelected(action == "ZoomOnePage");
                this.controls.toolbar.controls.ZoomPageWidth.setSelected(action == "ZoomPageWidth");
            }
            this.reportParams.zoom = action == "ZoomPageWidth"
                ? parseInt(this.controls.reportPanel.getZoomByPageWidth())
                : parseInt(this.controls.reportPanel.getZoomByPageHeight());
            break;

        case "ViewModeSinglePage":
            this.reportParams.viewMode = "SinglePage";
            break;

        case "ViewModeContinuous":
            this.reportParams.viewMode = "Continuous";
            break;

        case "ViewModeMultiplePages":
            this.reportParams.viewMode = "MultiplePages";
            break;

        case "ViewModeMultiPage":
            this.reportParams.viewMode = "MultiPage";
            this.reportParams.multiPageContainerWidth = this.controls.reportPanel.offsetWidth;
            this.reportParams.multiPageContainerHeight = this.controls.reportPanel.offsetHeight;
            this.reportParams.multiPageMargins = 10;
            break;

        case "GoToPage":
            this.reportParams.pageNumber = this.controls.toolbar.controls["PageControl"].textBox.getCorrectValue() - 1;
            if (this.controls.reportPanel.pagesNavigationIsActive()) {
                this.scrollToPage(this.reportParams.pageNumber);
                if (this.controls.toolbar) this.controls.toolbar.changeToolBarState();
                return;
            }
            break;

        case "BookmarkAction":
            if (this.reportParams.pageNumber == bookmarkPage || this.reportParams.viewMode != "SinglePage") {
                this.scrollToAnchor(bookmarkAnchor, componentGuid);
                return;
            }
            else {
                this.reportParams.pageNumber = bookmarkPage;
                this.options.bookmarkAnchor = bookmarkAnchor;
                this.options.componentGuid = componentGuid;
            }
            break;

        case "Bookmarks":
            this.controls.bookmarksPanel.changeVisibleState(!this.controls.buttons["Bookmarks"].isSelected);
            return;

        case "Parameters":
            this.controls.parametersPanel.changeVisibleState(!this.controls.buttons["Parameters"].isSelected);
            return;

        case "Resources":
            this.controls.resourcesPanel.changeVisibleState(!this.controls.buttons["Resources"].isSelected);
            return;

        case "Find":
            this.controls.findPanel.changeVisibleState(!this.controls.toolbar.controls.Find.isSelected);
            return;

        case "About":
            this.controls.aboutPanel.changeVisibleState(!this.controls.toolbar.controls.About.isSelected);
            return;

        case "Design":
            this.postDesign();
            return;

        case "Pin":
            if (this.controls.toolbar) this.controls.toolbar.changePinState(!this.options.toolbar.autoHide);
            return;

        case "Submit":

            this.reportParams.editableParameters = null;
            if (this.reportParams.type == "Report") this.reportParams.pageNumber = 0;
            if (this.options.isMobileDevice) this.controls.parametersPanel.changeVisibleState(false);
                    
            this.postInteraction({ action: "Variables", variables: this.controls.parametersPanel.getParametersValues() });
            return;

        case "Reset":
            this.options.parameters = {};
            if (this.options.paramsVariablesStartValues) {
                this.options.paramsVariables = this.options.paramsVariablesStartValues;
            }
            this.controls.parametersPanel.clearParameters();
            this.controls.parametersPanel.addParameters();
            return;

        case "Editor":
            this.SetEditableMode(!this.options.editableMode);
            return;
    }

    // Check for OnePage or PageWidth zoom when the viewer is launched for the first time
    if (this.reportParams.zoom == -1 || this.reportParams.zoom == -2)
        this.reportParams.autoZoom = this.reportParams.zoom;

    // Correct viewer action
    var viewerAction = action == "Refresh" ? "RefreshReport" : "GetPages";
    if (!action || action == "GetReport") {
        this.clearViewerState(true);
        viewerAction = "GetReport";
    }
    var requestUrl = this.options.requestUrl.replace("{action}",
        (viewerAction == "GetReport" || this.options.server.cacheMode == "None")
            ? this.options.actions.getReport
            : this.options.actions.viewerEvent);
    
    this.controls.processImage.show();
    this.postAjax(requestUrl, { action: viewerAction }, this.showReportPage);
}

StiJsViewer.prototype.postOpen = function (fileName, content) {
    if (typeof content != "string" || content == "") return;
    if (content.indexOf("<?xml") == 0 || content.indexOf("{") == 0) content = StiBase64.encode(content);

    var data = {
        "action": "OpenReport",
        "openingFileName": fileName || "Report.mdc",
        "base64Data": content.indexOf("base64,") > 0 ? content.substr(content.indexOf("base64,") + 7) : content
    };
    
    this.clearViewerState();
    this.reportParams.reportFileName = fileName;

    var jsObject = this;
    if (fileName && (fileName.toLowerCase().indexOf(".mdx") >= 0 || fileName.toLowerCase().indexOf(".mrx") >= 0)) {
        var passwordForm = this.InitializePasswordForm();
        passwordForm.show(function (password) {
            data.openingFilePassword = password;
            jsObject.controls.processImage.show();
            jsObject.postAjax(jsObject.options.requestUrl.replace("{action}", jsObject.options.actions.openReport), data, jsObject.showReportPage);
        }, this.collections.loc["PasswordEnter"] + ":");
    }
    else {
        this.controls.processImage.show();
        this.postAjax(this.options.requestUrl.replace("{action}", this.options.actions.openReport), data, this.showReportPage);
    }
}

StiJsViewer.prototype.postPrint = function (printAction) {
    var data = {
        "action": "PrintReport",
        "printAction": printAction,
        "bookmarksPrint": this.options.appearance.bookmarksPrint
    };

    var url = this.options.requestUrl.replace("{action}", this.options.actions.printReport);
    switch (printAction) {
        case "PrintPdf":
            if (this.options.appearance.printToPdfMode == "Popup") this.printAsPdfPopup(data);
            else this.printAsPdf(url, data);
            break;

        case "PrintWithPreview":
            this.postAjax(url, data, this.printAsPopup);
            break;

        case "PrintWithoutPreview":
            this.postAjax(url, data, this.printAsHtml);
            break;
    }
}

StiJsViewer.prototype.printAsPdfPopup = function (data) {
    var url = this.options.requestAbsoluteUrl.replace("{action}", this.options.actions.printReport);
    var win = this.openNewWindow("about:blank", "_blank");
    if (win != null) this.postForm(url, data, win.document);
}

StiJsViewer.prototype.printAsPdf = function (url, data) {
    data.responseType = "blob";

    var printFrameId = this.options.viewerId + "_PdfPrintFrame";
    var printFrame = document.getElementById(printFrameId);
    if (printFrame) this.controls.viewer.removeChild(printFrame);

    printFrame = document.createElement("iframe");
    printFrame.id = printFrameId;
    printFrame.name = printFrameId;
    printFrame.width = "0";
    printFrame.height = "0";
    printFrame.style.position = "absolute";
    printFrame.style.border = "none";
   
    // Firefox does not load the invisible content of the iframe
    if (this.getNavigatorName() == "Mozilla") {
        printFrame.width = "100px";
        printFrame.height = "100px";
        printFrame.style.opacity = "0.01";
        printFrame.style.zIndex = "-100";
        printFrame.style.pointerEvents = "none";
    }

    this.controls.viewer.insertBefore(printFrame, this.controls.viewer.firstChild);

    // Manual printing in browsers that do not support automatic PDF printing
    printFrame.onload = function () {
        printFrame.contentWindow.focus();
        printFrame.contentWindow.print();
    }

    var form = document.createElement("FORM");
    form.setAttribute("id", "printForm");
    form.setAttribute("method", "POST");
    form.setAttribute("action", url);
    form.setAttribute("target", this.options.viewerId + "_PdfPrintFrame");

    var params = this.createPostParameters(data, true);
    for (var key in params) {
        var paramsField = document.createElement("INPUT");
        paramsField.setAttribute("type", "hidden");
        paramsField.setAttribute("name", key);
        paramsField.setAttribute("value", params[key]);
        form.appendChild(paramsField);
    }

    document.body.appendChild(form);
    form.submit();
    document.body.removeChild(form);
}

StiJsViewer.prototype.printAsPopup = function (text, jsObject) {
    var width = jsObject.reportParams.pagesWidth || 790;
    var win = jsObject.openNewWindow("about:blank", "PrintReport", "height=900,width=" + width + ",toolbar=no,menubar=yes,scrollbars=yes,resizable=yes,location=no,directories=no,status=no");
    if (win != null) {
        win.document.open();
        win.document.write(text);
        win.document.close();
    }
}

StiJsViewer.prototype.printAsHtml = function (text, jsObject) {
    if (jsObject.showError(text)) return;

    // Remove '_PdfPrintFrame', this should fix IE strange error
    var printFrameId = jsObject.options.viewerId + "_PdfPrintFrame";
    var printFrame = document.getElementById(printFrameId);
    if (printFrame) jsObject.controls.viewer.removeChild(printFrame);

    printFrameId = jsObject.options.viewerId + "_HtmlPrintFrame";
    printFrame = document.getElementById(printFrameId);
    if (printFrame) jsObject.controls.viewer.removeChild(printFrame);
    
    printFrame = document.createElement("iframe");
    printFrame.id = printFrameId;
    printFrame.name = printFrameId;
    printFrame.width = "0";
    printFrame.height = "0";
    printFrame.style.position = "absolute";
    printFrame.style.border = "none";
    jsObject.controls.viewer.insertBefore(printFrame, jsObject.controls.viewer.firstChild);

    printFrame.contentWindow.document.open();
    printFrame.contentWindow.document.write(text);
    printFrame.contentWindow.document.close();
    setTimeout(function () {
        printFrame.contentWindow.focus();
        printFrame.contentWindow.print();
    });
}

StiJsViewer.prototype.postExport = function (format, settings, elementName, isDashboardExport) {
    var data = {
        action: isDashboardExport ? "ExportDashboard" : "ExportReport",
        exportFormat: format,
        exportSettings: settings,
        elementName: elementName
    };

    var doc = settings && settings.OpenAfterExport && this.options.appearance.openExportedReportWindow == "_blank" ? this.openNewWindow("about:blank", "_blank").document : null;
    var url = doc ? this.options.requestAbsoluteUrl : this.options.requestUrl;
    this.postForm(url.replace("{action}", this.options.actions.exportReport), data, doc);
}

StiJsViewer.prototype.postEmail = function (format, settings) {
    var data = {
        action: "EmailReport",
        exportFormat: format,
        exportSettings: settings
    };

    this.controls.processImage.show();
    this.postAjax(this.options.requestUrl.replace("{action}", this.options.actions.emailReport), data, this.emailResult);
}

StiJsViewer.prototype.postDesign = function () {
    var doc = this.options.appearance.designWindow == "_blank" ? this.openNewWindow("about:blank", "_blank").document : null;
    var url = doc ? this.options.requestAbsoluteUrl : this.options.requestUrl;
    this.postForm(url.replace("{action}", this.options.actions.designReport), { action: "DesignReport" }, doc);
}

StiJsViewer.prototype.postInteraction = function (params) {

    if (!this.options.actions.interaction) {
        if (this.controls.buttons["Parameters"]) this.controls.buttons["Parameters"].setEnabled(false);
        return;
    }

    // Add new drill-down parameters to drill-down queue and calc guid
    if (params.action != "InitVars" && (params.action == "DrillDown" || params.action == "DashboardDrillDown")) {
        if (params.action == "DashboardDrillDown" && params.drillDownParameters) {
            params.drillDownParameters.isDashboardDrillDown = true; //add dbs flag
        }
        var drillDownParameters = this.reportParams.drillDownParameters || [];
        params.drillDownParameters = params.drillDownParameters ? drillDownParameters.concat(params.drillDownParameters) : drillDownParameters;

        if (params.action == "DrillDown")
            params.drillDownGuid = this.reportParams.drillDownGuid || hex_md5(JSON.stringify(params.drillDownParameters));
        else
            params.dashboardDrillDownGuid = this.reportParams.dashboardDrillDownGuid || hex_md5(JSON.stringify(params.drillDownParameters));
    }

    this.controls.processImage.show();
    this.postAjax(
        this.options.requestUrl.replace("{action}", this.options.actions.interaction),
        params,
        params.action == "InitVars" ? this.showParametersPanel : this.showReportPage
    );
}

StiJsViewer.prototype.postReportResource = function (resourceName, viewType) {
    var data = {
        action: "ReportResource",
        reportResourceParams: {
            resourceName: resourceName,
            viewType: viewType
        }
    };

    var doc = viewType == "View" ? this.openNewWindow("about:blank", "_blank").document : null;
    var url = doc ? this.options.requestAbsoluteUrl : this.options.requestUrl;
    this.postForm(url.replace("{action}", this.options.actions.viewerEvent), data, doc);
}

StiJsViewer.prototype.initAutoUpdateCache = function (data, jsObject) {
    if (jsObject.options.server.allowAutoUpdateCache) {
        if (jsObject.controls.timerAutoUpdateCache) clearTimeout(jsObject.controls.timerAutoUpdateCache);
        jsObject.controls.timerAutoUpdateCache = setTimeout(function () {
            jsObject.postAjax(jsObject.options.requestUrl.replace("{action}", jsObject.options.actions.viewerEvent), { action: "UpdateCache" }, jsObject.initAutoUpdateCache);
        }, jsObject.options.server.timeoutAutoUpdateCache);
    }
}

StiJsViewer.prototype.emailResult = function (data, jsObject) {
    jsObject.controls.processImage.hide();
    if (data == "0")
        alert(jsObject.collections.loc["EmailSuccessfullySent"]);
    else {
        if (data.indexOf("<?xml") == 0) {
            alert(jsObject.GetXmlValue(data, "ErrorCode"));
            alert(jsObject.GetXmlValue(data, "ErrorDescription"));
        }
        else
            alert(data);
    }
}

StiJsViewer.prototype.parseReportParameters = function (parameters) {
    this.reportParams.pagesArray = parameters.pagesArray;

    // Apply new report parameters, if not update current page
    if (parameters.action != "GetPages") {
        this.reportParams.type = parameters.reportType;
        this.reportParams.drillDownGuid = parameters.drillDownGuid;
        this.reportParams.dashboardDrillDownGuid = parameters.dashboardDrillDownGuid;
        this.reportParams.pagesCount = parameters.pagesCount;
        if (parameters.pageNumber != null) this.reportParams.pageNumber = parameters.pageNumber;
        this.reportParams.zoom = parameters.zoom;
        this.reportParams.viewMode = parameters.viewMode;
        this.reportParams.reportFileName = parameters.reportFileName;
        this.reportParams.collapsingStates = parameters.collapsingStates;
        if (parameters.bookmarksContent) this.reportParams.bookmarksContent = parameters.bookmarksContent;
        if (parameters.resources) this.reportParams.resources = parameters.resources;
        this.reportParams.isCompilationMode = parameters.isCompilationMode;
        if (parameters.variablesValues) this.reportParams.variablesValues = parameters.variablesValues;
    }
}

StiJsViewer.prototype.parseCloudParameters = function (parameters) {
    if (parameters.maxReportPages) this.showError({
        success: false,
        type: "Warning",
        text: this.collections.loc["QuotaMaximumReportPagesCountExceeded"] + "\n" + this.collections.loc["Maximum"] + " " + this.numberWithSpaces(parameters.maxReportPages) + "."
    });

    if (parameters.maxDataRows) this.showError({
        success: false,
        type: "Warning",
        text: this.collections.loc["QuotaMaximumDataRowsCountExceeded"] + "\n" + this.collections.loc["Maximum"] + " " + this.numberWithSpaces(parameters.maxDataRows) + "."
    });
}

StiJsViewer.prototype.showParametersPanel = function (data, jsObject) {
    if (jsObject.showError(data)) data = null;

    jsObject.options.isParametersReceived = true;
    jsObject.options.paramsVariables = typeof data == "string" ? JSON.parse(data) : data;

    jsObject.InitializeParametersPanel();
    jsObject.controls.processImage.hide();

    if (jsObject.reportParams.type == "Dashboard") jsObject.postAction("GetPages");
}

StiJsViewer.prototype.showDrillDownPage = function (reportFileName, drillDownGuid, drillDownParameters, useDbsDrillDownPanel) {
    if (useDbsDrillDownPanel) return;

    this.controls.drillDownPanel.changeVisibleState(true);

    var buttonExist = false;
    for (var name in this.controls.drillDownPanel.buttons) {
        var button = this.controls.drillDownPanel.buttons[name];
        if (button.reportParams.drillDownGuid == drillDownGuid) {
            buttonExist = true;
            button.style.display = "inline-block";
            button.select();
            break;
        }
    }
    if (!buttonExist) {
        this.controls.drillDownPanel.addButton(reportFileName);
        this.reportParams.drillDownParameters = drillDownParameters;
        this.reportParams.pageNumber = 0;
        this.reportParams.pagesWidth = 0;
        this.reportParams.pagesHeight = 0;
    }

    this.controls.reportPanel.scrollTop = 0;
}

StiJsViewer.prototype.startRefreshReportTimer = function (timeout) {
    if (this.service.refreshReportTimer != null)
        clearInterval(this.service.refreshReportTimer);

    var jsObject = this;
    this.service.refreshReportTimer = setInterval(function () {
        if (!jsObject.service.isRequestInProcess)
            jsObject.postAction("Refresh");
    }, timeout * 1000);
}

StiJsViewer.prototype.stopRefreshReportTimer = function () {
    if (this.service.refreshReportTimer != null) {
        clearInterval(this.service.refreshReportTimer);
        this.service.refreshReportTimer = null;
    }
}

StiJsViewer.prototype.showReportPage = function (data, jsObject) {
    // If report not found, try to get the report again
    if (data == "ServerError:The report is not specified." && jsObject.options.isReportRecieved) {
        jsObject.options.isReportRecieved = false;
        jsObject.reportParams.prevPageNumber = jsObject.reportParams.pageNumber;
        jsObject.postAction("GetReport");
        return;
    }

    jsObject.controls.processImage.hide();
    jsObject.options.isReportRecieved = true;

    // Update the intermediate state of the panels
    jsObject.updateVisibleState();
    
    if (jsObject.showError(data)) return; // Check for error

    if (jsObject.options.server.useCompression) {
        data = StiGZipHelper.unpack(data);
        if (jsObject.showError(data)) return; // Check for error unpacked data
    }
    
    // Get JSON parameters and check for error in JSON format
    var parameters = (typeof (data) == "string" && data.substr(0, 1) == "{") ? JSON.parse(data) : data;
    if (jsObject.showError(parameters)) return;
    
    // Get collection of user values
    if (parameters.userValues) jsObject.options.userValues = parameters.userValues;

    // Add first report do drill-down panel, show drill-down page
    if (jsObject.controls.drillDownPanel.buttonsRow.children.length == 0) {
        jsObject.controls.drillDownPanel.addButton(parameters.reportFileName, jsObject.reportParams);
    }
        
    if (parameters.action == "DrillDown") {
        var useDbsDrillDownPanel = jsObject.controls.dashboardsPanel && jsObject.controls.dashboardsPanel.visible && jsObject.controls.dashboardsPanel.selectedButton;
        if (useDbsDrillDownPanel) {
            jsObject.controls.dashboardsPanel.addDrillDownButton(null, parameters.drillDownGuid, parameters.drillDownParameters, parameters.previewSettings, parameters.reportFileName);
        }
        jsObject.showDrillDownPage(parameters.reportFileName, parameters.drillDownGuid, parameters.drillDownParameters, useDbsDrillDownPanel);
    }

    // Add button to report do drill-down panel, show drill-down page
    if (parameters.action == "DashboardDrillDown" && jsObject.controls.dashboardsPanel) {
        jsObject.controls.dashboardsPanel.addDrillDownButton(parameters.dashboardDrillDownGuid, null, parameters.drillDownParameters, parameters.previewSettings, parameters.reportFileName);
    }
    // Parse report and cloud parameters
    jsObject.parseReportParameters(parameters);
    jsObject.parseCloudParameters(parameters);

    // Add custom report fonts for new report
    if (parameters.action == "GetReport" || parameters.action == "OpenReport") jsObject.addCustomFontStyles(parameters.customFonts);

    // Init viewer panels
    if (parameters.bookmarksContent) jsObject.InitializeBookmarksPanel();
    if (jsObject.controls.resourcesPanel) jsObject.controls.resourcesPanel.update();
    
    // Fill report panel
    
    if (parameters.pagesArray) {
        if (parameters.repaintOnlyDashboardContent) {
            jsObject.controls.reportPanel.repaintDashboardContent(parameters);
        }
        else {
            jsObject.controls.reportPanel.addPages();
        }
    }

    if (jsObject.controls.toolbar) {
        jsObject.controls.toolbar.changeToolBarState();
        jsObject.controls.toolbar.setEnabled(true);
        if (jsObject.controls.navigatePanel) {
            jsObject.controls.navigatePanel.setEnabled(true);
        }
        if (jsObject.controls.buttons.Editor && (parameters.action == "GetReport" || parameters.action == "OpenReport")) {
            jsObject.controls.buttons.Editor.style.display = parameters.isEditableReport ? "" : "none";
        }
    }

    // Check for auto zoom by page width or page height
    if (jsObject.reportParams.autoZoom != null) {
        if (jsObject.reportParams.type == "Report") jsObject.postAction(jsObject.reportParams.autoZoom == -1 ? "ZoomPageWidth" : "ZoomOnePage");
        delete jsObject.reportParams.autoZoom;
    }

    // Go to the bookmark, if it present
    if (jsObject.options.bookmarkAnchor != null) {
        jsObject.scrollToAnchor(jsObject.options.bookmarkAnchor, jsObject.options.componentGuid);
        jsObject.options.bookmarkAnchor = null;
        jsObject.options.componentGuid = null;
    }

    // Find text in the report
    if (jsObject.options.findMode && jsObject.controls.findPanel) jsObject.showFindLabels(jsObject.controls.findPanel.controls.findTextBox.value);
    
    // Init auto-update report cache
    jsObject.initAutoUpdateCache(null, jsObject);

    // Init auto refresh report timer
    jsObject.stopRefreshReportTimer();
    if (parameters.refreshTime && parseInt(parameters.refreshTime) > 0) jsObject.startRefreshReportTimer(parameters.refreshTime);

    // Update all panels
    jsObject.updateVisibleState();
    jsObject.updateLayout();

    // Get the request from user variables if they are not already received
    if (!jsObject.options.isParametersReceived && ((jsObject.reportParams.type == "Report" && jsObject.options.toolbar.showParametersButton) || jsObject.reportParams.type == "Dashboard")) 
    {
      
        jsObject.postInteraction({ action: "InitVars" });
       
    }

    // If report contains dashboards, add dashboards buttons and get dashboard page
    if (parameters.dashboards) {
        jsObject.controls.dashboardsPanel.update(parameters.dashboards, parameters.previewSettings);
        if (!jsObject.controls.menus.saveDashboardMenu) jsObject.InitializeSaveDashboardMenu();
    }

    // Used in cloud viewer
    return parameters;
}


StiJsViewer.prototype.InitializeNavigatePanel = function () {
    var navigatePanel = document.createElement("div");
    navigatePanel.id = this.controls.viewer.id + "NavigatePanel";
    navigatePanel.jsObject = this;
    navigatePanel.visible = false;
    navigatePanel.style.display = "none";
    this.controls.navigatePanel = navigatePanel;
    this.controls.mainPanel.appendChild(navigatePanel);
    navigatePanel.className = "stiJsViewerNavigatePanel";
    if (this.options.isMobileDevice) {
        navigatePanel.style.transition = "margin 300ms ease, opacity 300ms ease";
        if (this.options.toolbar.autoHide) navigatePanel.style.zIndex = 5;
    }

    var controlsTable = this.CreateHTMLTable();
    navigatePanel.appendChild(controlsTable);
  
    var controlProps = [];
    if (this.options.toolbar.showFirstPageButton) controlProps.push(["FirstPage", null, "PageFirst20.png", this.collections.loc["FirstPageToolTip"], null]);
    if (this.options.toolbar.showPreviousPageButton) controlProps.push(["PrevPage", null, "PagePrevious20.png", this.collections.loc["PrevPageToolTip"], null]);
    if (this.options.toolbar.showCurrentPageControl) {
        controlProps.push(["Separator"]);
        controlProps.push(["PageControl"]);
        controlProps.push(["Separator"]);
    }
    if (this.options.toolbar.showNextPageButton) controlProps.push(["NextPage", null, "PageNext20.png", this.collections.loc["NextPageToolTip"], null]);
    if (this.options.toolbar.showLastPageButton) controlProps.push(["LastPage", null, "PageLast20.png", this.collections.loc["LastPageToolTip"], null]);
    controlProps.push(["Space"]);
    controlProps.push(["ZoomPageWidth", null, "ZoomPageWidth20.png", this.collections.loc["ZoomPageWidth"], null]);
    controlProps.push(["ZoomOnePage", null, "ZoomOnePage20.png", this.collections.loc["ZoomOnePage"], null]);
    if (this.options.toolbar.showZoomButton) {
        controlProps.push(["Separator"]);
        controlProps.push(["Zoom", "100%", null, this.collections.loc["Zoom"], "Up"]);
    }

    for (var index = 0; index < controlProps.length; index++) {
        var name = controlProps[index][0];
        
        if (name.indexOf("Space") == 0) {
            controlsTable.addCell().style.width = "100%";
            continue;
        }

        if (name.indexOf("Separator") == 0) {
            controlsTable.addCell(this.NavigatePanelSeparator());
            continue;
        }

        var helpLink = this.helpLinks[name] || "user-manual/index.html?viewing_reports_basic_toolbar_of_report_viewer.htm";
        var control = (name != "PageControl")
            ? this.NavigateButton(name, controlProps[index][1], controlProps[index][2],
                (controlProps[index][3] ? [controlProps[index][3], helpLink] : null), controlProps[index][4])
            : this.PageControl();

        if (name != "PageControl") {            
            if (control.caption == null) {
                control.imageCell.style.textAlign = "center";
                control.innerTable.style.width = "100%";
                control.style.width = this.options.isMobileDevice ? "0.4in" : "35px";
            }
            if (control.toolTip) {
                var positions = { top: "isNavigatePanelTooltip" }
                if (name == "Zoom" || name == "ZoomPageWidth" || name == "ZoomOnePage") {
                    positions.rightToLeft = true;
                }
                control.toolTip.push(positions);
            }
        }
        else {
            control.textBox.style.border = "0px";
        }
        if (control.arrow) control.arrow.src = this.collections.images["ButtonArrowUp.png"];
        if (name == "FirstPage") control.style.margin = "0 1px 0 3px";
        else if (name == "Zoom") control.style.margin = "0 3px 0 1px";
        else control.style.margin = "0px 1px 0 1px";

        this.controls.toolbar.controls[name] = control;
        controlsTable.addCell(control);
    }
    
    var disabledPanel = document.createElement("div");    
    navigatePanel.disabledPanel = disabledPanel;
    disabledPanel.className = "stiJsViewerNavigatePanelDisabledPanel";
    navigatePanel.appendChild(disabledPanel);

    navigatePanel.setEnabled = function (state) {
        disabledPanel.style.display = state ? "none" : "";
    }

    navigatePanel.changeVisibleState = function (state) {
        this.visible = state;
        this.style.display = state ? "block" : "none";
    }

    navigatePanel.setEnabled(true);
    
    if (this.options.isMobileDevice) {
        this.controls.toolbar.addEventListener("touchstart", function () { navigatePanel.jsObject.controls.reportPanel.keepToolbar(); });
        navigatePanel.addEventListener("touchstart", function () { navigatePanel.jsObject.controls.reportPanel.keepToolbar(); });
        this.controls.reportPanel.showToolbar();
    }
}

//Separator
StiJsViewer.prototype.NavigatePanelSeparator = function () {
    var separator = document.createElement("div");
    separator.style.height = this.options.isMobileDevice ? "0.5in" : "35px";
    separator.className = "stiJsViewerNavigatePanelSeparator";

    return separator;
}

//Navigate Button
StiJsViewer.prototype.NavigateButton = function (name, caption, imageName, toolTip, arrowType) {
    var button = this.SmallButton(name, caption, imageName, toolTip, arrowType, "stiJsViewerNavigateButton");
    button.style.height = this.options.isMobileDevice ? "0.5in" : "35px";
    button.style.boxSizing = "border-box";
    if (button.arrow) button.arrow.style.marginTop = "1px";

    return button;
}

var StiBase64 = {
	_keyStr : "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=",

	encode : function (input) {
		
        // Decode from UTF-8 text
        if (typeof unescape != 'undefined') {
            input = unescape(encodeURIComponent(input));
        }
        else {
            input = input.replace(/\r\n/g, "\n");
            var utftext = "";
            for (var n = 0; n < input.length; n++) {
                var c = input.charCodeAt(n);

                if (c < 128) {
                    utftext += String.fromCharCode(c);
                }
                else if ((c > 127) && (c < 2048)) {
                    utftext += String.fromCharCode((c >> 6) | 192);
                    utftext += String.fromCharCode((c & 63) | 128);
                }
                else {
                    utftext += String.fromCharCode((c >> 12) | 224);
                    utftext += String.fromCharCode(((c >> 6) & 63) | 128);
                    utftext += String.fromCharCode((c & 63) | 128);
                }
            }

            input = utftext;
        }
        
        // Encode to Base64 string
        if (typeof window.btoa != 'undefined') return window.btoa(input);
            
        var output = "";
        var chr1, chr2, chr3, enc1, enc2, enc3, enc4;
        var i = 0;

        while (i < input.length) {
            chr1 = input.charCodeAt(i++);
            chr2 = input.charCodeAt(i++);
            chr3 = input.charCodeAt(i++);

            enc1 = chr1 >> 2;
            enc2 = ((chr1 & 3) << 4) | (chr2 >> 4);
            enc3 = ((chr2 & 15) << 2) | (chr3 >> 6);
            enc4 = chr3 & 63;

            if (isNaN(chr2)) enc3 = enc4 = 64;
            else if (isNaN(chr3)) enc4 = 64;

            output = output +
                this._keyStr.charAt(enc1) + this._keyStr.charAt(enc2) +
                this._keyStr.charAt(enc3) + this._keyStr.charAt(enc4);
        }
 
		return output;
    },

    decode: function (input) {
        var output = "";

        // Decode from Base64 string
        if (typeof window.atob != 'undefined') {
            output = window.atob(input);
        }
        else {
            var chr1, chr2, chr3;
            var enc1, enc2, enc3, enc4;
            var i = 0;

            input = input.replace(/[^A-Za-z0-9\+\/\=]/g, "");
            while (i < input.length) {
                enc1 = this._keyStr.indexOf(input.charAt(i++));
                enc2 = this._keyStr.indexOf(input.charAt(i++));
                enc3 = this._keyStr.indexOf(input.charAt(i++));
                enc4 = this._keyStr.indexOf(input.charAt(i++));

                chr1 = (enc1 << 2) | (enc2 >> 4);
                chr2 = ((enc2 & 15) << 4) | (enc3 >> 2);
                chr3 = ((enc3 & 3) << 6) | enc4;

                output = output + String.fromCharCode(chr1);

                if (enc3 != 64) {
                    output = output + String.fromCharCode(chr2);
                }
                if (enc4 != 64) {
                    output = output + String.fromCharCode(chr3);
                }
            }
        }

        // Encode to UTF-8 string
        if (typeof escape != 'undefined') return decodeURIComponent(escape(output));
        
        var string = "";
        var i = 0;
        var c = c1 = c2 = 0;

        while (i < output.length) {
            c = output.charCodeAt(i);

            if (c < 128) {
                string += String.fromCharCode(c);
                i++;
            }
            else if ((c > 191) && (c < 224)) {
                c2 = output.charCodeAt(i + 1);
                string += String.fromCharCode(((c & 31) << 6) | (c2 & 63));
                i += 2;
            }
            else {
                c2 = output.charCodeAt(i + 1);
                c3 = output.charCodeAt(i + 2);
                string += String.fromCharCode(((c & 15) << 12) | ((c2 & 63) << 6) | (c3 & 63));
                i += 3;
            }
        }

        return string;
	}
}



StiJsViewer.prototype.InitializeResourcesPanel = function () {    
    var resourcesPanel = document.createElement("div");
    this.controls.resourcesPanel = resourcesPanel;
    this.controls.mainPanel.appendChild(resourcesPanel);
    resourcesPanel.style.display = "none";
    resourcesPanel.style.zIndex = "3";
    resourcesPanel.visible = false;
    resourcesPanel.style.fontFamily = this.options.toolbar.fontFamily;
    if (this.options.toolbar.fontColor != "") resourcesPanel.style.color = this.options.toolbar.fontColor;
    resourcesPanel.id = this.controls.viewer.id + "_ResourcesPanel";
    resourcesPanel.className = "stiJsViewerToolBar";
    if (this.options.toolbar.displayMode == "Separated") resourcesPanel.className += " stiJsViewerToolBarSeparated";
    resourcesPanel.jsObject = this;

    var innerPanel = document.createElement("div");
    resourcesPanel.appendChild(innerPanel);
    if (this.options.toolbar.displayMode == "Simple") innerPanel.style.paddingTop = "2px";

    var innerBlock = document.createElement("div");
    innerPanel.appendChild(innerBlock);
    innerBlock.className = "stiJsViewerToolBarTable";
    if (this.options.toolbar.displayMode == "Separated") innerBlock.style.border = "0px";
    innerBlock.style.boxSizing = "border-box";
    innerBlock.style.display = "table";

    resourcesPanel.changeVisibleState = function (state) {
        var isStateChanged = this.visible != state;
        this.style.display = state ? "" : "none";
        this.visible = state;

        if (this.jsObject.options.toolbar.visible && this.jsObject.options.toolbar.showResourcesButton) this.jsObject.controls.toolbar.controls.Resources.setSelected(state);

        if (isStateChanged) this.jsObject.updateLayout();
    }

    resourcesPanel.update = function () {
        this.clearResources();
        
        if (this.jsObject.options.toolbar.visible && this.jsObject.options.toolbar.showResourcesButton) {
            this.jsObject.controls.toolbar.controls.Resources.setEnabled(this.jsObject.reportParams.resources != null);
        }

        if (this.jsObject.reportParams.resources) {
            var innerTable = this.jsObject.CreateHTMLTable();
            innerBlock.appendChild(innerTable);

            for (var i = 0; i < this.jsObject.reportParams.resources.length; i++) {
                var resource = this.jsObject.reportParams.resources[i];
                var captionText = resource.name + "<br>" + this.jsObject.GetHumanFileSize(resource.size, 1);
                var button = this.jsObject.ResourceButton(resource.name, captionText, this.jsObject.GetResourceImage(resource.type), resource.type);
                innerTable.addCell(button);
            }
        }

        this.changeVisibleState(this.jsObject.reportParams.resources != null);
    }

    resourcesPanel.clearResources = function () {
        while (innerBlock.childNodes[0]) {
            innerBlock.removeChild(innerBlock.childNodes[0]);
        }
    }
}

StiJsViewer.prototype.ResourceButton = function (name, captionText, imageName, resourceType) {
    var button = this.SmallButton(name, captionText, imageName, this.collections.loc["ButtonView"] + " " + name, null, "stiJsViewerFormButton");
    button.style.height = "auto";
    button.resourceType = resourceType;
    button.style.margin = "3px 0 3px 3px";
    var dropDownButton = this.SmallButton(null, null, "ButtonArrowDown.png", null, null, "stiJsViewerResourceDropDownButton");
    dropDownButton.style.height = dropDownButton.style.width = this.options.isTouchDevice ? "23px" : "17px";
    dropDownButton.style.margin = "0 7px 0 3px"; 
    dropDownButton.innerTable.style.width = "100%";
    dropDownButton.imageCell.style.textAlign = "center";
    if (!this.options.jsMode) button.innerTable.addCell(dropDownButton).style.width = "1px";
    button.innerTable.style.width = "100%";
    button.style.minWidth = "80px";

    if (button.caption) {
        button.caption.style.textAlign = "left";
        button.caption.style.paddinLeft = "3px";
        button.caption.style.maxWidth = "150px";
        button.caption.style.lineHeight = "14px";
        button.caption.style.whiteSpace = "nowrap";
        button.caption.style.overflow = "hidden";
        button.caption.style.textOverflow = "ellipsis";
    }

    if (button.imageCell) {
        button.imageCell.style.width = "1px";
        button.imageCell.style.padding = "4px 8px 4px 4px";
    }

    var items = [];
    items.push(this.Item("View", this.collections.loc["ButtonView"], null, "View"));
    items.push(this.Item("SaveFile", this.collections.loc["SaveFile"], null, "SaveFile"));

    var resourceMenu = this.VerticalMenu(name + "_ResourceMenu", dropDownButton, "Down", items);

    resourceMenu.action = function (menuItem) {
        resourceMenu.changeVisibleState(false);
        this.jsObject.postReportResource(button.name, menuItem.key);
    }

    button.action = function () {
        if (!dropDownButton.clicked) {
            var resTypesAllowedViewInBrowser = ["Image", "Pdf", "Txt" ];
            var viewType = resTypesAllowedViewInBrowser.indexOf(button.resourceType) >= 0 ? "View" : "SaveFile";
            this.jsObject.postReportResource(button.name, this.jsObject.options.jsMode ? "SaveFile" : viewType);
        }
        dropDownButton.clicked = false;
    }

    button.onmouseup = function (event) {
        if (event.button == 2) {
            resourceMenu.changeVisibleState(true);
        }
    }

    button.oncontextmenu = function (event) {
        return false;
    }

    dropDownButton.action = function () {
        resourceMenu.changeVisibleState(!resourceMenu.visible);
        dropDownButton.clicked = true;
    }

    return button;
}

StiJsViewer.prototype.GetResourceImage = function (resourceType) {
    if (this.collections.images["BigResource" + resourceType + ".png"])
        return "BigResource" + resourceType + ".png";
    else
        return "BigResource.png";
}


StiJsViewer.prototype.InitializeDashboardsPanel = function () {
    var dashboardsPanel = document.createElement("div");
    this.controls.dashboardsPanel = dashboardsPanel;
    this.controls.mainPanel.appendChild(dashboardsPanel);
    dashboardsPanel.style.fontFamily = this.options.toolbar.fontFamily;
    if (this.options.toolbar.fontColor != "") dashboardsPanel.style.color = this.options.toolbar.fontColor;
    dashboardsPanel.className = "stiJsViewerToolBar";
    if (this.options.toolbar.displayMode == "Separated") dashboardsPanel.className += " stiJsViewerToolBarSeparated";
    var jsObject = dashboardsPanel.jsObject = this;
    dashboardsPanel.style.display = "none";
    dashboardsPanel.visible = false;

    var innerPanel = document.createElement("div");
    dashboardsPanel.appendChild(innerPanel);
    if (this.options.toolbar.displayMode == "Simple") innerPanel.style.paddingTop = "2px";

    // Inner content panel
    var panelTable = this.CreateHTMLTable();
    innerPanel.appendChild(panelTable);
    dashboardsPanel.panelTable = panelTable;
    panelTable.className = "stiJsViewerToolBarTable";
    if (this.options.toolbar.displayMode == "Separated") panelTable.style.border = "0px";
    panelTable.style.margin = 0;
    panelTable.style.boxSizing = "border-box";

    // Left and right content tables
    var cell1 = panelTable.addCell();
    var cell2 = panelTable.addCell();
    var mainCell = (!this.options.appearance.rightToLeft) ? cell1 : cell2;
    var actionsCell = (!this.options.appearance.rightToLeft) ? cell2 : cell1;
    mainCell.style.width = "100%";
    var mainTable = this.CreateHTMLTable();

    var actionsTable = this.CreateHTMLTable();
    mainCell.appendChild(mainTable);
    actionsCell.appendChild(actionsTable);

    mainTable.setAttribute("align", this.options.appearance.rightToLeft ? "right" : (this.options.toolbar.alignment == "default" ? "left" : this.options.toolbar.alignment));
    actionsTable.style.marginRight = "2px";
    dashboardsPanel.actionsTable = actionsTable;
    var imagesPath = "Dashboards.Actions.Light.";

    // Refresh Dashboard menu button
    if (this.options.toolbar.showRefreshButton && this.options.toolbar.visible) {
        var buttonRefresh = this.SmallButton("RefreshDashboard", null, imagesPath + "Refresh.png", this.collections.loc["Refresh"]);
        buttonRefresh.jsObject = this;        
        buttonRefresh.style.margin = "2px 0 2px 2px";
        buttonRefresh.action = function () {
            this.jsObject.postAction("Refresh");
        };
        actionsTable.addCell(buttonRefresh);
    }

    // Open Dashboard button
    if (this.options.toolbar.showOpenButton && this.options.toolbar.visible) {
        var buttonOpen = this.SmallButton("OpenDashboard", null, imagesPath + "Open.png", this.collections.loc["Open"]);
        buttonOpen.style.margin = "2px 0 2px 2px";
        buttonOpen.action = function () {
            var openDashboardDialog = jsObject.InitializeOpenDialog("openDashboardDialog", function (fileName, filePath, content) {
                jsObject.postOpen(fileName, content);
            }, ".mdc,.mdz,.mdx,.mrt,.mrz,.mrx");
            openDashboardDialog.action();
        };
        actionsTable.addCell(buttonOpen);
    }

    // Edit button
    if (this.options.toolbar.showDesignButton && this.options.toolbar.visible) {
        var buttonEdit = this.SmallButton("EditDashboard", null, imagesPath + "Edit.png", this.collections.loc["Edit"]);
        buttonEdit.style.margin = "2px 0px 2px 2px";
        buttonEdit.action = function () {
            jsObject.postDesign();
        };
        actionsTable.addCell(buttonEdit);
    }

    // FullScreen button
    if (this.options.toolbar.showFullScreenButton && this.options.toolbar.visible) {
        var buttonFullScreen = this.SmallButton("FullScreenDashboard", jsObject.collections.loc.Close, imagesPath + "CloseFullScreen.png", this.collections.loc["FullScreen"]);
        buttonFullScreen.style.margin = "2px 0 2px 2px";
        buttonFullScreen.action = function () {
            jsObject.postAction("FullScreen");
            jsObject.postAction("GetPages");
        };
        buttonFullScreen.setFullScreenState = function (state) {
            this.caption.style.display = state ? "" : "none";
            this.imageName = state ? this.imageName.replace("Open", "Close") : this.imageName.replace("Close", "Open");
            this.image.src = jsObject.collections.images[this.imageName];
        }
        actionsTable.addCell(buttonFullScreen);
    }    

    // Export Dashboard menu button
    if (this.options.toolbar.showSaveButton && this.options.toolbar.visible) {
        var buttonExport = this.SmallButton("ExportDashboard", null, imagesPath + "Menu.png", this.collections.loc["Save"]);
        buttonExport.style.margin = "2px 0 2px 2px";
        buttonExport.action = function () {
            var menuStyle = this.isDarkStyle ? "stiJsViewerDbsDarkMenu" : "stiJsViewerDbsLightMenu";
            var saveMenu = this.jsObject.InitializeSaveDashboardMenu(menuStyle + "Item", menuStyle, false);
            saveMenu.changeVisibleState(true, this);
        };
        actionsTable.addCell(buttonExport);
    }    
    // Panel methods

    dashboardsPanel.changeVisibleState = function (state) {
        this.visible = state;
        this.style.display = state ? "" : "none";
    }    

    var dbsToolButtons = ["RefreshDashboard", "ExportDashboard", "FullScreenDashboard", "OpenDashboard", "EditDashboard"];

    dashboardsPanel.update = function (dashboards, previewSettings) {
        if (!dashboards || dashboards.length == 0) return;
        this.clear();
        this.dashboardsCount = 0;
        this.reportsCount = 0;
        this.buttons = [];
        for (var index in dashboards) {
            var info = dashboards[index];
            var button = jsObject.DashboardPanelButton(dashboardsPanel, "button" + (mainTable.cellsCount() + 1), info.name);
            var showToolbar = previewSettings ? previewSettings.dashboardToolBar : jsObject.options.toolbar.visible;
            button.style.display = showToolbar && !info.isNestedPage ? "" : "none";
            this.buttons.push(button);

            button.reportParams = index == 0 ? jsObject.reportParams : {};
            button.reportParams.type = info.type;
            button.reportParams[jsObject.options.toolbar.zoom < 0 ? "autoZoom" : "zoom"] = jsObject.options.toolbar.zoom;
            button.reportParams.pageNumber = info.type == "Dashboard" ? info.index : 0;
            button.reportParams.viewMode = jsObject.reportParams.viewMode;

            if (info.valid) button.isValid = true;

            if (info.type == "Dashboard")
                this.dashboardsCount++;
            else
                this.reportsCount++;

            button.action = function () {
                if (!this.closeButtonAction) {
                    this.select();
                    jsObject.reportParams = this.reportParams;
                    jsObject.reportParams.dashboardDrillDownGuid = null;
                    jsObject.postAction("Refresh");
                }
            };

            mainTable.addCell(button);
            if (index == 0) button.select();
        }

        var dbsMode = this.dashboardsCount > 0 && this.reportsCount == 0;
        dashboardsPanel.style.background = dbsMode ? "transparent" : "";
        dashboardsPanel.style.borderColor = dbsMode ? "transparent" : "";
        panelTable.style.background = dbsMode ? "transparent" : "";
        panelTable.style.borderColor = dbsMode ? "transparent" : "";

        if (this.dashboardsCount == 1 && this.buttons.length == 1) {
            this.buttons[0].style.display = "none";
        }

        for (var i = 0; i < this.buttons.length; i++) {
            this.buttons[i].style.borderColor = !dbsMode ? "transparent" : "";
            if (jsObject.options.toolbar.displayMode == "Separated") {
                this.buttons[i].style.height = dbsMode ? (jsObject.options.isTouchDevice ? "28px" : "23px") : "28px";
            }
        }
        
        for (var i = 0; i < dbsToolButtons.length; i++) {
            var button = jsObject.controls.buttons[dbsToolButtons[i]];
            if (button && jsObject.options.toolbar.displayMode == "Separated") {
                button.style.height = dbsMode ? (jsObject.options.isTouchDevice ? "28px" : "23px") : "28px";
                if (!button.caption) button.style.width = button.style.height;
                button.innerTable.style.width = "100%";
                button.imageCell.style.textAlign = "center";
            }
        }

        if (previewSettings) {
            var buttons = jsObject.controls.buttons;
            if (buttons.RefreshDashboard) buttons.RefreshDashboard.style.display = previewSettings.dashboardToolBar && previewSettings.dashboardRefreshButton ? "" : "none";
            if (buttons.OpenDashboard) buttons.OpenDashboard.style.display = previewSettings.dashboardToolBar && previewSettings.dashboardOpenButton ? "" : "none";
            if (buttons.EditDashboard) buttons.EditDashboard.style.display = previewSettings.dashboardToolBar && previewSettings.dashboardEditButton ? "" : "none";
            if (buttons.FullScreenDashboard) buttons.FullScreenDashboard.style.display = previewSettings.dashboardToolBar && previewSettings.dashboardFullScreenButton ? "" : "none";
            if (buttons.ExportDashboard) buttons.ExportDashboard.style.display = previewSettings.dashboardToolBar && previewSettings.dashboardMenuButton ? "" : "none";
        }

        this.changeVisibleState(true);
        jsObject.updateLayout();
    }    

    dashboardsPanel.addDrillDownButton = function (dashboardDrillDownGuid, drillDownGuid, drillDownParameters, previewSettings, drillDownReportFileName) {

        //select if button already exists
        for (var i = 0; i < this.buttons.length; i++) {
            var reportParams = this.buttons[i].reportParams;
            if ((dashboardDrillDownGuid && reportParams.dashboardDrillDownGuid == dashboardDrillDownGuid) || (drillDownGuid && reportParams.drillDownGuid == drillDownGuid)) {
                this.buttons[i].select();
                jsObject.reportParams = reportParams;
                return;
            }
        }

        //create new if button not exists
        var caption = drillDownReportFileName || jsObject.collections.loc["Report"] || "Report";

        if (!drillDownGuid && dashboardDrillDownGuid && drillDownParameters && drillDownParameters.length > 0) {
            var dashboardDrillDownParameters = drillDownParameters[drillDownParameters.length - 1];

            //dbs drilldown
            caption = dashboardDrillDownParameters.value;

            if (dashboardDrillDownParameters) {
                for (var i = 0; i < dashboardDrillDownParameters.parameters.length; i++) {
                    var key = dashboardDrillDownParameters.parameters[i].key;
                    if (key && key.toLowerCase() == "title") {
                        caption = dashboardDrillDownParameters.parameters[i].value;
                        break;
                    }
                }
            }
            if (!caption) {
                caption = drillDownReportFileName || jsObject.collections.loc["Dashboard"];
            }
        }

        var dbsMode = this.dashboardsCount > 0 && this.reportsCount == 0;
        var button = jsObject.DashboardPanelButton(dashboardsPanel, "button" + (dashboardDrillDownGuid || drillDownGuid), caption, true);
        this.buttons.push(button);

        if (jsObject.options.toolbar.displayMode == "Separated") {
            button.style.height = dbsMode ? (jsObject.options.isTouchDevice ? "28px" : "23px") : "28px";
        }

        button.reportParams = {
            type: dashboardDrillDownGuid ? "Dashboard" : "Report",
            pageNumber: 0,
            viewMode: jsObject.reportParams.viewMode,
            drillDownGuid: drillDownGuid,
            dashboardDrillDownGuid: dashboardDrillDownGuid,
            drillDownParameters: drillDownParameters
        };

        button.reportParams[jsObject.options.toolbar.zoom < 0 ? "autoZoom" : "zoom"] = jsObject.options.toolbar.zoom;

        jsObject.reportParams = button.reportParams;

        if (this.selectedButton) button.isValid = this.selectedButton.isValid;

        button.action = function () {
            if (!this.closeButtonAction) {
                button.select();
                jsObject.reportParams = this.reportParams;
                jsObject.postInteraction({ action: this.reportParams.drillDownGuid ? "DrillDown" : "DashboardDrillDown" });
            }
        };

        mainTable.addCell(button);
        button.select();

        var showToolbar = previewSettings ? previewSettings.dashboardToolBar : jsObject.options.toolbar.visible;
        button.style.display = showToolbar ? "" : "none";
    }

    dashboardsPanel.updateButtonsStyles = function (styleColors, hasReports) {
        if (hasReports) styleColors = null;
        var isDarkStyle = styleColors && styleColors.isDarkStyle;
        for (var i = 0; i < this.buttons.length; i++) {
            var button = this.buttons[i];
            button.isDarkStyle = isDarkStyle;
            button.applyStyleColors(styleColors);

            //correct styles for AliceBlue style
            if (styleColors && styleColors.styleName == "AliceBlue") {
                var styleColors_ = jsObject.copyObject(styleColors);
                styleColors_.foreColor = "#e4ffff";
                styleColors_.hotForeColor = "#e4ffff";
                styleColors_.hotSelectedForeColor = "#e4ffff";
                button.applyStyleColors(styleColors_);
            }

            //correct styles for close button
            var closeButton = button.closeButton;
            if (closeButton && closeButton.image) {
                var styleColors__ = null;
                if (styleColors) {
                    styleColors__ = jsObject.copyObject(styleColors);
                    styleColors__["backColor"] = "transparent";
                }
                closeButton.applyStyleColors(styleColors__);
                closeButton.imageName = button.isDarkStyle ? closeButton.imageName.replace(".Light.", ".Dark.") : closeButton.imageName.replace(".Dark.", ".Light.");
                closeButton.image.src = jsObject.collections.images[closeButton.imageName];
            }
        }
        for (var i = 0; i < dbsToolButtons.length; i++) {
            var button = jsObject.controls.buttons[dbsToolButtons[i]];
            if (button) {
                button.isDarkStyle = isDarkStyle;
                button.applyStyleColors(styleColors);
                if (button.image) {
                    button.imageName = button.isDarkStyle ? button.imageName.replace(".Light.", ".Dark.") : button.imageName.replace(".Dark.", ".Light.");
                    button.image.src = jsObject.collections.images[button.imageName];
                }
            }
        }
        if (jsObject.controls.parametersPanel && jsObject.controls.parametersPanel.visible && styleColors) {
            jsObject.controls.parametersPanel.style.color = styleColors.styleName == "AliceBlue" ? "#e4ffff" : styleColors.foreColor;
            jsObject.controls.parametersPanel.mainButtons.submit.style.color = jsObject.controls.parametersPanel.mainButtons.reset.style.color = "#444444";
        }
    }

    dashboardsPanel.clear = function () {
        mainTable.clearRow();
        this.selectedButton = null;
    }
}

StiJsViewer.prototype.DashboardPanelButton = function (dashboardsPanel, name, caption, showCloseButton) {
    var button = this.SmallButton(name, caption);
    button.panel = this;
    button.style.margin = "2px 1px 2px 2px";

    button.select = function () {
        if (dashboardsPanel.selectedButton)
            dashboardsPanel.selectedButton.setSelected(false);
        dashboardsPanel.selectedButton = this;
        this.setSelected(true);
    }

    if (showCloseButton) {
        var closeButton = this.SmallButton(null, null, "Dashboards.Actions.Light.Close.png");
        button.closeButton = closeButton;
        closeButton.style.display = "inline-block";
        closeButton.style.padding = "0";
        closeButton.style.margin = "3px 2px 0 0";
        closeButton.imageCell.style.padding = 0;
        closeButton.imageCell.style.textAlign = "center";
        closeButton.style.width = this.options.isTouchDevice ? "22px" : "16px";
        closeButton.style.height = closeButton.style.width;
        button.innerTable.addCell(closeButton);

        closeButton.action = function () {
            button.closeButtonAction = true;
            if (dashboardsPanel.buttons.indexOf(button) >= 0) {
                dashboardsPanel.buttons.splice(dashboardsPanel.buttons.indexOf(button), 1);
            }
            button.parentElement.parentElement.removeChild(button.parentElement);
            if (dashboardsPanel.selectedButton == button && dashboardsPanel.buttons.length > 0) dashboardsPanel.buttons[0].action();
        };

        closeButton.onmouseenter = function (event) {
            button.onmouseoutAction();
            this.onmouseoverAction();
            if (event) event.stopPropagation();
        }
    }

    return button;
}

StiJsViewer.prototype.InitializeEvents = function () {
    var jsObject = this;
    var viewer = this.controls.viewer;

    if (viewer && viewer.offsetWidth && viewer.offsetHeight) {
        jsObject.service.widthBeforeResize = viewer.offsetWidth;
        jsObject.service.heightBeforeResize = viewer.offsetHeight;
    }

    var resizeEvent = function (e) {
        if (jsObject.reportParams.type == "Dashboard") {
            if (jsObject.service.resizeTimer) clearTimeout(jsObject.service.resizeTimer);
            jsObject.service.resizeTimer = setTimeout(function () {
                if (jsObject.options.jsDesigner && !jsObject.options.jsDesigner.options.previewMode ||
                    !viewer || !viewer.offsetWidth || !viewer.offsetHeight) return;

                if (jsObject.service.widthBeforeResize != viewer.offsetWidth || jsObject.service.heightBeforeResize != viewer.offsetHeight) {
                    jsObject.service.widthBeforeResize = viewer.offsetWidth;
                    jsObject.service.heightBeforeResize = viewer.offsetHeight;
                    jsObject.postAction("GetPages");
                }
            }, 300);
        }
    }

    this.addEvent(window, "resize", resizeEvent);
}

StiJsViewer.prototype.AddDashboardElementToPage = function (page, elementAttributes) {
    var jsObject = this;
    var element = document.createElement("div");
    element.elementAttributes = elementAttributes;
    element.buttons = {};
    element.style.display = "inline-block";
    element.style.position = "absolute";
    element.style.overflow = "hidden";
    element.style.top = elementAttributes.top + "px";
    element.style.left = elementAttributes.left + "px";
    element.style.width = elementAttributes.width + "px";
    element.style.height = elementAttributes.height + "px";
    element.style.margin = elementAttributes.margin.split(",").join("px ") + "px";
    element.style.backgroundColor = elementAttributes.backColor;
    element.style.boxSizing = "border-box";
    page.appendChild(element);
        
    if (!this.isFilterElement(element.elementAttributes.type)) {
        var imagesPath = "Dashboards.Actions." + (element.elementAttributes.actionColors && element.elementAttributes.actionColors.isDarkStyle ? "Dark." : "Light.");

        //filters string panel
        var filtersStringPanel = document.createElement("div");
        filtersStringPanel.className = "stiJsViewerDashboardElementButtonsPanel";
        filtersStringPanel.element = element;
        element.filtersStringPanel = filtersStringPanel;
        element.appendChild(filtersStringPanel);

        filtersStringPanel.checkVisibleState = function () {
            this.style.opacity = this.element.isMouseOver ? 0 : 0.9;
        }

        //buttons panel
        var buttonsPanel = document.createElement("div");
        buttonsPanel.className = "stiJsViewerDashboardElementButtonsPanel";
        buttonsPanel.element = element;
        element.buttonsPanel = buttonsPanel;
        element.appendChild(buttonsPanel);

        buttonsPanel.checkVisibleState = function () {
            this.style.opacity = this.element.isMouseOver ? 0.9 : 0;
        }

        var buttonsTable = this.CreateHTMLTable();
        buttonsPanel.appendChild(buttonsTable);
        buttonsTable.className = "stiJsViewerToolBarTable";
        buttonsTable.style.border = 0;
        buttonsTable.style.margin = 0;
        buttonsTable.style.background = "transparent";
        buttonsTable.style.boxSizing = "border-box";               

        // MultiFilter button
        var buttonMultiFilter = this.SmallButton(null, null, imagesPath + "FilterMultiOptionOff.png", this.collections.loc["FilterMode"], null, null, elementAttributes.actionColors);
        buttonMultiFilter.isChecked = false;
        buttonsTable.addCell(buttonMultiFilter);
        element.buttons.multiFilter = buttonMultiFilter;

        buttonMultiFilter.setChecked = function (state) {
            this.isChecked = state;
            this.image.src = jsObject.collections.images[imagesPath + "FilterMultiOption" + (state ? "On" : "Off") + ".png"];
        };

        buttonMultiFilter.action = function () {
            this.setChecked(!this.isChecked);
            var options = jsObject.options;

            if (!options.multiFilterStates) {
                options.multiFilterStates = {};
            }
            if (this.isChecked) {
                options.multiFilterStates[elementAttributes.name] = true;
            }
            else {
                delete options.multiFilterStates[elementAttributes.name];
            }
        };

        // RemoveFilter button
        var buttonRemoveFilter = this.SmallButton(null, null, imagesPath + "RemoveFilter.png", this.collections.loc["RemoveFilter"], null, null, elementAttributes.actionColors);
        buttonsTable.addCell(buttonRemoveFilter);
        element.buttons.removeFilter = buttonRemoveFilter;

        buttonRemoveFilter.action = function () {
            this.style.display = "none";
            buttonMultiFilter.style.display = "none";

            if (element["resetAllSelectedGeoms"]) {
                element.resetAllSelectedGeoms();
            }

            if (element.elementAttributes && element.elementAttributes.contentAttributes) {
                element.elementAttributes.contentAttributes.filtersString = "";
                jsObject.UpdateFiltersStringPanel(element);
            }

            jsObject.ApplyFiltersToDashboardElement(element, []);            
        };

        //DrillDown Buttons
        var contentAttrs = elementAttributes.contentAttributes;
        if (contentAttrs.interaction && contentAttrs.interaction.allowUserDrillDown) {
            var buttonsProps = [
                ["drillDownSelected", this.collections.loc["DrillDownSelected"], null, null],
                ["drillDownCancel", this.collections.loc["ButtonCancel"], null, null],
                ["drillUp", null, imagesPath + "DrillUp.png", this.collections.loc["DrillUp"]],
                ["drillDown", null, imagesPath + "DrillDown.png", this.collections.loc["DrillDown"]]
            ];
            
            for (var i = 0; i < buttonsProps.length; i++) {
                var button = this.SmallButton(null, buttonsProps[i][1], buttonsProps[i][2], buttonsProps[i][3], null, null, elementAttributes.actionColors);
                element.buttons[buttonsProps[i][0]] = button;
                buttonsTable.addCell(button);

                if (buttonsProps[i][0] == "drillDownSelected" || buttonsProps[i][0] == "drillDownCancel") {
                    button.style.marginLeft = "4px";
                    button.showBorders = true;
                    button.applyStyleColors(elementAttributes.actionColors);
                }
            }

            element.buttons.drillDownSelected.action = function () {
                element.isDrillSelectionActivated = false;
                jsObject.ApplyDrillDownToDashboardElement(element, element.getFilters());
            }

            element.buttons.drillDownCancel.action = function () {
                element.isDrillSelectionActivated = false;
                element.updateSelectedGeoms();
                jsObject.UpdateButtonsPanel(element);
            }

            element.buttons.drillUp.action = function () {
                element.isDrillSelectionActivated = false;
                jsObject.ApplyDrillUpToDashboardElement(element);
            }

            element.buttons.drillDown.action = function () {
                element.isDrillSelectionActivated = true;
                jsObject.UpdateButtonsPanel(element);
            }
        }

        // FullScreen element button
        var buttonFullScreen = this.SmallButton(null, this.collections.loc.Close, imagesPath + "CloseFullScreen.png", this.collections.loc["FullScreenToolTip"], null, null, elementAttributes.actionColors);
        buttonFullScreen.jsObject = this;
        buttonFullScreen.buttonsPanel = buttonsPanel;
        buttonFullScreen.elementName = elementAttributes.name;

        buttonFullScreen.action = function () {
            this.jsObject.reportParams.elementName = this.jsObject.reportParams.elementName == this.elementName ? null : this.elementName;
            this.jsObject.postAction("GetPages");
        };

        buttonFullScreen.setFullScreenState = function (state) {
            this.caption.style.display = state ? "" : "none";
            this.imageName = state ? this.imageName.replace("Open", "Close") : this.imageName.replace("Close", "Open");
            this.image.src = this.jsObject.collections.images[this.imageName];
        }

        buttonFullScreen.setFullScreenState(this.reportParams.elementName == elementAttributes.name);
        buttonsTable.addCell(buttonFullScreen);
        element.buttons.fullScreen = buttonFullScreen;

        // Export element menu button
        var buttonExport = this.SmallButton(null, null, imagesPath + "Save.png", null, null, null, elementAttributes.actionColors);
        buttonExport.jsObject = this;
        buttonExport.buttonsPanel = buttonsPanel;
        buttonExport.filtersStringPanel = filtersStringPanel;
        buttonExport.elementName = elementAttributes.name;
        buttonExport.elementType = elementAttributes.type;

        buttonExport.action = function () {
            var menuStyle = (elementAttributes.actionColors && elementAttributes.actionColors.isDarkStyle) ? "stiJsViewerDbsDarkMenu" : "stiJsViewerDbsLightMenu";
            var saveMenu = this.jsObject.InitializeSaveDashboardMenu(menuStyle + "Item", menuStyle, true);
            saveMenu.changeVisibleState(true, this);
        };

        buttonExport.setSelectedBase = buttonExport.setSelected;

        buttonExport.setSelected = function (state) {
            buttonExport.setSelectedBase(state);
            this.buttonsPanel.checkVisibleState();
            this.filtersStringPanel.checkVisibleState();
        };

        buttonsTable.addCell(buttonExport);
        element.buttons.export = buttonExport;

        // Events
        element.onmouseover = function () {
            this.isMouseOver = true;
            this.buttonsPanel.checkVisibleState();
            this.filtersStringPanel.checkVisibleState();
        }

        element.onmouseout = function () {
            this.isMouseOver = false;
            if (!this.buttons.export.isSelected) {
                this.buttonsPanel.checkVisibleState();
                this.filtersStringPanel.checkVisibleState();
            }
        }
    }    

    this.PaintDashboardElementBorder(element);
    this.InsertContentToDashboardElement(element);
    this.UpdateButtonsPanel(element);
    this.UpdateFiltersStringPanel(element);

    return element;
}

StiJsViewer.prototype.PaintDashboardElementBorder = function (element) {
    element.style.border = 0;
    var border = element.elementAttributes.border;

    if (border) {
        var size = border.size;
        var styles = ["solid", "dashed", "dashed", "dotted", "dotted", "double", "none"];
        var borderStyle = border.size + "px " + styles[border.style] + " " + border.color;                
        if (border.left) element.style.borderLeft = borderStyle;
        if (border.top) element.style.borderTop = borderStyle;
        if (border.right) element.style.borderRight = borderStyle;
        if (border.bottom) element.style.borderBottom = borderStyle;
    }
}

StiJsViewer.prototype.GetDashboardElementTitleWidth = function (title) {
    var jsObject = this;
    var titleWidth = 0;
    if (title) {
        var measurePanel = document.createElement("div");
        var titleText = StiBase64.decode(title.text);
        var titleFont = title.font;
        measurePanel.style.display = "inline-block";
        this.controls.mainPanel.appendChild(measurePanel);
        measurePanel.innerHTML = titleText;
        measurePanel.style.fontFamily = titleFont.name;
        measurePanel.style.fontSize = jsObject.StrToDouble(titleFont.size) + "pt";
        measurePanel.style.fontWeight = titleFont.bold ? "bold" : "normal";
        measurePanel.style.fontStyle = titleFont.italic ? "italic" : "normal";
        measurePanel.style.textDecoration = "";
        if (titleFont.strikeout) measurePanel.style.textDecoration = "line-through";
        if (titleFont.underline) measurePanel.style.textDecoration += " underline";
        measurePanel.style.whiteSpace = "nowrap";
        measurePanel.style.padding = "3px";
        titleWidth = measurePanel.offsetWidth;
        this.controls.mainPanel.removeChild(measurePanel);
    }
    return titleWidth;
}

StiJsViewer.prototype.PaintDashboardElementTitle = function (element, contentAttrs) {
    var jsObject = this;
    var title = contentAttrs.title;   

    if (title && title.visible) {
        var applyFontToPanel = function (panel, font) {            
            panel.style.fontFamily = font.name;
            panel.style.fontSize = jsObject.StrToDouble(font.size) + "pt";
            panel.style.fontWeight = font.bold ? "bold" : "normal";
            panel.style.fontStyle = font.italic ? "italic" : "normal";
            panel.style.textDecoration = "";
            if (font.strikeout) panel.style.textDecoration = "line-through";
            if (font.underline) panel.style.textDecoration += " underline";
            panel.style.whiteSpace = "nowrap";
            panel.style.padding = "3px";
        }

        var titleText = StiBase64.decode(title.text);
        var titlePanel = document.createElement("div");
        var titleTable = this.CreateHTMLTable();
        titleTable.style.width = titleTable.style.height = "100%";
        titlePanel.appendChild(titleTable);
        titlePanel.style.position = "absolute";
        titlePanel.style.overflow = "hidden";
        titlePanel.style.left = titlePanel.style.top = titlePanel.style.right = "0px";
        titleTable.addTextCell(titleText).style.verticalAlign = "middle";
        titlePanel.style.background = title.backColor;
        titlePanel.style.color = title.foreColor;
        titlePanel.style.textAlign = title.horAlignment.toLowerCase();
        applyFontToPanel(titlePanel, title.font);
        element.appendChild(titlePanel);
        element.titlePanel = titlePanel;

        var measurePanel = document.createElement("div");
        measurePanel.style.display = "inline-block";
        this.controls.mainPanel.appendChild(measurePanel);
        measurePanel.innerHTML = titleText;
        applyFontToPanel(measurePanel, title.font);
        var factorX = measurePanel.offsetWidth > titlePanel.offsetWidth && measurePanel.offsetWidth != 0 ? (titlePanel.offsetWidth - 6) / measurePanel.offsetWidth : 1;
        var factorY = measurePanel.offsetHeight > titlePanel.offsetHeight && measurePanel.offsetHeight != 0 ? (titlePanel.offsetHeight - 6) / measurePanel.offsetHeight : 1;
        var factor = Math.min(Math.abs(factorX), Math.abs(factorY));

        titlePanel.style.height = titlePanel.offsetHeight + "px";
        titlePanel.style.fontSize = parseFloat(title.font.size.toString()) * factor + "pt";
        this.controls.mainPanel.removeChild(measurePanel);
    }
}

StiJsViewer.prototype.UpdateButtonsPanel = function (element) {
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs ? elementAttrs.contentAttributes : null;

    if (element.buttons.removeFilter) {
        element.buttons.removeFilter.style.display = contentAttrs && contentAttrs.filters && contentAttrs.filters.length > 0 && !element.isDrillSelectionActivated ? "" : "none";
    }

    if (element.buttons.multiFilter) {
        element.buttons.multiFilter.style.display = element.buttons.removeFilter.style.display == "" && !element.isDrillSelectionActivated &&
            (elementAttrs.type == "StiChartElement" || elementAttrs.type == "StiRegionMapElement") ? "" : "none";

        if (this.options.multiFilterStates && this.options.multiFilterStates[elementAttrs.name]) {
            element.buttons.multiFilter.setChecked(true);
        }
    }

    if (element.buttons.fullScreen) {
        element.buttons.fullScreen.style.display = elementAttrs.layout && elementAttrs.layout.fullScreenButton && !element.isDrillSelectionActivated ? "" : "none";
    }

    if (element.buttons.export) {
        element.buttons.export.style.display = elementAttrs.layout && elementAttrs.layout.saveButton && !element.isDrillSelectionActivated ? "" : "none";
    }

    if (contentAttrs.interaction && contentAttrs.interaction.allowUserDrillDown) {
        element.buttons.drillUp.onmouseoutAction();
        element.buttons.drillDown.onmouseoutAction();
        element.buttons.drillDownSelected.onmouseoutAction();
        element.buttons.drillDownCancel.onmouseoutAction();
        element.buttons.drillUp.style.display = !element.isDrillSelectionActivated && contentAttrs.interaction.drillDownCurrentLevel > 0 ? "" : "none";
        element.buttons.drillDown.style.display = !element.isDrillSelectionActivated && contentAttrs.interaction.drillDownCurrentLevel < contentAttrs.interaction.drillDownLevelCount - 1 ? "" : "none";
        element.buttons.drillDownSelected.style.display = element.buttons.drillDownCancel.style.display = element.isDrillSelectionActivated ? "" : "none";
    }
}

StiJsViewer.prototype.UpdateFiltersStringPanel = function (element) {
    var elementAttrs = element.elementAttributes;
    var foreColor = elementAttrs.actionColors.foreColor;
    var contentAttrs = elementAttrs ? elementAttrs.contentAttributes : null;
    var fsPanel = element.filtersStringPanel;

    if (fsPanel) {
        fsPanel.innerHTML = "";
        fsPanel.style.color = foreColor;

        if (contentAttrs && contentAttrs.filtersString) {
            var imagesPath = "Dashboards.Actions." + (elementAttrs.actionColors && elementAttrs.actionColors.isDarkStyle ? "Dark." : "Light.");
            var textCont = document.createElement("div");
            textCont.className = "stiJsViewerFiltersStringText";
            textCont.innerHTML = contentAttrs.filtersString;
            var table = this.CreateHTMLTable();
            table.addCell(textCont);
            var img = document.createElement("img");
            img.src = this.collections.images[imagesPath + "Filter.png"];
            table.addCell(img).style.paddingLeft = "5px";
            fsPanel.appendChild(table);
            var textWidth = elementAttrs.width - 40;
            var title = contentAttrs.title;

            if (title) {
                if (title.visible && title.text) {
                    var titleWidth = this.GetDashboardElementTitleWidth(title);
                    if (title.horAlignment == "Left") {
                        textWidth = elementAttrs.width - titleWidth - 40;
                        fsPanel.style.right = "5px";
                        fsPanel.style.left = "auto";
                    }
                    else if (title.horAlignment == "Center") {
                        textWidth = (elementAttrs.width - titleWidth) / 2 - 40;
                        fsPanel.style.right = "5px";
                        fsPanel.style.left = "auto";
                    }
                    else if (title.horAlignment == "Right") {
                        textWidth = elementAttrs.width - titleWidth - 40;
                        fsPanel.style.right = "auto";
                        fsPanel.style.left = "5px";
                    }
                }
                else {
                    textWidth = 0;
                    fsPanel.style.display = "none";
                }
            }

            textCont.style.maxWidth = (textWidth > 70 ? textWidth : 0) + "px";
        }

        fsPanel.checkVisibleState();
    }
}

StiJsViewer.prototype.InsertContentToDashboardElement = function (element) {
    var jsObject = this;
    var elementType = element.elementAttributes.type;
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;

    var oldScrollTop = element.itemsPanel ? element.itemsPanel.scrollTop : 0;    
    if (elementType == "StiTableElement" && element.dataGrid) element.dataGrid.saveGridStates();

    //remove filtersStringPanel from position
    if (element.filtersStringPanel) element.removeChild(element.filtersStringPanel);

    //remove buttonsPanel from position
    if (element.buttonsPanel) element.removeChild(element.buttonsPanel);

    //clear old content
    while (element.childNodes[0]) {
        element.removeChild(element.childNodes[0]);
    }

    //svg content
    if (contentAttrs.svgContent) {
        element.innerHTML = contentAttrs.svgContent;
        if (elementType == "StiTextElement" || elementType == "StiImageElement") {
            jsObject.AddInteractionsToDashboardElement(element);
        }
    }
    //interactive controls content
    else if (elementType == "StiChartElement" || elementType == "StiRegionMapElement") {
        this.InsertHTMLContentToDashboardElement(element, contentAttrs.htmlContent, function (frameDoc) {
            jsObject.AddInteractionsToHtmlContentDashboardElement(element, frameDoc);
        });
    }    
    else if (elementType == "StiOnlineMapElement") {
        this.InsertHTMLContentToDashboardElement(element, StiBase64.decode(contentAttrs.htmlContent), function () {});
    }    
    else {
        var contentPanel = document.createElement("div");
        contentPanel.style.position = "absolute";
        contentPanel.style.overflow = "auto";
        contentPanel.style.left = contentPanel.style.top = contentPanel.style.right = contentPanel.style.bottom = "0px";
        element.contentPanel = contentPanel;
        element.appendChild(contentPanel);

        jsObject.PaintDashboardElementTitle(element, contentAttrs);

        if (elementAttrs.padding) {
            var padding = elementAttrs.padding.split(",");
            contentPanel.style.top = (element.titlePanel ? (element.titlePanel.offsetHeight + parseInt(padding[0])) : padding[0]) + "px";
            contentPanel.style.right = padding[1] + "px";
            contentPanel.style.bottom = padding[2] + "px";
            contentPanel.style.left = padding[3] + "px";
        }

        if (elementType == "StiListBoxElement") {
            this.CreateListBoxElementContent(element);
        }
        else if (elementType == "StiComboBoxElement") {
            this.CreateComboBoxElementContent(element);
        }
        else if (elementType == "StiDatePickerElement") {
            this.CreateDatePickerElementContent(element);
        }
        else if (elementType == "StiTreeViewElement") {
            this.CreateTreeViewElementContent(element);
        }
        else if (elementType == "StiTreeViewBoxElement") {
            this.CreateTreeViewBoxElementContent(element);
        }
        else if (elementType == "StiTableElement") {
            this.CreateTableElementContent(element);
        }
        else if (elementType == "StiPivotTableElement") {
            this.CreatePivotTableElementContent(element);
        }

        if (element.itemsPanel) element.itemsPanel.scrollTop = oldScrollTop;
    }

    //return buttonsPanel and filtersStringPanel to the place
    if (element.filtersStringPanel) element.appendChild(element.filtersStringPanel);
    if (element.buttonsPanel) element.appendChild(element.buttonsPanel);
}

StiJsViewer.prototype.ApplyFiltersToDashboardElement = function (element, filters) {
    this.filterGuid = this.newGuid();

    this.postInteraction({
        action: "DashboardFiltering",
        dashboardFilteringParameters: {
            elementName: element.elementAttributes.name,
            elementGroup: element.elementAttributes.group,
            filters: filters,
            filterGuid: this.filterGuid
        }
    });

    this.controls.processImage.hide();
    clearTimeout(this.dashboardProcessTimeout);

    var jsObject = this;

    jsObject.dashboardProcessTimeout = setTimeout(function () {
        jsObject.controls.processImage.show();
    }, 800);
}

