StiJsViewer.prototype.SetFilterSortGuid = function () {
    this.filterSortGuid = this.newGuid();

    return this.filterSortGuid;
}

StiJsViewer.prototype.CheckFilterSortGuid = function (guid) {
    var newGuid = this.newGuid();
    this.filterSortGuid

    if (!this.filterSortGuids) this.filterSortGuids = [];
    this.filterSortGuids.push(newGuid);

    return newGuid;
}

StiJsViewer.prototype.InsertHTMLContentToDashboardElement = function (element, htmlContent, completeLoadFunction) {
    var jsObject = this;

    if (htmlContent) {
        var frame = document.createElement("iframe");
        frame.setAttribute("style", "position: absolute; overflow: hidden; left: 0px; top: 0px; right: 0px; bottom: 0px; border: none");
        frame.setAttribute("scrolling", "no");
        frame.style.width = element.style.width;
        frame.style.height = element.style.height;
        element.appendChild(frame);
        element.frame = frame;
        
        var frameDoc = frame.contentWindow.document;
        if (frameDoc) {
            if (completeLoadFunction) {
                frame.onload = function () { completeLoadFunction(frameDoc); }
            }

            frameDoc.open();
            frameDoc.write(htmlContent);
            frameDoc.close();

            //correct html content
            var domElements = frameDoc.getElementsByClassName("StiPageContainer");
            if (domElements && domElements.length > 0) {
                domElements[0].style.position = "absolute";
                domElements[0].style.top = "0px";
            }

            frameDoc.onmousedown = function () {
                jsObject.controls.viewer.pressedDown();
                if (jsObject.options.jsDesigner) {
                    jsObject.options.jsDesigner.options.mobileDesigner.pressedDown();
                }
            }
        }
    }
}

StiJsViewer.prototype.InitializeSaveDashboardMenu = function (itemStyleName, menuStyleName, isElementExport) {
    var exports = this.options.exports;
    var showExportToImage = exports.showExportToImageBmp || exports.showExportToImageGif || exports.showExportToImageJpeg || exports.showExportToImagePcx ||
        exports.showExportToImagePng || exports.showExportToImageTiff || exports.showExportToImageMetafile || exports.showExportToImageSvg || exports.showExportToImageSvgz;
    var showExportToData = exports.showExportToCsv || exports.showExportToDbf || exports.showExportToXml || exports.showExportToDif || exports.showExportToSylk || exports.showExportToJson;

    var items = [];

    if (!this.options.jsMode && exports.showExportToDocument && !isElementExport && !this.reportParams.isCompilationMode) {
        items.push(this.Item("Document", this.collections.loc["ReportSnapshot"], null, "Document"));
        items.push("separator");
    }

    if (this.options.exports.showExportToPdf) items.push(this.Item("Pdf", "Adobe PDF", null, "Pdf"));
    if (this.options.exports.showExportToExcel2007) items.push(this.Item("Excel2007", "Microsoft Excel", null, "Excel2007"));
    if (showExportToData) items.push(this.Item("Data", this.collections.loc["Data"], null, "Data"));

    if (!this.options.jsMode && showExportToImage) {
        items.push(this.Item("Image", this.collections.loc["Image"], null, "Image"));
    }

    var saveMenu = this.VerticalMenu("saveDashboardMenu", null, "Down", items, itemStyleName, menuStyleName, true);

    if (saveMenu.items.separator) saveMenu.items.separator.style.margin = "1px 2px 0 2px";

    saveMenu.action = function (menuItem) {
        saveMenu.changeVisibleState(false);

        if (!this.jsObject.checkCloudAuthorization("export")) return;

        if (!(saveMenu.jsObject.options.jsMode && menuItem.key == "Data") && menuItem.key != "Document" && saveMenu.jsObject.options.exports.showExportDialog) {
            var exportForm = saveMenu.jsObject.controls.forms.dashboardExportForm || saveMenu.jsObject.InitializeDashboardExportForm();
            exportForm.show(menuItem.key, saveMenu.parentButton.elementName, saveMenu.parentButton.elementType);
        }
        else {
            saveMenu.jsObject.postExport(menuItem.key, saveMenu.jsObject.getDefaultExportSettings(menuItem.key, true), saveMenu.parentButton.elementName, true);
        }
    }

    saveMenu._changeVisibleState = saveMenu.changeVisibleState;

    saveMenu.changeVisibleState = function (state, parentButton, rightAlign, leftOffset, onlyCorrectPosition) {
        if (state && parentButton && this.items.Data)
            this.items.Data.style.display = parentButton.elementType == "StiTableElement" ? "" : "none";

        saveMenu._changeVisibleState(state, parentButton, rightAlign, leftOffset, onlyCorrectPosition);

        var jsDesigner = this.jsObject.options.jsDesigner;
        if (state && jsDesigner && this.jsObject.options.cloudMode && this.items.Document && (!jsDesigner.options.cloudParameters || !jsDesigner.options.cloudParameters.sessionKey)) {
            this.items.Document.style.display = this.items.separator.style.display = "none";
        }
    }

    return saveMenu;
}


StiJsViewer.prototype.CreateListBoxElementContent = function (element) {
    var jsObject = this;

    var itemsPanel = document.createElement("div");
    itemsPanel.style.position = "absolute";
    itemsPanel.style.left = itemsPanel.style.top = itemsPanel.style.right = itemsPanel.style.bottom = "0px";
    itemsPanel.style.overflow = "auto";

    jsObject.CreateListBoxItemsContent(element, itemsPanel, element.contentPanel); 
}

StiJsViewer.prototype.CreateListBoxItemsContent = function (element, itemsPanel, parentPanel, actionFunction) {
    var jsObject = this;
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;
    var itemAllValue;
    element.itemsPanel = itemsPanel;

    while (parentPanel.childNodes[0]) {
        parentPanel.removeChild(parentPanel.childNodes[0]);
    }

    //Helper methods
    element.setStatesForAllItems = function (state) {
        if (contentAttrs.selectionMode == "Multi" && itemAllValue) {
            itemAllValue.setChecked(state);
        }
        for (var i = 0; i < itemsPanel.childNodes.length; i++) {
            var item = itemsPanel.childNodes[i];

            //Mode Multi
            if (item["setChecked"]) {
                item.setChecked(state);
            }
            else if (item["setSelected"]) {
                item.setSelected(state);
            }
        }
    }

    element.applyFiltersToItems = function () {
        for (var i = 0; i < itemsPanel.childNodes.length; i++) {
            var item = itemsPanel.childNodes[i];

            //Mode Multi
            if (item["setChecked"]) {
                var state = contentAttrs.filters[0].condition == "NotEqualTo" || contentAttrs.filters[0].condition == "IsFalse";

                if (state && contentAttrs.filters.some(function (f) { return ((f.condition == "NotEqualTo" && f.value == item.value) || f.condition == "IsFalse") })) {
                    item.setChecked(false);
                }
                else if (!state && contentAttrs.filters.some(function (f) { return (f.condition == "EqualTo" && f.value == item.value) })) {
                    item.setChecked(true);
                }
                else {
                    item.setChecked(state);
                }

                if (itemAllValue && !item.isChecked) {
                    itemAllValue.setChecked(false);
                }
            }
            //Mode One
            else if (item["setSelected"] && contentAttrs.filters.some(function (f) { return (f.condition == "EqualTo" && f.value == item.value) })) {
                item.setSelected(true);
                return;
            }
        }
    }
        
    element.getAllItemsCheckedState = function () {
        var states = {
            checkedItems: [],
            unCheckedItems: []
        };

        for (var i = 0; i < itemsPanel.childNodes.length; i++) {
            var item = itemsPanel.childNodes[i];
            if (item["setChecked"] && !item.isAllValue) {
                states[item.isChecked ? "checkedItems" : "unCheckedItems"].push(item);
            }
        }

        return states;
    }

    element.getFilters = function () {
        var filters = [];
        var states = element.getAllItemsCheckedState();

        if (states.checkedItems.length == 0) {
            filters.push({ condition: "IsFalse", path: contentAttrs.columnPath });
        }
        else if (states.unCheckedItems.length > states.checkedItems.length) {
            for (var i = 0; i < states.checkedItems.length; i++) {
                filters.push({ condition: "EqualTo", value: states.checkedItems[i].value, path: contentAttrs.columnPath });
            }
        }
        else {
            for (var i = 0; i < states.unCheckedItems.length; i++) {
                filters.push({ condition: "NotEqualTo", value: states.unCheckedItems[i].value, path: contentAttrs.columnPath });
            }
        }
        return filters;
    }

    element.itemAction = function (item) {
        if (contentAttrs.selectionMode == "Multi") {
            if (item.isAllValue) {
                element.setStatesForAllItems(item.isChecked);
            }
            else if (itemAllValue) {
                var itemsStates = element.getAllItemsCheckedState();
                itemAllValue.setChecked(itemsStates.unCheckedItems.length == 0);
            }

            clearTimeout(this.actionTimer);
            this.actionTimer = setTimeout(function () {
                jsObject.ApplyFiltersToDashboardElement(element, element.getFilters());
            }, 500);
        }
        else {
            element.setStatesForAllItems(false);
            item.setSelected(true);
            var filters = !item.isAllValue ? [{ condition: "EqualTo", value: item.value, path: contentAttrs.columnPath }] : [];
            jsObject.ApplyFiltersToDashboardElement(element, filters);
        }

        if (actionFunction) actionFunction();
    }

    if (contentAttrs.items) {
        if (contentAttrs.selectionMode == "Multi") {
            //Mode Multi
            if (contentAttrs.showAllValue) {
                itemAllValue = this.ListBoxElementCheckBox(this.collections.loc.DashboardAllValue, elementAttrs);
                itemAllValue.isAllValue = true;
                jsObject.ApplyAttributesToObject(itemAllValue.button.innerTable, elementAttrs);                
                parentPanel.appendChild(itemAllValue);
                parentPanel.appendChild(jsObject.ListBoxElementSeparator(elementAttrs));
                itemsPanel.style.top = (itemAllValue.offsetHeight + 3) + "px";

                itemAllValue.action = function () {
                    element.itemAction(this);
                }
            }

            for (var i = 0; i < contentAttrs.items.length; i++) {
                var itemObj = contentAttrs.items[i];
                var item = this.ListBoxElementCheckBox(contentAttrs.items[i].label || (itemObj.value ? itemObj.value.toString() : ""), elementAttrs);
                item.value = itemObj.value;

                jsObject.ApplyAttributesToObject(item.button.innerTable, elementAttrs);
                itemsPanel.appendChild(item);

                item.action = function () {
                    element.itemAction(this);
                }
            }            
        }
        else {
            //Mode One
            if (contentAttrs.showAllValue) {
                itemAllValue = this.ListBoxElementButton(this.collections.loc.DashboardAllValue, elementAttrs);
                itemAllValue.isAllValue = true;
                itemsPanel.appendChild(itemAllValue);
                itemsPanel.appendChild(jsObject.ListBoxElementSeparator(elementAttrs));

                itemAllValue.action = function () {
                    element.itemAction(this);
                }
            }

            for (var i = 0; i < contentAttrs.items.length; i++) {
                var itemObj = contentAttrs.items[i];
                var item = this.ListBoxElementButton(contentAttrs.items[i].label || (itemObj.value ? itemObj.value.toString() : ""), elementAttrs);
                item.value = itemObj.value;
                itemsPanel.appendChild(item);

                item.action = function () {
                    element.itemAction(this);
                }
            }
        }

        element.setStatesForAllItems(contentAttrs.selectionMode == "Multi");
        
        if (contentAttrs.filters.length > 0) {
            element.applyFiltersToItems();
        }
        else if (itemAllValue && contentAttrs.selectionMode == "One") {
            itemAllValue.setSelected(true);
        }
    }

    parentPanel.appendChild(itemsPanel);
}

StiJsViewer.prototype.ListBoxElementButton = function (caption, elementAttrs) {
    var button = this.SmallButton(null, caption, null, null, null, null, elementAttrs.contentAttributes.settings);
    button.style.height = "auto";

    this.ApplyAttributesToObject(button.innerTable, elementAttrs);

    return button;
}

StiJsViewer.prototype.ListBoxElementCheckBox = function (caption, elementAttrs) {
    var checkItem = document.createElement("div");
    checkItem.isChecked = false;

    var button = this.SmallButton(null, caption, "CheckBox.png", null, null, null, elementAttrs.contentAttributes.settings, { width: 13, height: 13 });
    button.style.height = "auto";
    checkItem.appendChild(button);
    checkItem.button = button;

    var checkBox = this.CheckBox(null, null, null, elementAttrs.contentAttributes.settings);
    checkBox.onmouseenter = null;
    checkBox.onmouseleave = null;
    checkBox.onmouseover = null;
    checkBox.onmouseout = null;
    checkBox.action = function () { };
    checkBox.style.margin = "0 3px 0 3px";
    checkBox.image.parentNode.style.fontSize = "0px";

    if (elementAttrs && elementAttrs.foreColor) {
        checkBox.imageBlock.style.borderColor = elementAttrs.foreColor;
        checkBox.imageBlock.style.background = "transparent";
    }

    button.imageCell.removeChild(button.image);
    button.imageCell.appendChild(checkBox);

    checkItem.setChecked = function (state) {
        this.isChecked = state;
        checkBox.setChecked(state);
    }

    button.action = function () {
        checkItem.setChecked(!checkItem.isChecked);
        checkItem.action();
    }

    checkItem.action = function () { }

    return checkItem;
}

StiJsViewer.prototype.ApplyAttributesToObject = function (obj, elementAttrs) {
    if (elementAttrs.contentAttributes.settings) {        
        obj.style.minHeight = elementAttrs.contentAttributes.settings.itemHeight + "px";
        obj.style.height = "0px"; //fix a bug in the Firefox
    }

    if (elementAttrs.font) {
        obj.style.fontFamily = elementAttrs.font.name;
        obj.style.fontSize = elementAttrs.font.size + "pt";
        if (elementAttrs.font.bold) obj.style.fontWeight = "bold";
        if (elementAttrs.font.italic) obj.style.fontStyle = "italic";
        if (elementAttrs.font.underline) obj.style.textDecoration = "underline";
    }  
}

StiJsViewer.prototype.ListBoxElementSeparator = function (elementAttrs) {
    var sep = document.createElement("div");
    sep.style.height = "1px";   
    sep.style.margin = "1px";
    sep.style.background = elementAttrs.contentAttributes.settings.separatorColor;

    return sep;
}

StiJsViewer.prototype.CreateTableElementContent = function (element) {
    var jsObject = this;
    
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;
    if (!contentAttrs) return;

    var panel = document.createElement("div");
    panel.setAttribute("style", "-webkit-user-select: none; -moz-user-select: none; -ms-user-select: none; user-select: none;");
    panel.style.position = "absolute";
    panel.style.left = panel.style.top = panel.style.right = panel.style.bottom =  "0px";
    panel.style.overflow = "hidden";
    element.contentPanel.appendChild(panel);

    var padding = elementAttrs.padding.split(",");                    
    var gridWidth = parseInt(element.style.width) - parseInt(padding[1]) - parseInt(padding[3]);
    var gridHeight = parseInt(element.style.height) - parseInt(padding[0]) - parseInt(padding[2]);

    var border = elementAttrs.border;
    if (border) {
        var horBorders = (border.left ? border.size : 0) + (border.right ? border.size : 0);
        var vertBorders = (border.top ? border.size : 0) + (border.bottom ? border.size : 0);
        gridWidth -= horBorders;
        gridHeight -= vertBorders;
    }

    if (element.titlePanel) {
        gridHeight -= element.titlePanel.offsetHeight;
    }

    var dataGrid = jsObject.DataGrid(gridWidth, gridHeight, contentAttrs.settings, elementAttrs, element);
    element.dataGrid = dataGrid;
    panel.appendChild(dataGrid);

    if (document._stiTooltip) document._stiTooltip.cx = -0.2; //fix - hide old tooltip

    dataGrid.showData(contentAttrs.data);
        
    dataGrid.action = function (headerButton) {
        var menuStyle = (elementAttrs.actionColors && elementAttrs.actionColors.isDarkStyle) ? "stiJsViewerDbsDarkMenu" : "stiJsViewerDbsLightMenu";

        var sortFilterMenu = jsObject.SortFilterMenu(headerButton, dataGrid, element, menuStyle + "Item", menuStyle);
        sortFilterMenu.changeVisibleState(true);
        this.selectedHeaderButton = headerButton;
    }
}

StiJsViewer.prototype.DataGrid = function (width, height, settings, elementAttrs, element) {    
    var grid = document.createElement("div");
    var jsObject = grid.jsObject = this;
    grid.style.userSelect = "none";
    grid.style.position = "relative";    

    if (jsObject.options.isTouchDevice) {
        grid.style.overflowX = "auto";
        grid.style.overflowY = "hidden";
    }
    else {
        grid.style.overflow = "hidden";
    }

    if (width) grid.style.width = width + "px";
    if (height) grid.style.height = height + "px";

    grid.clear = function () {
        while (this.childNodes[0]) this.removeChild(this.childNodes[0]);
    }

    grid.showProgress = function () {
        grid.hideProgress();
        var panel = document.createElement("div");
        panel.style.position = "absolute";
        panel.style.zIndex = "1";
        panel.style.top = panel.style.left = panel.style.right = panel.style.bottom = "0px";
        panel.style.background = elementAttrs.backColor || "transparent";
        jsObject.AddProgressToControl(panel);
        grid.appendChild(panel);
        grid.progressPanel = panel;
        panel.progress.show();
    }

    grid.hideProgress = function () {
        if (grid.progressPanel) {
            grid.removeChild(grid.progressPanel);
        }
        grid.progressPanel = null;
    }

    grid.showData = function (data) {
        grid.hideProgress();

        grid.data = data;
        if (!data || data.length == 0) return;

        grid.selectedCells = null;
        grid.showProgress();

        grid.headerButtons = [];
        var interaction = elementAttrs.contentAttributes.interaction;
        var allowInteractions = interaction.allowUserSorting || interaction.allowUserFiltering;
        var sortsCount = 0;
        var showFooter = false;

        for (var i = 0; i < data[0].length; i++) {
            if (data[0][i].sortLabel) sortsCount++;
            if (data[0][i].showTotalSummary) showFooter = true;
        }

        var headerTable = jsObject.CreateHTMLTable();
        var headerTableRow = headerTable.tr[0];
        grid.appendChild(headerTable);

        var cellsContainer = document.createElement("div");
        cellsContainer.style.position = "relative";

        if (jsObject.options.isTouchDevice) {
            cellsContainer.style.overflowX = "hidden";
            cellsContainer.style.overflowY = "auto";
        }
        else {
            cellsContainer.style.overflow = "hidden";
        }

        grid.appendChild(cellsContainer);
                
        var dataTable = jsObject.CreateHTMLTable();
        var dataTableRow = dataTable.tr[0];
        cellsContainer.appendChild(dataTable);

        var footerTable = jsObject.CreateHTMLTable();
        var footerTableRow = footerTable.tr[0];
        if (showFooter) grid.appendChild(footerTable);

        //Add header
        for (var i = 0; i < data[0].length; i++) {
            var columnObj = data[0][i];
            var headerButton = jsObject.GridHeaderButton(columnObj.label, settings, allowInteractions, columnObj.type == "StiSparklinesColumn");
            grid.headerButtons.push(headerButton);
            headerButton.columnObject = columnObj;
            headerButton.columnIndex = columnObj.columnIndex;
            headerButton.style.minHeight = settings.headerHeight + "px";
            headerButton.style.background = settings.headerBackground;
            headerButton.style.fontFamily = settings.headerFont.name || "Arial";
            headerButton.style.fontSize = (settings.headerFont.size || "10") + "pt";
            headerButton.style.fontWeight = settings.headerFont.bold ? "bold" : "normal";
            headerButton.style.fontStyle = settings.headerFont.italic ? "italic" : "normal";
            headerButton.style.textDecoration = "";
            if (settings.headerFont.strikeout) headerButton.style.textDecoration = "line-through";
            if (settings.headerFont.underline) headerButton.style.textDecoration += " underline";
            headerButton.style.color = settings.headerForeColor;

            var headerCell = headerTable.addCell(headerButton);
            headerCell.style.padding = "0";

            if (i < data[0].length - 1) {
                headerCell.style.borderRight = "1px solid " + settings.tableBorderColor;
            }

            if (allowInteractions && columnObj.type != "StiSparklinesColumn") {
                headerButton.action = function () {
                    grid.action(this);
                }

                headerButton.onclick = null;

                headerButton.onmouseup = function () {
                    this.action();
                }
            }

            if (grid.selectedHeaderButton && grid.selectedHeaderButton.columnIndex == i) {
                headerButton.setSelected(true);
                grid.selectedHeaderButton = headerButton;
            }

            if (columnObj.sortLabel) {
                headerButton.showSortDirection(columnObj.sortLabel.direction, sortsCount > 1 ? columnObj.sortLabel.sortIndex : null);
            }

            if (columnObj.filterLabel) {
                headerButton.showFilter(true);
            }
        }

        if (data.length > 1) {
            dataTable.style.whiteSpace = "normal";
            dataTable.style.fontFamily = elementAttrs.font.name || "Arial";
            dataTable.style.fontSize = (elementAttrs.font.size || "10") + "pt";
            dataTable.style.fontWeight = elementAttrs.font.bold ? "bold" : "normal";
            dataTable.style.fontStyle = elementAttrs.font.italic ? "italic" : "normal";
            dataTable.style.textDecoration = "";
            if (elementAttrs.font.strikeout) dataTable.style.textDecoration = "line-through";
            if (elementAttrs.font.underline) dataTable.style.textDecoration += " underline";
                        
            for (var i = 1; i < data.length; i++) {
                for (var k = 0; k < data[i].length; k++) {
                    var columnObj = data[0][k];
                    var cellObj = data[i][k];

                    //Add footer
                    if (showFooter && i == data.length - 1) {
                        var footerDiv = document.createElement("div");
                        var footerCell = footerTable.addCell(footerDiv);
                        footerDiv.style.textAlign = columnObj.align;
                        footerDiv.innerHTML = cellObj.text != null ? cellObj.text : "";
                        footerCell.style.padding = "0 4px 0 4px";
                        footerCell.style.background = settings.footerBackground;
                        footerCell.style.fontFamily = settings.footerFont.name || "Arial";
                        footerCell.style.fontSize = (settings.footerFont.size || "10") + "pt";
                        footerCell.style.fontWeight = settings.footerFont.bold ? "bold" : "normal";
                        footerCell.style.fontStyle = settings.footerFont.italic ? "italic" : "normal";
                        footerCell.style.textDecoration = "";
                        if (settings.footerFont.strikeout) footerCell.style.textDecoration = "line-through";
                        if (settings.footerFont.underline) footerCell.style.textDecoration += " underline";
                        footerCell.style.color = settings.footerForeColor;
                        footerCell.style.height = settings.footerHeight + "px";
                        footerCell.style.vertAlign = "middle";

                        if (k < data[i].length - 1) {
                            footerCell.style.borderRight = "1px solid " + settings.tableBorderColor;
                        }
                        continue;
                    }

                    var cell = dataTable.addCellInLastRow();
                    cell.columnObj = columnObj;
                    cell.cellObj = cellObj;
                    cell.style.padding = "0 4px 0 4px";
                    cell.style.height = settings.cellHeight + "px";
                    cell.style.background = i % 2 == 0 ? settings.cellBackColorInterlaced : settings.cellBackColor;
                    cell.style.color = cellObj.textColor ? cellObj.textColor : (i % 2 == 0 ? columnObj.cellForeColorInterlaced : columnObj.cellForeColor);
                    cell.style.textAlign = columnObj.align;
                    cell.indexDataRow = i;

                    cell.setSelected = function () {
                        if (grid.selectedCells) {
                            for (var i = 0; i < grid.selectedCells.length; i++) {
                                grid.selectedCells[i].style.background = grid.selectedCells[i].oldBackground;
                                grid.selectedCells[i].style.color = grid.selectedCells[i].oldColor;
                            }
                            grid.selectedCells = null;
                        }

                        grid.selectedCells = [this];

                        if (interaction && interaction.fullRowSelect) {
                            grid.selectedCells = [];
                            var row = dataTable.tr[this.indexDataRow - 1];
                            for (var i = 0; i < row.childNodes.length; i++) {
                                grid.selectedCells.push(row.childNodes[i]);
                            }
                        }

                        for (var i = 0; i < grid.selectedCells.length; i++) {
                            var cell = grid.selectedCells[i];
                            cell.oldBackground = cell.style.background;
                            cell.oldColor = cell.style.color;
                            cell.style.background = settings.cellSelectedBackColor;
                            cell.style.color = settings.cellSelectedForeColor;
                        }
                    }

                    cell.onmouseup = function () {
                        this.setSelected();
                        grid.saveGridStates();
                    }

                    cell.oncontextmenu = function (event) {
                        return false;
                    }

                    //Add Interactions
                    grid.addInteractionsToCell(cell, columnObj, cellObj);

                    if (k < data[i].length - 1) {
                        cell.style.borderRight = "1px solid " + settings.tableBorderColor;
                    }

                    var imageCell = null;

                    if (columnObj.type == "StiDataBarsColumn") {
                        var table = jsObject.CreateHTMLTable();
                        table.style.width = "100%";
                        cell.appendChild(table);

                        var image = document.createElement("img");
                        image.src = cellObj.image;                       

                        if (columnObj.align == "left") {
                            if (cellObj.text) table.addTextCell(cellObj.text).textAlign = columnObj.align;
                            if (cellObj.image) imageCell = table.addCell(image);
                        }
                        else {
                            if (cellObj.image) imageCell = table.addCell(image);
                            if (cellObj.text) table.addTextCell(cellObj.text).textAlign = columnObj.align;
                        }                        
                    }
                    else if (columnObj.type == "StiSparklinesColumn") {
                        if (cellObj.image) {
                            var image = document.createElement("img");
                            image.src = cellObj.image;
                            cell.appendChild(image);
                            imageCell = cell;
                        }
                    }
                    else if (columnObj.type == "StiColorScaleColumn") {
                        if (cellObj.text) {
                            cell.innerHTML = cellObj.text;
                        }
                        if (cellObj.backColor) {
                            cell.style.background = cellObj.backColor;
                        }
                    }
                    else if (columnObj.type == "StiIndicatorColumn") {
                        if (cellObj.imageWidth && cellObj.imageHeight && cellObj.textHeight && cellObj.textWidth) {
                            var div = document.createElement("div");
                            div.style.position = "relative";
                            div.style.height = Math.max(cellObj.textHeight, cellObj.imageHeight) + "px";
                            div.style.width = Math.max(cellObj.textWidth, cellObj.imageWidth) + "px";
                            div.style.display = "inline-block";
                            cell.appendChild(div);

                            var image = document.createElement("img");
                            image.src = cellObj.image;
                            image.style.width = cellObj.imageWidth + "px";
                            image.style.height = cellObj.imageHeight + "px";
                            image.style.left = "0px";
                            image.style.top = "0px";
                            image.style.position = "absolute";
                            div.appendChild(image);

                            var textTable = jsObject.CreateHTMLTable();
                            if (cellObj.text) textTable.addTextCell(cellObj.text);
                            textTable.style.height = cellObj.textHeight + "px";
                            textTable.style.width = cellObj.textWidth + "px";
                            textTable.style.left = (columnObj.align == "left" ? (cellObj.imageWidth - cellObj.textWidth) : (columnObj.align == "center" ? - 3 : 0)) + "px";
                            textTable.style.top = "0px";
                            textTable.style.position = "absolute";
                            div.appendChild(textTable);
                        }
                        else {
                            var table = jsObject.CreateHTMLTable();
                            table.style.width = "100%";
                            cell.appendChild(table);

                            var image = document.createElement("img");
                            image.src = cellObj.image;
                            if (cellObj.imageWidth) image.style.width = cellObj.imageWidth + "px";
                            if (cellObj.imageHeight) image.style.height = cellObj.imageHeight + "px";

                            if (columnObj.align == "left") {
                                if (cellObj.image) imageCell = table.addCell(image);
                                if (cellObj.text) table.addTextCell(cellObj.text).textAlign = columnObj.align;
                            }
                            else {
                                if (cellObj.text) table.addTextCell(cellObj.text).textAlign = columnObj.align;
                                if (cellObj.image) imageCell = table.addCell(image);
                            }
                        }
                    }                    
                    else if (columnObj.type == "StiDimensionColumn" && columnObj.showHyperlink) {
                        var value = cellObj.text != null ? cellObj.text : "";
                        cell.innerHTML = value;
                        cell.style.textDecoration = "underline";
                        cell.style.color = cellObj.textColor ? cellObj.textColor : (i % 2 == 0 ? columnObj.cellForeColorInterlaced : columnObj.cellForeColor);
                        cell.link = columnObj.hyperlinkPattern ? grid.replaceRowValues(cell, jsObject.ReplaceAllKeysInText(columnObj.hyperlinkPattern, { value: value })) : null;
                        cell.style.cursor = cell.link ? "pointer" : "default";

                        if (cell.link) {
                            cell.onclick = function () {
                                jsObject.openNewWindow(this.link);
                            };
                        }
                    }
                    else {
                        if (columnObj.dataType == "image" || columnObj.dataType == "byte[]" || cellObj.image) {
                            var img = document.createElement("img");
                            img.style.maxWidth = img.style.maxHeight = "60px";
                            var imageValue = cellObj.image || cellObj.text;
                            if (imageValue && imageValue.indexOf("data:image") != 0) {
                                imageValue = "data:image/png;base64," + imageValue;
                            }
                            img.src = imageValue;
                            cell.style.width = cell.style.height = "60px";
                            cell.appendChild(img);
                        }
                        else if (columnObj.dataType == "bool") {
                            var checkBox = jsObject.CheckBox();
                            checkBox.setChecked(cellObj.boolValue);
                            checkBox.onmouseover = null;
                            checkBox.onmouseout = null;
                            checkBox.onmouseenter = null;
                            checkBox.onmouseleave = null;
                            checkBox.onclick = null;
                            checkBox.style.display = "inline-block";
                            cell.style.width = "50px";
                            cell.style.textAlign = "center";
                            cell.appendChild(checkBox);
                        }
                        else {
                            cell.innerHTML = cellObj.text != null ? cellObj.text : "";
                        }
                    }

                    if (imageCell) {
                        imageCell.style.width = "1px";
                        imageCell.style.verticalAlign = "middle";
                        imageCell.style.fontSize = "0";
                    }
                }

                if (i < data.length - 1) dataTable.addRow();
            }
        }

        var scrollHiddenColor = "rgba(191, 191, 191, 0)";
        var scrollDivColor = "rgba(191, 191, 191, 0.1)";
        var scrollColor = "rgba(191, 191, 191, 0.5)";
        var scrollSelectedColor = "rgba(191, 191, 191, 0.8)";

        //horizontal scroll 
        var cellsHScrollDiv = document.createElement("div");
        grid.parentElement.appendChild(cellsHScrollDiv);
        cellsHScrollDiv.style.bottom = "0";
        cellsHScrollDiv.style.left = "0";
        cellsHScrollDiv.style.width = "100%";
        cellsHScrollDiv.style.position = "absolute";
        cellsHScrollDiv.style.boxSizing = "border-box";
        cellsHScrollDiv.style.height = "8px";
        cellsHScrollDiv.style.touchAction = "none";
        cellsHScrollDiv.style.backgroundColor = scrollHiddenColor;
        cellsHScrollDiv.style.transition = "background-color 0.5s ease";
        cellsHScrollDiv.style.poinerEvents = "none";
        cellsHScrollDiv.className = "pivotUnselectable";

        var cellHScroll = document.createElement("div");
        cellsHScrollDiv.appendChild(cellHScroll);
        cellHScroll.style.height = "100%";
        cellHScroll.style.width = "73%";
        cellHScroll.style.backgroundColor = scrollHiddenColor;
        cellHScroll.style.transition = "background-color 0.5s ease";
        cellHScroll.className = "pivotUnselectable";
        grid.hScrollOffset = 0;
        grid.hOffset = 1;

        //vertical scroll 
        var cellsVScrollDiv = document.createElement("div");
        grid.parentElement.appendChild(cellsVScrollDiv);
        cellsVScrollDiv.style.top = "0";
        cellsVScrollDiv.style.right = "0";
        cellsVScrollDiv.style.height = "100%";
        cellsVScrollDiv.style.position = "absolute";
        cellsVScrollDiv.style.boxSizing = "border-box";
        cellsVScrollDiv.style.width = "8px";
        cellsVScrollDiv.style.touchAction = "none";
        cellsVScrollDiv.style.backgroundColor = scrollHiddenColor;
        cellsVScrollDiv.style.transition = "background-color 0.5s ease";
        cellsVScrollDiv.style.poinerEvents = "none";
        cellsVScrollDiv.className = "pivotUnselectable";

        var cellVScroll = document.createElement("div");
        cellsVScrollDiv.appendChild(cellVScroll);
        cellVScroll.style.width = "100%";
        cellVScroll.style.height = "73%";
        cellVScroll.style.backgroundColor = scrollHiddenColor;
        cellVScroll.style.transition = "background-color 0.5s ease";
        cellVScroll.className = "pivotUnselectable";
        grid.vScrollOffset = 0;
        grid.vOffset = 1;
                
        document.body.addEventListener("mousemove", function (event) {
            if (grid.screenX) {
                var emptyWidth = grid.offsetWidth - grid.offsetWidth / grid.hOffset;
                var offset = Math.max(0, Math.min(emptyWidth, event.screenX - grid.screenX + grid.startXOffset));
                cellHScroll.style.transform = "translateX(" + offset + "px)";
                grid.scrollLeft = offset * grid.hOffset;
                grid.hScrollOffset = offset;
            }

            if (grid.screenY) {
                var emptyHeight = (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) - (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) / grid.vOffset;
                var offset = Math.max(0, Math.min(emptyHeight, event.screenY - grid.screenY + grid.startYOffset));
                cellVScroll.style.transform = "translateY(" + offset + "px)";
                cellsContainer.scrollTop = offset * grid.vOffset;
                grid.vScrollOffset = offset;
            }
        });

        document.body.addEventListener("mouseup", function (event) {
            grid.screenX = null;
            grid.screenY = null;
            if (!grid.mouseOver) {
                cellsHScrollDiv.style.backgroundColor = scrollHiddenColor;
                cellHScroll.style.backgroundColor = scrollHiddenColor;
                cellsVScrollDiv.style.backgroundColor = scrollHiddenColor;
                cellVScroll.style.backgroundColor = scrollHiddenColor;
            } else {
                if (grid.hOffset > 1)
                    cellHScroll.style.backgroundColor = scrollColor;
                if (grid.vOffset > 1)
                    cellVScroll.style.backgroundColor = scrollColor;
            }
        });

        cellHScroll.onmousedown = function (event) {
            event.stopPropagation();
            if (grid.hOffset > 1) {
                grid.screenX = event.screenX;
                grid.startXOffset = grid.hScrollOffset;
                cellHScroll.style.backgroundColor = scrollSelectedColor;
            }
        }

        cellVScroll.onmousedown = function (event) {
            event.stopPropagation();
            if (grid.vOffset > 1) {
                grid.screenY = event.screenY;
                grid.startYOffset = grid.vScrollOffset;
                cellVScroll.style.backgroundColor = scrollSelectedColor;
            }
        }

        cellsHScrollDiv.onmousedown = function (event) {
            var sWidth = grid.offsetWidth / grid.hOffset;
            var emptyWidth = grid.offsetWidth - sWidth;

            if (cellHScroll.getBoundingClientRect().left > event.screenX)
                sWidth *= -1;

            var offset = Math.max(0, Math.min(emptyWidth, sWidth + grid.hScrollOffset));
            cellHScroll.style.transform = "translateX(" + offset + "px)";
            grid.scrollLeft = offset * grid.hOffset;
            grid.hScrollOffset = offset;
        }

        cellsVScrollDiv.onmousedown = function (event) {
            var sHeight = (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) / grid.vOffset;
            var emptyHeight = (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) - sHeight;

            if (cellVScroll.getBoundingClientRect().top > event.screenY)
                sHeight *= -1;

            var offset = Math.max(0, Math.min(emptyHeight, sHeight + grid.vScrollOffset));
            cellVScroll.style.transform = "translateY(" + offset + "px)";
            cellsContainer.scrollTop = offset * grid.vOffset;
            grid.vScrollOffset = offset;
        }

        grid.parentElement.onmouseover = function () {
            grid.mouseOver = true;
            if (grid.hOffset > 1) {
                cellsHScrollDiv.style.backgroundColor = scrollDivColor;
                cellHScroll.style.backgroundColor = scrollColor;
            }
            if (grid.vOffset > 1) {
                cellsVScrollDiv.style.backgroundColor = scrollDivColor;
                cellVScroll.style.backgroundColor = scrollColor;
            }
        }

        grid.parentElement.onmouseout = function () {
            grid.mouseOver = false;
            if (!grid.screenX) {
                cellsHScrollDiv.style.backgroundColor = scrollHiddenColor;
                cellHScroll.style.backgroundColor = scrollHiddenColor;
            }
            if (!grid.screenY) {
                cellsVScrollDiv.style.backgroundColor = scrollHiddenColor;
                cellVScroll.style.backgroundColor = scrollHiddenColor;
            }
        }

        grid.addWheel = function (elem) {
            if (elem.addEventListener) {
                if ('onwheel' in document) {
                    elem.addEventListener("wheel", onWheel);
                } else if ('onmousewheel' in document) {
                    elem.addEventListener("mousewheel", onWheel);
                } else {
                    elem.addEventListener("MozMousePixelScroll", onWheel);
                }
            } else { // IE8-
                elem.attachEvent("onmousewheel", onWheel);
            }

            function onWheel(e) {
                e = e || window.event;
                var delta = e.wheelDelta || e.deltaY || e.detail;
                if (e.wheelDelta == null && e.deltaY != null) delta *= -40; //fix for firefox
                e.preventDefault ? e.preventDefault() : (e.returnValue = false);
                var sHeight = (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) / grid.vOffset;
                var emptyHeight = (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) - sHeight;
                var offset = Math.max(0, Math.min(emptyHeight, -delta / 5 + grid.vScrollOffset));
                cellVScroll.style.transform = "translateY(" + offset + "px)";
                cellsContainer.scrollTop = offset * grid.vOffset;
                grid.vScrollOffset = offset;
            }
        }

        grid.saveGridStates = function () {
            if (!jsObject.tableElementGridStates) jsObject.tableElementGridStates = {};

            jsObject.tableElementGridStates[elementAttrs.key] = {
                selectedCells: this.selectedCells,
                cellVScrollTransform: cellVScroll.style.transform,
                cellsContainerScrollTop: cellsContainer.scrollTop,
                vScrollOffset: grid.vScrollOffset
            }
        }

        grid.restoreGridStates = function () {
            var gridStates = jsObject.tableElementGridStates ? jsObject.tableElementGridStates[elementAttrs.key] : null;
            if (gridStates) {
                cellVScroll.style.transform = gridStates.cellVScrollTransform;
                cellsContainer.scrollTop = gridStates.cellsContainerScrollTop;
                grid.vScrollOffset = gridStates.vScrollOffset;
                if (gridStates.selectedCells && gridStates.selectedCells.length > 0) {
                    var rowIndex = gridStates.selectedCells[0].indexDataRow - 1;
                    var cellIndex = gridStates.selectedCells[0].cellIndex;
                    var row = dataTable.tr && dataTable.tr.length > rowIndex
                        ? dataTable.tr[rowIndex]
                        : dataTable.tr.length > 0 ? dataTable.tr[dataTable.tr.length - 1] : null;
                    if (row) {
                        var cell = row.childNodes && row.childNodes.length > cellIndex
                            ? row.childNodes[cellIndex]
                            : row.childNodes.length > 0 ? row.childNodes[row.childNodes.length - 1] : null;
                        if (cell) cell.setSelected();
                    }
                }
            }
        }

        //Update cell sizes
        setTimeout(function () {
            if (headerTableRow.childNodes.length == 0 || dataTableRow.childNodes.length == 0 || headerTableRow.childNodes.length != dataTableRow.childNodes.length) {
                grid.hideProgress();
                return;
            }

            for (i = 0; i < dataTableRow.childNodes.length; i++) {
                var width = Math.max(dataTableRow.childNodes[i].offsetWidth, headerTableRow.childNodes[i].offsetWidth);
                if (showFooter) width = Math.max(width, footerTableRow.childNodes[i].offsetWidth);
                if (width > 300) width = 300;

                var headerButton = headerTableRow.childNodes[i].firstChild;
                headerButton.style.width = width + "px";

                if (showFooter) {
                    var footerDiv = footerTableRow.childNodes[i].firstChild;
                    footerDiv.style.width = width + "px";
                }

                if (settings.sizeMode != "Fit" && headerButton.caption.offsetWidth > headerButton.offsetWidth && headerButton.caption.offsetWidth != 0) {
                    width = headerButton.caption.offsetWidth + 50;
                    headerButton.style.width = width + "px";
                    if (showFooter) footerDiv.style.width = width + "px";
                }

                for (var k = 0; k < dataTable.tr.length; k++) {
                    if (i < dataTable.tr[k].childNodes.length) {
                        var cell = dataTable.tr[k].childNodes[i];
                        var divCell = document.createElement("div");
                        divCell.style.textAlign = cell.columnObj.align;
                        divCell.style.width = width + "px";
                        divCell.className = "stiJsViewerDataGridCellInnerContainer";
                        divCell.innerHTML = cell.innerHTML;
                        cell.innerHTML = "";
                        cell.appendChild(divCell);
                    }
                }
            }

            cellsContainer.style.minWidth = Math.max(width, headerTable.offsetWidth, footerTable.offsetWidth) + "px";
            cellsContainer.style.height = (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) + "px";

            if (settings.sizeMode == "Fit" && headerTable.offsetWidth < grid.offsetWidth && headerTable.offsetWidth > 0) {
                var xFactor = grid.offsetWidth / headerTable.offsetWidth;

                for (i = 0; i < dataTableRow.childNodes.length; i++) {
                    var headerButton = headerTableRow.childNodes[i].firstChild;
                    var newWidth = headerButton.offsetWidth * xFactor - 8;

                    for (var k = 0; k < dataTable.tr.length; k++) {
                        if (i < dataTable.tr[k].childNodes.length) {
                            var cell = dataTable.tr[k].childNodes[i];
                            var divCell = cell.firstChild;
                            headerButton.style.width = divCell.style.width = newWidth + "px";
                            if (showFooter) footerTableRow.childNodes[i].firstChild.style.width = newWidth + "px";
                        }
                    }
                }
            }

            grid.hOffset = (headerTable.offsetWidth - 4) / grid.offsetWidth;
            grid.vOffset = dataTable.offsetHeight / (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight);
            cellHScroll.style.width = (grid.offsetWidth / grid.hOffset) + "px";
            cellVScroll.style.height = ((grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) / grid.vOffset) + "px";
            cellsVScrollDiv.style.top = headerTable.offsetHeight + "px";
            cellsVScrollDiv.style.height = (grid.offsetHeight - headerTable.offsetHeight - footerTable.offsetHeight) + "px";

            grid.addWheel(grid.parentElement);
            grid.hideProgress();
            grid.restoreGridStates();
        }, 0); 
    }

    grid.replaceRowValues = function (currentCell, inputText) {
        var indexDataRow = currentCell.indexDataRow;
        if (indexDataRow < this.data.length) {
            var columns = this.data[0];
            var cells = this.data[indexDataRow];
            for (var i = 0; i < cells.length; i++) {
                var columnName = columns[i].labelCorrect;
                var cellText = cells[i].text || "";
                if (columnName != null && cellText != null) {
                    inputText = inputText.replace(new RegExp("{row." + columnName.toLowerCase() + "}", 'g'), cellText).replace(new RegExp("{Row." + columnName + "}", 'g'), cellText);
                }
            }
        }
        return inputText;
    }

    grid.addInteractionsToCell = function (cell, columnObj, cellObj) {
        if (columnObj.interaction) {
            var value = cellObj.text != null ? cellObj.text : "";

            if (columnObj.interaction.onHover == "ShowToolTip" && columnObj.interaction.toolTip ||
                columnObj.interaction.onHover == "ShowHyperlink" && (columnObj.interaction.hyperlink || (columnObj.showHyperlink && columnObj.hyperlinkPattern))) {

                var toolTipText = columnObj.interaction.onHover == "ShowToolTip" ? columnObj.interaction.toolTip : (columnObj.interaction.hyperlink || columnObj.hyperlinkPattern);
                toolTipText = jsObject.CorrectTooltipText(grid.replaceRowValues(cell, jsObject.ReplaceAllKeysInText(toolTipText, { value: value })));

                if (columnObj.interaction.onHover == "ShowHyperlink") {
                    toolTipText = "<font style=\"color: #0645ad; text-decoration: underline;\">" + toolTipText + "</font>";
                }

                cell.setAttribute("_text1", toolTipText);

                if (!document._stiTooltip)
                    jsObject.CreateCustomTooltip(document, jsObject.controls.mainPanel);

                jsObject.AddCustomTooltip(cell, document);
            }

            if (columnObj.interaction.onClick == "OpenHyperlink" && columnObj.interaction.hyperlink) {
                cell.style.cursor = "pointer";
                cell.onclick = function () {
                    var link = grid.replaceRowValues(cell, jsObject.ReplaceAllKeysInText(columnObj.interaction.hyperlink, { value: value }));
                    jsObject.openNewWindow(link);
                }
            }
            else if (columnObj.interaction.onClick == "ApplyFilter") {
                cell.style.cursor = "pointer";
                cell.onclick = function () {
                    var filters = [jsObject.DataFilterObject(columnObj.key, columnObj.path, "EqualTo", value)];
                    jsObject.ApplyFiltersToDashboardElement(element, filters, true);
                }
            }
            else if (columnObj.interaction.onClick == "ShowDashboard" && columnObj.interaction.drillDownPageKey) {
                cell.style.cursor = "pointer";
                cell.onclick = function () {
                    var drillDownParameters = {
                        drillDownPageKey: columnObj.interaction.drillDownPageKey,
                        value: value,
                        parameters: []
                    }
                    var parameters = columnObj.interaction.drillDownParameters;
                    if (parameters) {
                        for (var i = 0; i < parameters.length; i++) {
                            drillDownParameters.parameters.push({
                                key: parameters[i].name,
                                value: grid.replaceRowValues(cell, parameters[i].expression ? jsObject.ReplaceAllKeysInText(parameters[i].expression, { value: value }) : "")
                            });
                        }
                    }
                    jsObject.postInteraction({
                        action: "DashboardDrillDown",
                        drillDownParameters: drillDownParameters,
                        pageNumber: 0
                    });
                }
            }
        }
    }

    grid.action = function () {

    }    

    return grid;
}

StiJsViewer.prototype.GridHeaderButton = function (caption, settings, allowInteractions, disableEvents) {
    var button = this.SmallButton(null, caption, null, null, "Down");
    button.sort = null;
    button.filter = null;
    button.style.border = "0px";
    button.style.color = "#ffffff";
    button.style.borderRadius = 0;
    button.style.overflow = "hidden";
    button.style.padding = "0 4px 0 4px";

    var innerTable = this.CreateHTMLTable();
    innerTable.style.height = "100%";
    innerTable.style.width = "100%";
    button.removeChild(button.innerTable);
    button.appendChild(innerTable);   

    var sortImage = document.createElement("img");
    sortImage.style.marginLeft = "4px";
    sortImage.style.visibility = "hidden";
    sortImage.src = this.collections.images["Dashboards.SortAsc.png"];
    innerTable.addCell(sortImage);

    var sortNumber = document.createElement("div");
    var numberCell = innerTable.addCell(sortNumber);    
    sortNumber.style.width = "6px";
    sortNumber.style.marginRight = "4px";
    sortNumber.style.fontSize = "8px";
    sortNumber.style.color = "#ffffff";
    sortNumber.style.textAlign = "right";
    numberCell.style.verticalAlign = "bottom";
    numberCell.style.paddingBottom = "4px";

    button.caption = innerTable.addTextCell(caption);
    button.caption.style.whiteSpace = "nowrap";
    button.caption.style.textAlign = "center";
    button.caption.style.width = "100%";

    var filterImage = document.createElement("img");
    filterImage.style.margin = "0 6px 0 6px";
    filterImage.style.visibility = "hidden";
    filterImage.src = this.collections.images["Dashboards.DropDownButtonWhite.png"];
    innerTable.addCell(filterImage)

    if (!disableEvents) {
        button.onmouseoverAction = function () {
            if (!allowInteractions) return;
            if (!this.isEnabled || this.jsObject.options.isTouchClick || (this["haveMenu"] && this.isSelected)) return;
            this.className = this.styleName + " " + this.styleName + "Over";
            this.isOver = true;
            filterImage.style.visibility = "visible";
            this.style.background = settings.headerMouseOverBackground;
        }

        button.onmouseoutAction = function () {
            if (!allowInteractions) return;
            this.isOver = false;
            if (!this.isEnabled) return;
            this.className = this.styleName + " " + this.styleName + (this.isSelected ? "Selected" : "Default");
            this.style.background = this.isSelected ? settings.headerSelectedBackground : settings.headerBackground;
            if (!this.filter) filterImage.style.visibility = "hidden";
        }
    }

    button.setSelected = function (state) {
        this.isSelected = state;
        this.className = this.styleName + " " + this.styleName +
            (state ? "Selected" : (this.isEnabled ? (this.isOver ? "Over" : "Default") : "Disabled"));
        this.style.background = state && this.isEnabled
            ? settings.headerMouseSelectedBackground
            : (this.isOver ? settings.headerMouseOverBackground : settings.headerBackground);
    }

    button.showSortDirection = function (sortDirection, number) {
        sortImage.style.visibility = sortDirection == "Ascending" || sortDirection == "Descending" ? "visible" : "hidden";
        sortImage.src = this.jsObject.collections.images[sortDirection == "Ascending" ? "Dashboards.SortAsc.png" : "Dashboards.SortDesc.png"];
        sortNumber.innerHTML = number || "";
    }

    button.showFilter = function (filter) {
        filterImage.src = this.jsObject.collections.images[filter ? "Dashboards.Filter.png" : "Dashboards.DropDownButtonWhite.png"];
        filterImage.style.visibility = filter ? "visible" : "hidden";
        filterImage.style.margin = filter ? "0 5px 0 5px" : "0 6px 0 6px";
        this.filter = filter;
    }

    if (!allowInteractions || disableEvents) {
        button.action = function () { };
    }

    return button;
}

StiJsViewer.prototype.SortFilterMenu = function (headerButton, dataGrid, element, itemStyleName, menuStyleName) {
    var menu = this.VerticalMenu("viewerSortFilterMenu", headerButton, "Down", [], itemStyleName, menuStyleName);
    if (!this.options.isMobileDevice) menu.innerContent.style.maxHeight = "1000px";

    var jsObject = this;
        
    menu.action = function(menuItem) {
        if (menuItem.name.indexOf("filterItem") == 0) {
            menuItem.setChecked(!menuItem.isChecked);
            menu.updateSelectAllItemState();
            menu.contentAttributes.filters = this.getFilters();
            menu.updateRemoveFilterItemState();
            clearTimeout(menu.filterItemTimer);
            menu.filterItemTimer = setTimeout(function () {
                jsObject.ApplyFiltersToDashboardElement(element, menu.contentAttributes.filters);
            }, 500);
            return;
        }

        switch (menuItem.name) {
            case "selectAll": {
                menu.selectAllFilterItems(!menuItem.isChecked);
                menu.contentAttributes.filters = this.getFilters();
                menu.updateRemoveFilterItemState();
                jsObject.ApplyFiltersToDashboardElement(element, menu.contentAttributes.filters);
                return;
            }
            case "removeFilter": {
                var filters = menu.getThisColumnFilters();
                for (var i = 0; i < filters.length; i++) {
                    jsObject.RemoveElementFromArray(menu.contentAttributes.filters, filters[i]);
                }
                menu.selectAllFilterItems(true);
                menu.items.removeFilter.setEnabled(false);
                jsObject.ApplyFiltersToDashboardElement(element, menu.contentAttributes.filters);
                break;
            }
            case "sortAsc":
            case "sortDesc":
            case "noSort": {
                this.items["sortAsc"].setChecked(menuItem.key == "Ascending");
                this.items["sortDesc"].setChecked(menuItem.key == "Descending");
                this.items["noSort"].setChecked(menuItem.key == "None");
                this.setSortDirection(menuItem.key);
                break;
            }
            case "customFilter": {
                var filtersForm = jsObject.InitializeFiltersForm();

                filtersForm.show(menu.columnObject, menu.getThisColumnFilters(), menu.getFilterItemsForEditors());

                filtersForm.action = function () {
                    this.changeVisibleState(false);
                    var otherFilters = menu.getNotThisColumnFilters();
                    var resultFilters = filtersForm.filterControl.getFilters()
                    menu.contentAttributes.filters = otherFilters.concat(resultFilters);
                    jsObject.ApplyFiltersToDashboardElement(element, menu.contentAttributes.filters);
                }
                break;
            }     
        }

        this.changeVisibleState(false);
    }
    
    menu.onshow = function () {
        var elementAttrs = element.elementAttributes;
        var contentAttrs = elementAttrs.contentAttributes;

        menu.clear();
        menu.columnObject = headerButton.columnObject;
        menu.contentAttributes = contentAttrs;

        var startItems = [];

        if (contentAttrs.interaction.allowUserSorting) {
            startItems.push(jsObject.Item("sortAsc", jsObject.ColumnIsNumericType(menu.columnObject.dataType)
                ? jsObject.collections.loc["DashboardSortSmallestToLargest"] : jsObject.collections.loc["DashboardSortAZ"], null, "Ascending"));
            startItems.push(jsObject.Item("sortDesc", jsObject.ColumnIsNumericType(menu.columnObject.dataType)
                ? jsObject.collections.loc["DashboardSortLargestToSmallest"] : jsObject.collections.loc["DashboardSortZA"], null, "Descending"));
            startItems.push(jsObject.Item("noSort", jsObject.collections.loc["FormBandNoSort"], null, "None"));

            menu.addItems(startItems);
            menu.updateItemsStates();
        }

        if (contentAttrs.interaction.allowUserFiltering) {
            var fContainer = document.createElement("div");
            fContainer.style.height = "280px";
            fContainer.style.minWidth = !contentAttrs.interaction.allowUserSorting ? "150px" : "100%";
            fContainer.style.position = "relative";
            menu.innerContent.appendChild(fContainer);
            jsObject.AddProgressToControl(fContainer);
            fContainer.progress.show();

            setTimeout(function () {
                jsObject.postAjax(jsObject.options.requestUrl.replace("{action}", jsObject.options.actions.viewerEvent),
                    {
                        action: "DashboardGettingFilterItems",
                        dashboardFilteringParameters: {
                            elementName: elementAttrs.name,
                            elementGroup: elementAttrs.group,
                            columnIndex: headerButton.columnIndex
                        }
                    },
                    function (answer) {
                        fContainer.progress.hide();
                        menu.innerContent.removeChild(fContainer);

                        var filterItemsHelper = JSON.parse(answer);
                        if (!filterItemsHelper || !filterItemsHelper.mainItems) {
                            menu.correctPositions();
                            return;
                        }
                        var items = [];
                        var filterItems = [];

                        menu.columnObject.path = filterItemsHelper.columnPath;

                        if (contentAttrs.interaction.allowUserSorting) items.push("separatorSort");

                        for (var i = 0; i < filterItemsHelper.mainItems.length; i++) {
                            var filterItem = filterItemsHelper.mainItems[i];
                            if (filterItem.filtered) {
                                filterItems.push(jsObject.Item("filterItem" + i, filterItem.displayString, null, { filterString: filterItem.filterString }));
                            }
                        }

                        if (filterItemsHelper.haveNulls)
                            filterItems.push(jsObject.Item("filterItemIsNull", jsObject.collections.loc["DashboardNulls"], null, { isNullValue: true, filterString: null }));

                        if (filterItemsHelper.haveBlanks)
                            filterItems.push(jsObject.Item("filterItemIsBlank", jsObject.collections.loc["DashboardBlanks"], null, { isBlankValue: true, filterString: "" }));

                        menu.filterItems = filterItems

                        if (jsObject.ColumnIsNumericType(menu.columnObject.dataType)) {
                            items.push(jsObject.Item("numberFilters", jsObject.collections.loc["DashboardNumberFilters"], null, "numberFilters", true));
                        }
                        else if (jsObject.ColumnIsDateType(menu.columnObject.dataType)) {
                            items.push(jsObject.Item("dateFilters", jsObject.collections.loc["DashboardDateFilters"], null, "dateFilters", true));
                        }
                        else if (menu.columnObject.dataType == "bool") {
                            items.push(jsObject.Item("booleanFilters", jsObject.collections.loc["DashboardBooleanFilters"], null, "booleanFilters", true));
                        }
                        else {
                            items.push(jsObject.Item("stringFilters", jsObject.collections.loc["DashboardStringFilters"], null, "stringFilters", true));
                        }

                        items.push(jsObject.Item("customFilter", jsObject.collections.loc["DashboardCustomFilter"], null, "customFilter", null));
                        items.push(jsObject.Item("removeFilter", jsObject.collections.loc["RemoveFilter"], null, "removeFilter", null));

                        if (filterItems.length > 0) {
                            items.push("separatorFilter");
                            items.push(jsObject.Item("selectAll", jsObject.collections.loc["SelectAll"], null, "selectAll"));
                        }

                        items = items.concat(filterItems);
                        menu.addItems(items);
                        menu.updateItemsStates();

                        //Add filter submenus
                        if (menu.items["numberFilters"]) {
                            var numberFiltersMenu = jsObject.InitializeSubMenu("viewerSortFilterMenuNumberFilters", jsObject.GetFilterConditionItems("Numeric", false), menu.items["numberFilters"], menu, itemStyleName, menuStyleName);
                            numberFiltersMenu.action = function (menuItem) {
                                this.changeVisibleState(false);
                                menu.filterSubMenuAction(menuItem.key);
                            }
                        }

                        if (menu.items["dateFilters"]) {
                            var dateFiltersMenu = jsObject.InitializeSubMenu("viewerSortFilterMenuDateFilters", jsObject.GetFilterConditionItems("DateTime", false), menu.items["dateFilters"], menu, itemStyleName, menuStyleName);
                            dateFiltersMenu.action = function (menuItem) {
                                this.changeVisibleState(false);
                                menu.filterSubMenuAction(menuItem.key);
                            }
                        }

                        if (menu.items["booleanFilters"]) {
                            var booleanFiltersMenu = jsObject.InitializeSubMenu("viewerSortFilterMenuBooleanFilters", jsObject.GetFilterConditionItems("Boolean", false), menu.items["booleanFilters"], menu, itemStyleName, menuStyleName);
                            booleanFiltersMenu.action = function (menuItem) {
                                this.changeVisibleState(false);
                                menu.filterSubMenuAction(menuItem.key);
                            }
                        }

                        if (menu.items["stringFilters"]) {
                            var stringFiltersMenu = jsObject.InitializeSubMenu("viewerSortFilterMenuStringFilters", jsObject.GetFilterConditionItems("String", false, true), menu.items["stringFilters"], menu, itemStyleName, menuStyleName);
                            stringFiltersMenu.action = function (menuItem) {
                                this.changeVisibleState(false);
                                menu.filterSubMenuAction(menuItem.key);
                            }
                        }

                        menu.correctPositions();
                    });
            }, jsObject.options.menuAnimDuration);
        }
    }

    menu.onhide = function () {
        if (dataGrid && dataGrid.selectedHeaderButton) {
            dataGrid.selectedHeaderButton.setSelected(false);
            dataGrid.selectedHeaderButton = null;
        }
    }

    menu.updateItemsStates = function () {
        if (this.contentAttributes.interaction.allowUserSorting) {
            var sort = this.getThisColumnSort();
            var sortDirection = sort ? sort.direction : "None";
            this.items["sortAsc"].setChecked(sortDirection == "Ascending");
            this.items["sortDesc"].setChecked(sortDirection == "Descending");
            this.items["noSort"].setChecked(sortDirection == "None");
        }

        if (this.contentAttributes.interaction.allowUserFiltering) {
            var filters = menu.getThisColumnFilters(this.contentAttributes, this.columnObject);
            var filterType = menu.getDataFilterConditionGroupType(filters);

            if (filters.length == 0) {
                this.selectAllFilterItems(true);
            }
            else {
                for (var itemName in this.items) {
                    var item = this.items[itemName];
                    if (item.name && item.name.indexOf("filterItem") == 0) {
                        var filterString = this.items[itemName].key != null ? this.items[itemName].key.filterString : null;
                        this.items[itemName].setChecked(this.checkCondition(filterType, filterString, filters));
                    }
                }
            }

            this.updateSelectAllItemState();
            this.updateRemoveFilterItemState();
        }
    }

    menu.filterSubMenuAction = function (itemKey) {
        this.changeVisibleState(false);

        var filtersForm = jsObject.InitializeFiltersForm();
        filtersForm.show(menu.columnObject, [jsObject.DataFilterObject(menu.columnObject.key, menu.columnObject.path, itemKey, menu.columnObject.dataType == "bool" ? "False" : null)], menu.getFilterItemsForEditors());

        filtersForm.action = function () {
            this.changeVisibleState(false);
            var filters = menu.getNotThisColumnFilters();
            var resultFilters = filtersForm.filterControl.getFilters();
            menu.contentAttributes.filters = filters.concat(resultFilters);
            jsObject.ApplyFiltersToDashboardElement(element, menu.contentAttributes.filters);
        }
    }

    menu.setSortDirection = function (direction) {
        var currentSort = this.getThisColumnSort();
        var columnKey = this.columnObject.key;

        if (currentSort == null && direction != "None") {
            this.contentAttributes.sorts.push(jsObject.DataSortObject(columnKey, direction));
        }
        else {
            if (direction == "None") {
                jsObject.RemoveElementFromArray(this.contentAttributes.sorts, currentSort);
            }
            else {
                currentSort.direction = direction;
            }
        }

        jsObject.ApplySortsToDashboardElement(element, this.contentAttributes.sorts);
    }

    menu.getFilters = function () {
        var filters = this.getNotThisColumnFilters();

        if (this.items["selectAll"].isChecked)
            return filters;

        var itemsCount = menu.filterItems.length;
        var itemsCheckedCount = menu.getFilterItemsCheckedCount();
        var conditionGroupType = itemsCheckedCount > 0 && itemsCheckedCount <= itemsCount / 2 ? "Equal" : "NotEqual";
        var columnKey = this.columnObject.key;
        var columnPath = this.columnObject.path;
        var filter;

        for (var itemName in this.items) {
            var item = this.items[itemName];
            if (item.name && item.name.indexOf("filterItem") == 0) {
                var itemKey = item.key;
                var filterString = itemKey.filterString;

                if (item.isChecked && conditionGroupType == "Equal") {
                    if (itemKey.isNullValue)
                        filter = jsObject.DataFilterObject(columnKey, columnPath, "IsNull");
                    else if (itemKey.isBlankValue)
                        filter = jsObject.DataFilterObject(columnKey, columnPath, "IsBlank");
                    else
                        filter = jsObject.DataFilterObject(columnKey, columnPath, "EqualTo", filterString);

                    filters.push(filter);
                }
                else if (!item.isChecked && conditionGroupType == "NotEqual") {
                    if (itemKey.isNullValue)
                        filter = jsObject.DataFilterObject(columnKey, columnPath, "IsNotNull");
                    else if (itemKey.isBlankValue)
                        filter = jsObject.DataFilterObject(columnKey, columnPath, "IsNotBlank");
                    else
                        filter = jsObject.DataFilterObject(columnKey, columnPath, "NotEqualTo", filterString);

                    filters.push(filter);
                }
            }
        }        

        return filters;
    }

    menu.getThisColumnSort = function () {
        var contentAttrs = this.contentAttributes;
        for (var i = 0; i < contentAttrs.sorts.length; i++) {
            if (contentAttrs.sorts[i].key == this.columnObject.key) {
                return contentAttrs.sorts[i];
            }
        }
        return null;
    }

    menu.getThisColumnFilters = function () {
        var contentAttrs = this.contentAttributes;
        var filters = [];
        for (var i = 0; i < contentAttrs.filters.length; i++) {
            var filter = contentAttrs.filters[i];

            if (filter.key == this.columnObject.key || (!filter.key && filter.path == this.columnObject.path)) {
                filters.push(filter);
            }
        }
        return filters;
    }

    menu.getNotThisColumnFilters = function () {
        var contentAttrs = this.contentAttributes;
        var filters = [];
        for (var i = 0; i < contentAttrs.filters.length; i++) {
            var filter = contentAttrs.filters[i];
            if (filter.key == this.columnObject.key || (!filter.key && filter.path == this.columnObject.path)) {
                continue;
            }
            else {
                filters.push(filter);
            }
        }
        return filters;
    }

    menu.getDataFilterConditionGroupType = function (filters) {

        if (filters.length == 0) {
            return "Empty";
        }

        if (filters.every(function (r) { return (r.condition == "EqualTo" || r.condition == "IsBlank" || r.condition == "IsNull") })) {
            return "Equal";
        };

        if (filters.every(function (r) { return (r.condition == "NotEqualTo" || r.condition == "IsNotBlank" || r.condition == "IsNotNull") })) {
            return "NotEqual";
        };

        return "Custom";
    }

    menu.checkCondition = function (filterType, value, filters) {

        if (filterType == "Equal") {
            if (value == null)
                return filters.some(function (r) { return (r.condition == "IsNull") });

            if (value == "")
                return filters.some(function (r) { return (r.condition == "IsBlank") });

            return filters.some(function (r) { return (r.value == value) });
        }

        if (filterType == "NotEqual") {
            if (value == null)
                return !filters.some(function (r) { return (r.condition == "IsNotNull") });

            if (value == "")
                return !filters.some(function (r) { return (r.condition == "IsNotBlank") });

            return !filters.some(function (r) { return (r.value == value) });
        }

        return false;
    }

    menu.selectAllFilterItems = function(state) {
        if (this.items["selectAll"])
            this.items["selectAll"].setChecked(state);

        for (var itemName in this.items) {
            var item = this.items[itemName];
            if (item.name && item.name.indexOf("filterItem") == 0) {
                this.items[itemName].setChecked(state);
            }
        }
    }

    menu.updateSelectAllItemState = function () {
        var isChecked = true;

        for (var itemName in this.items) {
            var item = this.items[itemName];
            if (item.name && item.name.indexOf("filterItem") == 0) {
                if (!this.items[itemName].isChecked) {
                    isChecked = false;
                    break;
                }
            }
        }        

        if (this.items["selectAll"])
            this.items["selectAll"].setChecked(isChecked);
    }

    menu.updateRemoveFilterItemState = function () {
        if (this.items["removeFilter"])
            this.items["removeFilter"].setEnabled(menu.getThisColumnFilters().length != 0);
    }

    menu.getFilterItemsCheckedCount = function () {
        var checkedCount = 0;

        for (var itemName in this.items) {
            var item = this.items[itemName];
            if (item.name && item.name.indexOf("filterItem") == 0 && item.isChecked) {
                checkedCount++;
            }
        }

        return checkedCount;
    }

    menu.getFilterItemsForEditors = function () {
        var items = [];

        if (this.filterItems) {
            for (var i = 0; i < this.filterItems.length; i++) {
                var filterItem = this.filterItems[i];
                if (filterItem.key && !filterItem.key.isNullValue && !filterItem.key.isBlankValue) {
                    items.push(jsObject.Item("filterItem" + i, filterItem.key.filterString, null, filterItem.key.filterString));
                }
            }
        }

        return items;
    }

    //override
    menu.addItems = function (items) {
        var itemsContainer = this.innerContent;

        if (items && items.length) {
            for (var i = 0; i < items.length; i++) {
                if (typeof (items[i]) != "string") {
                    itemsContainer.appendChild(jsObject.SortFilterMenuItem(this, items[i].name, items[i].caption, items[i].imageName, items[i].key, items[i].haveSubMenu, itemStyleName));

                    if (items[i].name == "selectAll") {
                        filterContainer = document.createElement("div");
                        filterContainer.style.overflowY = "auto";
                        filterContainer.style.overflowX = "visible";
                        if (!jsObject.options.isMobileDevice) filterContainer.style.maxHeight = "180px";
                        filterContainer.style.borderTop = "1px dotted #c6c6c6";
                        this.innerContent.appendChild(filterContainer);
                        itemsContainer = filterContainer;
                    }
                }
                else {
                    itemsContainer.appendChild(jsObject.VerticalMenuSeparator(this, items[i]));
                }
            }
        }
    }
        
    return menu; 
}

StiJsViewer.prototype.SortFilterMenuItem = function (menu, itemName, caption, imageName, key, haveSubMenu, itemStyleName) {
    var item = this.VerticalMenuItem(menu, itemName, (caption && caption.length > 40) ? caption.substring(0, 40) + "..." : caption,
        imageName || "CheckBox.png", key, itemStyleName || "stiJsViewerMenuStandartItem", haveSubMenu, imageName ? null : { width: 13, height: 13 })

    var jsObject = this;
    var imgRect = document.createElement("div");
    item.cellImage.appendChild(imgRect);
    imgRect.appendChild(item.image);
    imgRect.style.padding = "2px 1px 0 1px";
    imgRect.style.boxSizing = "content-box";    
    imgRect.style.width = imgRect.style.height = "16px";
    imgRect.style.border = "1px solid transparent";
    if (item.imageName == "CheckBox.png") {
        item.image.style.display = "none";
    }

    item.setChecked = function (state) {
        this.isChecked = state;
        if (this.imageName == "CheckBox.png") {
            this.image.style.display = state ? "" : "none";
        }
        imgRect.style.border = "1px solid " + (state ? "#ababab" : "transparent");
    }

    return item;
}

StiJsViewer.prototype.InitializeSubMenu = function (name, items, parentButton, parentMenu, itemStyleName, menuStyleName) {

    var menu = this.HorizontalMenu(name, parentButton, "Right", items, itemStyleName, menuStyleName);
    menu.parentMenu = parentMenu;
    parentButton.menu = menu;

    parentButton.showSubMenu = function () {
        if (parentMenu.currentSubMenu && parentButton.menu != parentMenu.currentSubMenu) {
            parentMenu.currentSubMenu.changeVisibleState(false);
        }
        if (!parentButton.menu.visible) {
            parentButton.menu.changeVisibleState(true);
            parentMenu.currentSubMenu = parentButton.menu;
        }
    }

    parentButton.action = function () {
        this.onmouseover();
    }

    if (!this.options.isTouchDevice) {
        parentButton.onmouseover = function () {
            if (!this.isEnabled) return;
            this.className = this.styleName + " " + this.styleName + "Over";
            this.isOver = true;
            clearTimeout(parentMenu.subMenuShowTimer);
            clearTimeout(parentMenu.subMenuHideTimer);
            parentMenu.subMenuShowTimer = setTimeout(function () {
                if (parentButton.isOver) parentButton.showSubMenu();
            }, 200);
        }

        try {
            for (var itemName in parentMenu.items) {
                if (itemName.indexOf("separator") != 0 && !parentMenu.items[itemName].haveSubMenu && parentMenu.items[itemName] != parentButton) {
                    parentMenu.items[itemName].onmouseenter = function () {
                        if (!this.isEnabled || this.jsObject.options.isTouchClick) return;
                        this.className = this.styleName + " " + this.styleName + "Over";
                        this.isOver = true;
                        clearTimeout(parentMenu.subMenuShowTimer);
                        clearTimeout(parentMenu.subMenuHideTimer);
                        parentMenu.subMenuHideTimer = setTimeout(function () {
                            if (menu.currentSubMenu) menu.currentSubMenu.changeVisibleState(false);
                            menu.changeVisibleState(false);
                        }, 200);
                    }
                }
            }
        }
        catch (e) { console.log(e); }

        menu.onmouseover = function () {
            clearTimeout(parentMenu.subMenuHideTimer);
        }
    }

    menu.action = function (menuItem) {
        menu.changeVisibleState(false);
        parentMenu.changeVisibleState(false);
        parentMenu.action(menuItem);
    }

    return menu;
}

StiJsViewer.prototype.HorizontalMenu = function (name, parentButton, animDirection, items, itemStyleName, menuStyleName) {
    var menu = this.BaseMenu(name, parentButton, animDirection, menuStyleName);
    menu.itemStyleName = itemStyleName;

    menu.clear = function () {
        while (this.innerContent.childNodes[0]) {
            this.innerContent.removeChild(this.innerContent.childNodes[0]);
        }
    }

    menu.addItems = function (items) {
        this.clear();
        if (items && items.length) {
            for (var i = 0; i < items.length; i++) {
                if (typeof (items[i]) != "string") {
                    var item = this.jsObject.VerticalMenuItem(this, items[i].name, items[i].caption, items[i].imageName, items[i].key, this.itemStyleName, items[i].haveSubMenu);
                    this.innerContent.appendChild(item);
                }
                else {
                    this.innerContent.appendChild(this.jsObject.VerticalMenuSeparator(this, items[i]));
                }
            }
        }
    }

    menu.onmousedown = function () {
        if (!this.isTouchStartFlag) this.ontouchstart(true);
    }

    menu.ontouchstart = function (mouseProcess) {
        var this_ = this;
        this.isTouchStartFlag = mouseProcess ? false : true;
        clearTimeout(this.isTouchStartTimer);
        this.jsObject.options.horMenuPressed = this;
        this.isTouchStartTimer = setTimeout(function () {
            this_.isTouchStartFlag = false;
        }, 1000);
    }
    
    menu.addItems(items);

    return menu;
}

StiJsViewer.prototype.CreateSvgElement = function (tagName) {
    return ("createElementNS" in document ? document.createElementNS("http://www.w3.org/2000/svg", tagName) : document.createElement(tagName));
}

StiJsViewer.prototype.ColumnIsNumericType = function (type) {
    return (
        type == "sbyte" ||
        type == "byte" ||
        type == "short" ||
        type == "ushort" ||
        type == "int" ||
        type == "uint" ||
        type == "long" ||
        type == "ulong" ||
        type == "float" ||
        type == "decimal" ||
        type == "double"
    );
}

StiJsViewer.prototype.ColumnIsDateType = function (type) {
    return (
        type == "datetime" ||
        type == "timespan"
    );
}

StiJsViewer.prototype.DataFilterObject = function (key, path, condition, value, value2, isEnabled, isExpression) {
    return {
        typeItem: "FilterRule",
        key: key,
        path: path,
        condition: typeof (condition) != "undefined" ? condition : "EqualTo",
        value: typeof (value) != "undefined" ? value : null,
        value2: typeof (value2) != "undefined" ? value2 : null,
        isEnabled: typeof (isEnabled) != "undefined" ? isEnabled : true,
        isExpression: typeof (isExpression) != "undefined" ? isExpression : false
    }
}

StiJsViewer.prototype.DataSortObject = function (key, direction) {
    return {
        typeItem: "SortRule",
        key: key,
        direction: direction
    }
}

StiJsViewer.prototype.RemoveElementFromArray = function (array, element) {
    for (var i = 0; i < array.length; i++) {
        if (element == array[i]) {
            array.splice(array.indexOf(element), 1);
        }
    }
}

StiJsViewer.prototype.FiltersControl = function (name, width, height) {
    var filterControl = document.createElement("div");
    var jsObject = this;
    filterControl.controls = {};
    filterControl.name = name;
    filterControl.columnObject = null;

    //ToolBar
    var toolBar = this.CreateHTMLTable();
    toolBar.style.margin = "4px";
    filterControl.appendChild(toolBar);

    var controlProps = [
        ["addFilter", this.SmallButton(null, this.collections.loc["AddFilter"], "Dashboards.AddFilter.png")],
        ["separator"],
        ["moveUp", this.SmallButton(null, null, "Dashboards.MoveUp.png")],
        ["moveDown", this.SmallButton(null, null, "Dashboards.MoveDown.png")],
        ["separator"],
        ["filterOn", this.CheckBox(null, this.collections.loc["FilterOn"])]
    ]

    for (var i = 0; i < controlProps.length; i++) {
        if (controlProps[i][0] == "separator") {
            toolBar.addCell(this.ToolBarSeparator());
            continue;
        }
        var control = controlProps[i][1];
        control.style.margin = "0 2px 0 2px";
        filterControl.controls[controlProps[i][0]] = control;
        if (controlProps[i][0] == "filterOn") {
            control.style.margin = "0 6px 0 6px";
        }
        toolBar.addCell(control);
    }

    //Container
    var container = this.FiltersContainer(filterControl);
    container.style.width = (width ? width : 600) + "px";
    container.style.height = (height ? height : 300) + "px";
    filterControl.appendChild(container);

    filterControl.controls.addFilter.action = function () {
        container.addFilter(jsObject.DataFilterObject(filterControl.columnObject.key, filterControl.columnObject.path, "EqualTo",
            filterControl.columnObject.dataType == "bool" ? "False" : null, null, filterControl.controls.filterOn.isChecked));
    }

    filterControl.controls.moveUp.setEnabled(false);
    filterControl.controls.moveDown.setEnabled(false);

    filterControl.controls.moveUp.action = function () {
        if (container.selectedItem) {
            container.selectedItem.move("Up");
        }
    }

    filterControl.controls.moveDown.action = function () {
        if (container.selectedItem) {
            container.selectedItem.move("Down");
        }
    }

    filterControl.controls.filterOn.action = function () {
        for (var i = 0; i < container.childNodes.length; i++) {
            var filterItem = container.childNodes[i];
            filterItem.filter.isEnabled = this.isChecked;
        }
    }

    container.onAction = function () {
        var count = container.getCountItems();
        var index = container.selectedItem ? container.selectedItem.getIndex() : -1;
        filterControl.controls.moveUp.setEnabled(index > 0);
        filterControl.controls.moveDown.setEnabled(index != -1 && index < count - 1);
    }

    filterControl.setFilters = function (filters) {
        container.clear();
        filterControl.controls.filterOn.setChecked(true);

        if (!filters) return;

        for (var i = 0; i < filters.length; i++) {
            container.addFilter(filters[i], true);
            if (i == 0) {
                filterControl.controls.filterOn.setChecked(filters[i].isEnabled);
            }
        }

        container.onAction();
    }

    filterControl.getFilters = function () {
        var filters = [];

        for (var i = 0; i < container.childNodes.length; i++) {
            filters.push(container.childNodes[i].filter)
        }

        return filters;
    }

    return filterControl;
}

StiJsViewer.prototype.FiltersContainer = function (filterControl) {
    var container = document.createElement("div");
    var jsObject = this;
    container.className = "stiDesignerFilterContainer";
    container.selectedItem = null;
    container.filterControl = filterControl;

    container.addFilter = function (filter, notAction) {
        var filterItem = jsObject.FilterItem(container, filter);
        this.appendChild(filterItem);
        if (!notAction) container.onAction();
        if (filterItem.valueControl && filterItem.valueControl.textBox && filterItem.valueControl.textBox["focus"] && !filterItem.valueControl.readOnly) {
            filterItem.valueControl.textBox.focus();
        }
    }

    container.clear = function () {
        while (this.childNodes[0]) this.removeChild(this.childNodes[0]);
    }

    container.getCountItems = function () {
        return this.childNodes.length;
    }

    container.onAction = function () { };

    return container;
}

StiJsViewer.prototype.FilterItem = function (filterContainer, filter) {
    var filterItem = document.createElement("div");
    var columnObject = filterContainer.filterControl.columnObject;
    var jsObject = this;
    filterItem.key = this.newGuid().replace(/-/g, '');
    filterItem.isSelected = false;
    filterItem.filter = filter;
    filterItem.className = "stiJsViewerFilterPanel";

    //Header
    var header = this.CreateHTMLTable();
    header.className = "stiJsViewerFilterPanelHeader";
    header.style.width = "100%";
    filterItem.appendChild(header);

    var headerButton = this.SmallButton(null, this.collections.loc["Filter"], "CheckBox.png", null, null, null, null, { width: 13, height: 13 });
    headerButton.style.margin = "2px 0px 2px 2px";
    headerButton.image.style.visibility = "hidden";
    headerButton.caption.style.width = "100%";
    headerButton.caption.style.textAlign = "center";
    headerButton.action = function () { };
    header.addCell(headerButton).style.width = "100%";

    var removeButton = this.SmallButton(null, null, "RemoveItemButton.png");
    removeButton.style.margin = "2px 2px 2px 0px";
    header.addCell(removeButton);

    removeButton.action = function () {
        filterItem.remove();
    }

    header.onclick = function () {
        if (this.isTouchEndFlag || jsObject.options.isTouchClick) return;
        this.action();
    }

    header.ontouchend = function () {
        if (jsObject.options.fingerIsMoved) return;
        var this_ = this;
        this.isTouchEndFlag = true;
        clearTimeout(this.isTouchEndTimer);
        this.action();
        this.isTouchEndTimer = setTimeout(function () {
            this_.isTouchEndFlag = false;
        }, 1000);
    }

    header.action = function () {
        filterItem.setSelected(!filterItem.isSelected);
        filterContainer.onAction();
    }

    headerButton.oldonmouseenter = headerButton.onmouseenter;
    headerButton.oldonmouseleave = headerButton.onmouseleave;

    headerButton.onmouseenter = function () {
        headerButton.oldonmouseenter();
        removeButton.onmouseenter();
    }

    headerButton.onmouseleave = function () {
        headerButton.oldonmouseleave();
        removeButton.onmouseleave();
    }

    filterItem.setSelected = function (state) {
        if (state) {
            if (filterContainer.selectedItem) filterContainer.selectedItem.setSelected(false);
            filterContainer.selectedItem = this;
        }
        else {
            if (filterContainer.selectedItem && filterContainer.selectedItem == this) filterContainer.selectedItem = null;
        }
        filterItem.isSelected = state;
        headerButton.image.style.visibility = state ? "visible" : "hidden";
    }

    filterItem.remove = function () {
        filterContainer.removeChild(this);
        if (filterContainer.selectedItem == this) filterContainer.selectedItem = null;
        filterContainer.onAction();
    }

    filterItem.getIndex = function () {
        for (var i = 0; i < filterContainer.childNodes.length; i++)
            if (filterContainer.childNodes[i] == this) return i;
    };

    filterItem.move = function (direction) {
        var index = this.getIndex();
        filterContainer.removeChild(this);
        var count = filterContainer.getCountItems();
        var newIndex = direction == "Up" ? index - 1 : index + 1;
        if (direction == "Up" && newIndex == -1) newIndex = 0;
        if (direction == "Down" && newIndex >= count) {
            filterContainer.appendChild(this);
            filterContainer.onAction();
            return;
        }
        filterContainer.insertBefore(this, filterContainer.childNodes[newIndex]);
        filterContainer.onAction();
    }  
   
    var innerTable = this.CreateHTMLTable();
    innerTable.style.margin = "7px";
    filterItem.appendChild(innerTable);

    var conditionItems = [];

    if (jsObject.ColumnIsNumericType(columnObject.dataType)) {
        conditionItems = jsObject.GetFilterConditionItems("Numeric");
    }
    else if (jsObject.ColumnIsDateType(columnObject.dataType)) {
        conditionItems = jsObject.GetFilterConditionItems("DateTime");
    }
    else if (columnObject.dataType == "bool") {
        conditionItems = jsObject.GetFilterConditionItems("Boolean");
    }
    else {
        conditionItems = jsObject.GetFilterConditionItems("String");
    }

    //Condition
    var conditionControl = this.DropDownList(null, 145, null, conditionItems, true, false);
    conditionControl.style.marginRight = "7px";
    innerTable.addCell(conditionControl);
    conditionControl.setKey(filter.condition);

    conditionControl.action = function () {
        filter.condition = this.key;
        filterItem.updateControls();
    };

    //Value
    var valueControl;

    /*if (jsObject.ColumnIsDateType(columnObject.type)) {
        valueControl = this.DateControl(null, 130, null, true);

        if (!filter.isExpression) {
            valueControl.setKey(filter.value ? new Date(filter.value) : new Date());
        }
        else {
            valueControl.textBox.value = filter.value;
        }

        valueControl.action = function () {
            filter.value = !filter.isExpression
                ? this.jsObject.formatDate(this.key, "MM/dd/yyyy")
                : this.textBox.value;
        }
    }
    else*/ if (columnObject.dataType == "bool") {
        valueControl = this.DropDownList(null, 160, null, this.GetBoolItems());
        valueControl.setKey(filter.value);

        valueControl.action = function () {
            filter.value = this.key;
        }
    }
    else {
        valueControl = this.DropDownList(null, 160, null, filterContainer.filterControl.filterItems);
        valueControl.textBox.value = filter.value || "";

        valueControl.action = function () {
            filter.value = this.textBox.value;
        }
    }

    valueControl.style.marginRight = "7px";
    innerTable.addCell(valueControl);
    filterItem.valueControl = valueControl;

    //And Caption
    var andCaption = innerTable.addTextCell(this.collections.loc["FilterModeAnd"]);

    //Value2
    var value2Control;

    /*if (jsObject.ColumnIsDateType(columnObject.dataType)) {
        value2Control = this.DateControl(null, 13, null, true);

        if (!filter.isExpression) {
            value2Control.setKey(filter.value2 ? new Date(filter.value2) : new Date());
        }
        else {
            value2Control.textBox.value = filter.value2;
        }

        value2Control.action = function () {
            filter.value2 = !filter.isExpression
                ? this.jsObject.formatDate(this.key, "MM/dd/yyyy")
                : this.textBox.value;
        }
    }
    else */{
        value2Control = this.DropDownList(null, 160, null, filterContainer.filterControl.filterItems);
        value2Control.textBox.value = filter.value2 || "";

        value2Control.action = function () {
            filter.value2 = this.textBox.value;
        }
    }

    value2Control.style.margin = "0 7px 0 7px";
    innerTable.addCell(value2Control);

    //Expression
    var isExpressionControl = this.CheckBox(null, this.collections.loc["Expression"]);
    isExpressionControl.style.marginRight = "7px";
    innerTable.addCell(isExpressionControl);
    isExpressionControl.setChecked(filter.isExpression);

    isExpressionControl.action = function () {
        filter.isExpression = this.isChecked;
        filterItem.updateControls();
        if (!this.isChecked) {
            if (columnObject.dataType == "bool") {
                valueControl.setKey("False");
            }
            //else if (jsObject.ColumnIsDateType(columnObject.dataType)) {
            //    valueControl.setKey(new Date());
            //}
            else {
                valueControl.textBox.value = "";
                valueControl.textBox.focus();
            }
        }
    }
    
    filterItem.updateControls = function () {        
        var showValue2 = filter.condition == "Between" || filter.condition == "NotBetween";
        var showValues = filter.condition != "IsNull" && filter.condition != "IsNotNull" && filter.condition != "IsBlank" && filter.condition != "IsNotBlank";
        valueControl.style.display = showValues ? "" : "none";
        value2Control.style.display = showValues && showValue2 ? "" : "none";
        andCaption.style.display = showValue2 ? "" : "none";
        isExpressionControl.style.display = showValues ? "" : "none";

        valueControl.button.parentElement.style.visibility = !filter.isExpression ? "visible" : "hidden";
        value2Control.button.parentElement.style.visibility = !filter.isExpression ? "visible" : "hidden";

        if (columnObject.dataType == "bool") {
            valueControl.readOnly = valueControl.textBox.readOnly = !filter.isExpression;
        }
        //else if (jsObject.ColumnIsDateType(columnObject.dataType)) {
        //    valueControl.textBox.readOnly = !filter.isExpression;
        //    value2Control.textBox.readOnly = !filter.isExpression;
        //}
    }

    filterItem.updateControls();

    return filterItem;
}

StiJsViewer.prototype.InitializeFiltersForm = function () {
    var form = this.BaseForm("filtersForm", this.collections.loc["Filters"], 2);
    form.container.style.padding = 0;

    var filterControl = this.FiltersControl("filtersFormFilterControl", 700, 350);
    form.filterControl = filterControl;
    form.container.appendChild(filterControl);
    
    form.show = function (columnObject, filters, filterItems) {
        this.changeVisibleState(true);
        filterControl.columnObject = columnObject;
        filterControl.filterItems = filterItems;
        filterControl.setFilters(this.jsObject.copyObject(filters));
    }

    return form;
}

StiJsViewer.prototype.CreateComboBoxElementContent = function (element) {
    var jsObject = this;
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;

    var mainButton = this.SmallButton(null, " ", null, null, "Down", null, contentAttrs.settings);
    jsObject.ApplyAttributesToObject(mainButton.innerTable, elementAttrs);
    mainButton.innerTable.style.minHeight = "auto";
    mainButton.style.height = mainButton.innerTable.style.height = "100%";
    mainButton.style.border = "0";
    mainButton.style.overflow = "hidden";
    mainButton.caption.style.width = "100%";
    mainButton.caption.style.padding = "0 4px 0 4px";

    element.contentPanel.appendChild(mainButton);
    element.contentPanel.style.overflow = "hidden";

    var menuName = elementAttrs.name + "ComboBoxMenu";
    var menu = this.controls.menus && this.controls.menus[menuName] ? this.controls.menus[menuName] : this.VerticalMenu(menuName, mainButton, "Down");
    menu.parentButton = mainButton;

    mainButton.action = function () {
        menu.changeVisibleState(!menu.visible);
    }

    var itemsPanel = document.createElement("div");
    itemsPanel.style.left = itemsPanel.style.top = itemsPanel.style.right = itemsPanel.style.bottom = "0px";
    itemsPanel.style.overflow = "auto";

    var parentPanel = menu.innerContent;
    parentPanel.style.width = mainButton.offsetWidth + "px";
    parentPanel.style.backgroundColor = elementAttrs.backColor;

    if (contentAttrs.showAllValue && contentAttrs.selectionMode == "Multi") {
        parentPanel.style.overflow = "hidden";
        itemsPanel.style.maxHeight = "350px";
    }
    
    mainButton.update = function () {
        if (contentAttrs.selectionMode == "One") {
            for (var i = 0; i < itemsPanel.childNodes.length; i++) {
                if (itemsPanel.childNodes[i].isSelected) {
                    mainButton.caption.innerHTML = itemsPanel.childNodes[i].caption.innerHTML;
                }
            }
        }
        else {
            var onRemoveButton = function (button) {
                if (button.item.value == "StiUnCheckAll") {
                    element.setStatesForAllItems(false);
                    jsObject.ApplyFiltersToDashboardElement(element, element.getFilters());
                }
                else {
                    button.item.setChecked(false);
                    button.item.action();
                }
            }
            
            var checkItems = [];
            var unCheckItems = [];

            for (var i = 0; i < itemsPanel.childNodes.length; i++) {
                if (itemsPanel.childNodes[i].button != null) {
                    if (itemsPanel.childNodes[i].isChecked)
                        checkItems.push(itemsPanel.childNodes[i]);
                    else
                        unCheckItems.push(itemsPanel.childNodes[i]);
                }
            }
                        
            mainButton.caption.innerHTML = "";
            var captionWidth = mainButton.caption.offsetWidth;

            if (unCheckItems.length == 0) {
                mainButton.caption.innerHTML = "";
                mainButton.caption.appendChild(jsObject.ComboBoxCaptionButton(jsObject.collections.loc.All, { value: "StiUnCheckAll" }, onRemoveButton, contentAttrs.settings, elementAttrs));
            }
            else if (checkItems.length > 0) {
                var сaptionNotFit = false;

                for (var i = 0; i < checkItems.length; i++) {
                    mainButton.caption.appendChild(jsObject.ComboBoxCaptionButton(checkItems[i].button.caption.innerHTML, checkItems[i], onRemoveButton, contentAttrs.settings, elementAttrs));

                    if (mainButton.caption.offsetWidth > captionWidth) {
                        mainButton.caption.innerHTML = "";
                        сaptionNotFit = true;
                        break;
                    }
                }
                if (сaptionNotFit ) {
                    mainButton.caption.appendChild(jsObject.ComboBoxCaptionButton(jsObject.collections.loc.DashboardNSelected.replace("{0}", checkItems.length),
                        { value: "StiUnCheckAll" }, onRemoveButton, contentAttrs.settings, elementAttrs));
                }
            }
        }

        mainButton.setEnabled(itemsPanel.childNodes.length > 0);
    }

    var actionFunction = function () {        
        if (contentAttrs.selectionMode == "One") {
            menu.changeVisibleState(false);            
        }
        mainButton.update();
    }

    jsObject.CreateListBoxItemsContent(element, itemsPanel, parentPanel, actionFunction);

    mainButton.update();
}

StiJsViewer.prototype.ComboBoxCaptionButton = function (caption, item, actionFunction, styleColors, elementAttrs) {
    var button = this.SmallButton(null, caption, null, null, "Down");
    button.item = item;

    //override
    button.style.display = "inline-block";
    button.arrow.src = this.collections.images["CloseForm.png"];
    button.style.backgroundColor = styleColors.selectedBackColor;
    button.style.color = styleColors.selectedForeColor;
    button.style.border = "0";
    button.style.boxSizing = "border-box";
    button.style.marginRight = "4px";
    button.style.height = "100%";
    button.style.fontSize = (elementAttrs && elementAttrs.font.size ? elementAttrs.font.size : "10") + "pt";
    button.arrow.parentNode.style.padding = "0 2px 0 0";
    button.arrow.style.margin = "0 0 1px 0";
    button.arrow.style.opacity = "0.6";
    if (button.caption) button.caption.style.padding = "0 2px 0 4px";

    button.onmouseoverAction = function () {
        if (this.jsObject.options.isTouchClick) return;
        this.isOver = true;
        this.style.backgroundColor = styleColors.hotSelectedBackColor;
        this.style.color = styleColors.hotSelectedForeColor;
    }

    button.onmouseoutAction = function () {
        this.isOver = false;
        this.style.backgroundColor = styleColors.selectedBackColor;
        this.style.color = styleColors.selectedForeColor;
    }

    button.arrow.onmouseover = function () {
        this.style.opacity = "1";
    }

    button.arrow.onmouseout = function () {
        this.style.opacity = "0.6";
    }

    button.arrow.onclick = function (event) {
        button.parentNode.removeChild(button);
        actionFunction(button);
        event.stopPropagation();
    }

    return button;
}

StiJsViewer.prototype.CreateDatePickerElementContent = function (element) {
    var jsObject = this;
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;

    var mainButton = this.SmallButton(null, " ", null, null, "Down", null, contentAttrs.settings);
    jsObject.ApplyAttributesToObject(mainButton.innerTable, elementAttrs);
    mainButton.innerTable.style.minHeight = "auto";
    mainButton.style.height = mainButton.innerTable.style.height = "100%";
    mainButton.style.border = "0";
    mainButton.style.overflow = "hidden";
    mainButton.caption.style.width = "100%";
    mainButton.caption.style.padding = "0 4px 0 4px";

    element.contentPanel.appendChild(mainButton);
    element.contentPanel.style.overflow = "hidden";

    mainButton.update = function () {
        var filters = contentAttrs.filters;
        var firstDate = new Date();
        var secondDate = null;

        if (filters.length == 0) {
            if (contentAttrs.selectionMode == "AutoRange") {
                if (contentAttrs.autoRangeValues) {
                    try {
                        firstDate = new Date(contentAttrs.autoRangeValues.selectionStart);
                        secondDate = new Date(contentAttrs.autoRangeValues.selectionEnd);
                    }
                    catch (e) { };
                }
            }
            else if (contentAttrs.selectionMode == "Range") {
                var values = jsObject.GetValuesByDateRangeName(jsObject.ConvertDateRangeSelectionToDateRangeKind(contentAttrs.initialRangeSelection));
                if (values) {
                    firstDate = values[0];
                    secondDate = values[1];
                }
            }
        }
        else {
            try {
                if (filters[0].value) firstDate = new Date(filters[0].value);
                if (filters[0].value2) secondDate = new Date(filters[0].value2);
            }
            catch (e) { };
        }
        
        var caption = firstDate.toLocaleDateString();
        if (secondDate) caption += " - " + secondDate.toLocaleDateString();

        mainButton.firstDate = firstDate;
        mainButton.secondDate = secondDate || new Date();        

        var getStringDate = function (date) {
            var dateObj = jsObject.getDateTimeObject(date);
            return dateObj.month + "/" + dateObj.day + "/" + dateObj.year;
        }

        var dateValues = { value1: getStringDate(firstDate) };
        if (secondDate) dateValues.value2 = getStringDate(secondDate);

        jsObject.postAjax(jsObject.options.requestUrl.replace("{action}", jsObject.options.actions.viewerEvent),
            {
                action: "GetDatePickerFormattedValues",
                dateValues: dateValues,
                datePickerElementName: elementAttrs.name
            },
            function (data) {
                if (data) {
                    var answer = JSON.parse(data);
                    if (answer && answer.value1) {
                        caption = answer.value1;
                        if (answer.value2) caption += " - " + answer.value2;
                    }
                }
                mainButton.caption.innerHTML = caption;
            });
    }

    mainButton.update();

    mainButton.action = function () {
        if (contentAttrs.selectionMode == "Single") {
            var datePicker = jsObject.controls.datePicker;
            if (!datePicker.visible) {
                datePicker.key = this.firstDate;
                datePicker.parentButton = this;
                datePicker.changeVisibleState(true);
            }
            else {
                datePicker.changeVisibleState(false);
            }

            datePicker.action = function () {
                contentAttrs.filters = [{ condition: contentAttrs.condition, value: jsObject.formatDate(this.key, "MM/dd/yyyy"), path: contentAttrs.columnPath }];
                mainButton.update();
                jsObject.ApplyFiltersToDashboardElement(element, contentAttrs.filters);
            }
        }
        else {
            var params = {
                firstParentButton: mainButton,
                secondParentButton: mainButton
            }

            var datePicker = jsObject.InitializeDoubleDatePicker(params);
            datePicker.firstDatePicker.key = this.firstDate;
            datePicker.secondDatePicker.key = this.secondDate;
            datePicker.changeVisibleState(!datePicker.visible, mainButton);

            datePicker.action = function () {
                var value = jsObject.formatDate(this.firstDatePicker.key, "MM/dd/yyyy");
                var value2 = jsObject.formatDate(this.secondDatePicker.key, "MM/dd/yyyy");
                contentAttrs.filters = [{ condition: "Between", value: value, value2: value2, path: contentAttrs.columnPath }];
                mainButton.update();
                jsObject.ApplyFiltersToDashboardElement(element, contentAttrs.filters);
            }
        }
    }    
}

StiJsViewer.prototype.ConvertDateRangeSelectionToDateRangeKind = function (rangeSelection) {
    switch (rangeSelection) {
        case "DayTomorrow": return "Tomorrow";
        case "DayToday": return "Today";
        case "DayYesterday": return "Yesterday";
        case "WeekNext": return "NextWeek";
        case "WeekCurrent": return "CurrentWeek";
        case "WeekPrevious": return "PreviousWeek";
        case "MonthNext": return "NextMonth";
        case "MonthCurrent": return "CurrentMonth";
        case "MonthPrevious": return "PreviousMonth";
        case "QuarterNext": return "NextQuarter";
        case "QuarterCurrent": return "CurrentQuarter";
        case "QuarterPrevious": return "PreviousQuarter";
        case "QuarterFirst": return "FirstQuarter";
        case "QuarterSecond": return "SecondQuarter";
        case "QuarterThird": return "ThirdQuarter";
        case "QuarterFourth": return "FourthQuarter";
        case "YearNext": return "NextYear";
        case "YearCurrent": return "CurrentYear";
        case "YearPrevious": return "PreviousYear";
        case "Last7Days": return "Last7Days";
        case "Last14Days": return "Last14Days";
        case "Last30Days": return "Last30Days";
        case "DateToWeek": return "WeekToDate";
        case "DateToMonth": return "MonthToDate";
        case "DateToQuarter": return "QuarterToDate";
        case "DateToYear": return "YearToDate";
    }

    return "Today";
}

StiJsViewer.prototype.TreeItem = function (caption, imageName, itemObject, tree, showCheckBox, id, styleColors) {
    var treeItem = this.CreateHTMLTable();
    treeItem.id = id || this.newGuid().replace(/-/g, '');
    var jsObject = treeItem.jsObject = this;
    treeItem.isSelected = false;
    treeItem.isOpening = false;
    treeItem.isChecked = false;
    treeItem.itemObject = itemObject;
    treeItem.tree = tree;
    tree.items[treeItem.id] = treeItem;
    treeItem.childs = {};
    treeItem.parent = null;

    //Opening icon
    var iconOpening = document.createElement("img");
    treeItem.iconOpening = iconOpening;
    treeItem.addCell(iconOpening).style.width = "1px";
    iconOpening.treeItem = treeItem;
    iconOpening.src = this.collections.images["Dashboards.IconOpenItem" + (styleColors && styleColors.isDarkStyle ? "White.png" : ".png")];
    iconOpening.className = "stiJsViewerTreeItemIconOpening";
    iconOpening.style.visibility = "hidden";
    iconOpening.style.opacity = "0.6";

    iconOpening.onmouseover = function () {
        if (jsObject.options.isTouchClick) return;
        this.style.opacity = "1";
    }

    iconOpening.onmouseout = function () {
        this.style.opacity = "0.6";
    }

    iconOpening.onmousedown = function () {
        if (this.isTouchStartFlag) return;
        this.action();
    }

    iconOpening.ontouchstart = function () {
        var this_ = this;
        this.isTouchStartFlag = true;
        clearTimeout(this.isTouchStartTimer);
        this.action();
        this.isTouchStartTimer = setTimeout(function () {
            this_.isTouchStartFlag = false;
        }, 1000);
    }

    iconOpening.action = function () {
        if (tree.isDisable) return;
        treeItem.isOpening = !treeItem.isOpening;
        treeItem.childsRow.style.display = treeItem.isOpening ? "" : "none";
        var imgName = (treeItem.isOpening ? "Dashboards.IconCloseItem" : "Dashboards.IconOpenItem") + (styleColors && styleColors.isDarkStyle ? "White.png" : ".png");
        iconOpening.src = jsObject.collections.images[imgName];
    }

    //Button
    var button = this.CreateHTMLTable();
    button.className = "stiJsViewerTreeItem";
    treeItem.button = button;
    treeItem.addCell(button);

    if (styleColors) {
        button.style.borderRadius = "0";
        button.style.background = styleColors.backColor;
        button.style.color = styleColors.foreColor;
    }

    button.onmouseover = function () {
        if (jsObject.options.isTouchClick) return;        
        treeItem.isOver = true;

        if (styleColors) {
            this.style.background = treeItem.isSelected ? styleColors.hotSelectedBackColor : styleColors.hotBackColor;
            this.style.color = treeItem.isSelected ? styleColors.hotSelectedForeColor : styleColors.hotForeColor;
        }
        else {
            this.className = "stiJsViewerTreeItemOver";
        }
    }

    button.onmouseout = function () {
        treeItem.isOver = false;        
        if (styleColors) {
            this.style.background = treeItem.isSelected ? styleColors.selectedBackColor : styleColors.backColor;
            this.style.color = treeItem.isSelected ? styleColors.selectedForeColor : styleColors.foreColor;
        }
        else {
            this.className = treeItem.isSelected ? "stiJsViewerTreeItemSelected" : "stiJsViewerTreeItem";
        }
    }

    treeItem.getAllChilds = function (childsArray) {
        if (!childsArray) childsArray = [];
        for (var itemKey in this.childs) {
            childsArray.push(this.childs[itemKey]);
            this.childs[itemKey].getAllChilds(childsArray);
        }

        return childsArray;
    }

    //Checkbox
    if (showCheckBox) {
        var checkBox = this.CheckBox(null, null, null, styleColors);
        treeItem.checkBox = checkBox;
        button.addCell(checkBox).style.width = "1px";
        checkBox.style.marginLeft = "7px";

        treeItem.setChecked = function (state) {
            this.isChecked = state;
            checkBox.setChecked(state);
            treeItem.setIndeterminate(false);
        }

        treeItem.setIndeterminate = function (state) {
            checkBox.setIndeterminate(state);
        }

        checkBox.onmousedown = function () {
            treeItem.checkBoxClicked = true;
        }

        checkBox.action = function () {
            if (tree.isDisable) return;
            treeItem.setChecked(this.isChecked);

            var childs = treeItem.getAllChilds();
            for (var i = 0; i < childs.length; i++) {
                childs[i].setChecked(this.isChecked);
            }
            if (treeItem.parent && treeItem.parent.setChecked && this.isChecked) {
                treeItem.parent.setChecked(true);
            }
            if (tree["onChecked"])
                tree.onChecked(treeItem);
        }
    }

    if (imageName != null) {
        button.image = document.createElement("img");
        button.imageCell = button.addCell(button.image);
        button.imageCell.style.fontSize = "0px"
        if (jsObject.collections.images[imageName]) button.image.src = jsObject.collections.images[imageName];
        button.image.className = "stiJsViewerTreeItemImage";
    }

    if (caption != null || typeof (caption) == "undefined") {
        var captionCell = button.addCell();
        captionCell.className = "stiJsViewerTreeItemCaption";
        captionCell.style.padding = "2px 7px 2px 7px"
        captionCell.innerHTML = caption;
        button.captionCell = captionCell;
    }

    button.onmousedown = function () {
        if (this.isTouchStartFlag) return;
        if (!treeItem.checkBoxClicked) this.action();
        treeItem.checkBoxClicked = false;
    }

    button.ontouchstart = function () {
        var this_ = this;
        this.isTouchStartFlag = true;
        clearTimeout(this.isTouchStartTimer);
        this.action();
        this.isTouchStartTimer = setTimeout(function () {
            this_.isTouchStartFlag = false;
        }, 1000);
    }

    button.action = function () {
        if (tree.isDisable || showCheckBox) return;
        if (tree.selectedItem != treeItem) {
            treeItem.setSelected();
            tree.onActionItem(treeItem);
        }
        else
            treeItem.setSelected();
    }

    //ChildsRow
    treeItem.childsRow = treeItem.addRow();
    treeItem.childsRow.style.display = "none";

    //Empty Cell
    treeItem.addCellInLastRow();

    //Childs Container
    treeItem.childsContainer = treeItem.addCellInLastRow();
    treeItem.childsContainer.style.textAlign = "left";

    //Methods
    treeItem.addChild = function (childItem) {
        this.childsContainer.appendChild(childItem);
        childItem.parent = this;
        this.childs[childItem.id] = childItem;
        iconOpening.style.visibility = "visible";
        tree.onAddItem(childItem);

        return childItem;
    }

    treeItem.remove = function () {
        if (this.parent && this.parent.childsContainer.contains(this)) {
            var nextItem = this.nextSibling;
            if (!nextItem) nextItem = this.previousSibling;
            if (!nextItem) nextItem = this.parent;
            this.parent.childsContainer.removeChild(this);
            delete this.parent.childs[this.id];
            delete tree.items[this.id];
            for (var key in this.childs) {
                this.childs[key].remove();
            }
            this.parent.isOpening = jsObject.getCountObjects(this.parent.childs) > 0;
            this.parent.iconOpening.style.visibility = this.parent.isOpening ? "visible" : "hidden";
            if (nextItem) nextItem.setSelected();
            tree.onRemoveItem(this);
        }
    }

    treeItem.move = function (direction) {
        if (this.parent) {
            var index = this.getIndex();
            this.parent.childsContainer.removeChild(this);
            var count = this.parent.childsContainer.childNodes.length;
            var newIndex = direction == "Up" ? index - 1 : index + 1;
            if (direction == "Up" && newIndex == -1) newIndex = 0;
            if (direction == "Down" && newIndex >= count) {
                this.parent.childsContainer.appendChild(this);
                return;
            }
            this.parent.childsContainer.insertBefore(this, this.parent.childsContainer.childNodes[newIndex]);
        }
    }

    treeItem.getIndex = function () {
        if (this.parent) {
            var index = 0;
            for (i = 0; i < this.parent.childsContainer.childNodes.length; i++) {
                if (this == this.parent.childsContainer.childNodes[i]) {
                    return i;
                }
            }
        }
        return -1;
    }

    treeItem.getCountElementsInCurrent = function () {
        return this.parent ? this.parent.childsContainer.childNodes.length : 0;
    }

    treeItem.removeAllChilds = function () {
        for (var itemKey in this.childs) {
            this.childs[itemKey].remove();
        }
    }

    treeItem.setSelected = function () {
        if (tree.selectedItem) {
            if (styleColors) {
                tree.selectedItem.button.style.background = styleColors.backColor;
                tree.selectedItem.button.style.color = styleColors.foreColor;
            }
            else {
                tree.selectedItem.button.className = "stiJsViewerTreeItem";
            }
            tree.selectedItem.isSelected = false;
        }

        if (styleColors) {
            button.style.background = this.isOver ? styleColors.hotSelectedBackColor : styleColors.selectBackgroundColor;
            button.style.color = this.isOver ? styleColors.hotSelectedForeColor : styleColors.selectedForeColor;
        }
        else {
            button.className = this.isOver ? "stiJsViewerTreeItemOver" : "stiJsViewerTreeItemSelected";
        }
        
        this.isSelected = true;
        tree.selectedItem = this;
        tree.onSelectedItem(this);
    }    

    treeItem.openTree = function () {
        var item = this.parent;
        while (item != null) {
            item.isOpening = true;
            item.childsRow.style.display = "";
            item.iconOpening.src = jsObject.collections.images["Dashboards.IconCloseItem" + (styleColors && styleColors.isDarkStyle ? "White.png" : ".png")];
            item = item.parent;
        }
    }

    treeItem.setOpening = function (state) {
        this.isOpening = state;
        this.childsRow.style.display = state ? "" : "none";
        var imageType = state ? "Close" : "Open";
        this.iconOpening.src = jsObject.collection.images["Icon" + imageType + "Item.png"];
    }
        
    return treeItem;
}

StiJsViewer.prototype.Tree = function (width, height) {
    var tree = document.createElement("div");
    tree.jsObject = this;
    tree.items = {};
    tree.selectedItem = null;
    if (width) tree.style.width = width + "px";
    if (height) tree.style.height = height + "px";

    //Events
    tree.onSelectedItem = function (item) { };
    tree.onRemoveItem = function (item) { };
    tree.onAddItem = function (item) { };
    tree.onChecked = function (item) { };
    tree.onActionItem = function (item) { };
    tree.action = function () { };

    tree.clear = function () {
        while (this.childNodes[0]) this.removeChild(this.childNodes[0]);
        this.items = {};
        this.selectedItem = null;
    }

    tree.autoscroll = function () {        
        if (this.selectedItem && this.offsetHeight > 0) {            
            var scrollContainer = this.style.overflow == "auto" ? this : this.parentNode;
            
            if (scrollContainer) {
                scrollContainer.scrollTop = 0;
                var yPos = this.jsObject.FindPosY(this.selectedItem, null, null, scrollContainer);
                if (yPos + 100 > scrollContainer.offsetHeight) scrollContainer.scrollTop = yPos - scrollContainer.offsetHeight + 100;
            }
        }
    }

    return tree;
}  

StiJsViewer.prototype.CreateTreeViewElementContent = function (element) {
    this.CreateTreeViewItemsContent(element, element.contentPanel); 
}

StiJsViewer.prototype.CreateTreeViewItemsContent = function (element, parentPanel, actionFunction) {
    var jsObject = this;
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;
    var itemAllValue;
    
    while (parentPanel.childNodes[0]) {
        parentPanel.removeChild(parentPanel.childNodes[0]);
    }

    var tree = jsObject.TreeViewElementTree(elementAttrs);
    element.itemsPanel = tree;

    tree.onChecked = function (item) {
        if (item.id == "allValue") {
            element.setStatesForAllItems(item.isChecked);
        }
        else if (itemAllValue) {
            var itemsStates = element.getAllItemsCheckedState();
            itemAllValue.setChecked(itemsStates.unCheckedItems.length == 0);
        }
        tree.updateCheckBoxesStates();

        if (actionFunction) actionFunction();

        clearTimeout(element.actionTimer);
        element.actionTimer = setTimeout(function () { jsObject.ApplyFiltersToDashboardElement(element, element.getFilters()); }, 500);
    }

    tree.onActionItem = function (item) {
        if (item && item.itemObject) {
            var filters = item.id != "allValue" ? [{ condition: "EqualTo", value: item.itemObject.key, path: item.itemObject.columnPath }] : [];
            jsObject.ApplyFiltersToDashboardElement(element, filters);
        }
        if (actionFunction) actionFunction();
    }

    //Helper methods
    element.setStatesForAllItems = function (state) {
        if (contentAttrs.selectionMode == "One") {
            if (!state) tree.mainItem.setSelected();
        }
        else {
            for (var itemKey in tree.items) {
                if (tree.items[itemKey].setChecked) {
                    tree.items[itemKey].setChecked(state);
                }
            }
        }
    }

    element.applyFiltersToItems = function () {
        var state = contentAttrs.selectionMode == "Multi";

        for (var itemKey in tree.items) {
            var item = tree.items[itemKey];
            var itemObject = item.itemObject;
            if (item.id == "mainItem" || item.id == "allValue" || !itemObject) continue;

            //Mode Multi
            if (contentAttrs.selectionMode == "Multi") {
                state = contentAttrs.filters[0].condition == "NotEqualTo" || contentAttrs.filters[0].condition == "IsFalse";

                if (state && contentAttrs.filters.some(function (f) { return ((f.condition == "NotEqualTo" && f.value == itemObject.key && f.path == itemObject.columnPath) || f.condition == "IsFalse") })) {
                    item.setChecked(false);
                }
                else if (!state && contentAttrs.filters.some(function (f) { return (f.condition == "EqualTo" && f.value == itemObject.key && f.path == itemObject.columnPath) })) {
                    item.setChecked(true);
                }
                else {
                    item.setChecked(state);
                }

                if (itemAllValue && !item.isChecked) {
                    itemAllValue.setChecked(false);
                }
            }
            //Mode One
            else if (contentAttrs.filters.some(function (f) { return (f.condition == "EqualTo" && f.value == itemObject.key && f.path == itemObject.columnPath) })) {
                item.setSelected();
                item.openTree();
                tree.autoscroll();
                return;
            }
        }
    }

    element.getFilters = function () {
        var filters = [];
        var states = element.getAllItemsCheckedState();

        if (states.checkedItems.length == 0) {
            filters.push({ condition: "IsFalse", path: contentAttrs.columnPath });
        }
        else if (states.unCheckedItems.length > states.checkedItems.length) {
            for (var i = 0; i < states.checkedItems.length; i++) {
                filters.push({ condition: "EqualTo", value: states.checkedItems[i].itemObject.key, path: states.checkedItems[i].itemObject.columnPath });
            }
        }
        else {
            for (var i = 0; i < states.unCheckedItems.length; i++) {
                filters.push({ condition: "NotEqualTo", value: states.unCheckedItems[i].itemObject.key, path: states.unCheckedItems[i].itemObject.columnPath });
            }
        }

        return filters;
    }

    element.getAllItemsCheckedState = function () {
        var states = {
            checkedItems: [],
            unCheckedItems: []
        };

        for (var itemKey in tree.items) {
            var item = tree.items[itemKey];
            if (item.id == "mainItem" || item.id == "allValue" || !item.setChecked)
                continue;

            states[item.isChecked ? "checkedItems" : "unCheckedItems"].push(item);
        }

        return states;
    }

    if (contentAttrs.items) {
        if (contentAttrs.selectionMode == "Multi") {
            //Mode Multi
            if (contentAttrs.showAllValue) {
                itemAllValue = jsObject.TreeViewElementTreeItem(this.collections.loc.DashboardAllValue, {}, tree, true, "allValue", elementAttrs);
                parentPanel.appendChild(itemAllValue);
                parentPanel.appendChild(jsObject.TreeViewElementSeparator(elementAttrs));
                tree.style.top = (itemAllValue.offsetHeight + 5) + "px";
            }
            tree.addTreeItems(contentAttrs.items, tree.mainItem, true);
        }
        else {
            //Mode One
            if (contentAttrs.showAllValue) {
                itemAllValue = jsObject.TreeViewElementTreeItem(this.collections.loc.DashboardAllValue, {}, tree, null, "allValue", elementAttrs);
                tree.mainItem.addChild(itemAllValue);
                tree.mainItem.childsContainer.appendChild(jsObject.TreeViewElementSeparator(elementAttrs));
            }
            tree.addTreeItems(contentAttrs.items, tree.mainItem);
        }

        element.setStatesForAllItems(contentAttrs.selectionMode == "Multi");

        if (contentAttrs.filters.length > 0) {
            element.applyFiltersToItems();
            tree.updateCheckBoxesStates();
        }
        else if (itemAllValue && contentAttrs.selectionMode == "One") {
            itemAllValue.setSelected();
        }
    }

    parentPanel.appendChild(tree);
}

StiJsViewer.prototype.TreeViewElementTreeItem = function (caption, itemObject, tree, showCheckBox, id, elementAttrs) {
    var treeItem = this.TreeItem(caption, null, itemObject, tree, showCheckBox, id, elementAttrs.contentAttributes.settings);
    treeItem.style.width = "100%";
    treeItem.style.marginRight = "5px";
    treeItem.button.style.width = "100%";
    treeItem.childsContainer.style.width = "100%";   

    if (elementAttrs) {
        this.ApplyAttributesToObject(treeItem.button, elementAttrs);

        if (elementAttrs.foreColor && treeItem.checkBox) {
            treeItem.checkBox.imageBlock.style.borderColor = elementAttrs.foreColor;
            treeItem.checkBox.imageBlock.style.background = "transparent";
        }
    }

    return treeItem;
}

StiJsViewer.prototype.TreeViewElementTree = function (elementAttrs) {
    var tree = this.Tree();
    var jsObject = tree.jsObject = this;
    tree.style.position = "absolute";
    tree.style.left = tree.style.top = tree.style.right = tree.style.bottom = "0px";
    tree.style.overflow = "auto";

    var mainItem = jsObject.TreeViewElementTreeItem(" ", { typeItem: "mainItem" }, tree, null, "mainItem", elementAttrs);
    mainItem.childsRow.style.display = "";
    mainItem.button.style.display = "none";
    mainItem.iconOpening.style.display = "none";
    mainItem.style.width = "auto";
    tree.appendChild(mainItem);
    tree.mainItem = mainItem;

    tree.addTreeItems = function (collection, parentItem, showCheckBoxes) {
        if (collection) {
            for (var i = 0; i < collection.length; i++) {
                var childItem = jsObject.TreeViewElementTreeItem(collection[i].text, collection[i], tree, showCheckBoxes, null, elementAttrs);
                parentItem.addChild(childItem);

                if (collection[i].items) {
                    this.addTreeItems(collection[i].items, childItem, showCheckBoxes);
                }
            }
        }
    }

    tree.getItemsLastLevel = function () {
        var items = [];

        for (var itemKey in tree.items) {
            var item = tree.items[itemKey];
            if (item.id == "mainItem" || item.id == "allValue" || !item.setChecked || jsObject.getCountObjects(item.childs) > 0)
                continue;

            items.push(item);
        }

        return items;
    }

    tree.updateCheckBoxesStates = function (startParents) {        
        if (!startParents) {
            startParents = [];

            for (var itemKey in tree.items) {
                var item = tree.items[itemKey];
                if (item.id == "mainItem" || item.id == "allValue" || !item.setChecked || jsObject.getCountObjects(item.childs) > 0)
                    continue;

                if (item.parent && startParents.indexOf(item.parent) < 0) startParents.push(item.parent);
            }
        }

        var nextLevelParents = [];
        var allValueIsIndeterminate = false;
        var allParentsUnChecked = true;

        for (var i = 0; i < startParents.length; i++) {
            var parentItem = startParents[i];
            if (!parentItem.setChecked) continue;

            if (parentItem.parent && parentItem.parent.id != "allValue" &&
                parentItem.parent.id != "mainItem" && nextLevelParents.indexOf(parentItem.parent) < 0)
            {
                nextLevelParents.push(parentItem.parent);
            }

            var checkedCount = 0;
            var unCheckedCount = 0;
            var indeterminateCount = 0;

            for (var itemKey in parentItem.childs) {
                var child = parentItem.childs[itemKey]
                if (child.isIndeterminate) indeterminateCount++;
                else if (child.isChecked) checkedCount++;
                else unCheckedCount++;
            }

            if (indeterminateCount > 0 || (checkedCount > 0 && unCheckedCount > 0)) {
                parentItem.setIndeterminate(true);
                allValueIsIndeterminate = true;
                allParentsUnChecked = false;
            }
            else {
                parentItem.setChecked(unCheckedCount == 0);
                if (unCheckedCount > 0) allValueIsIndeterminate = true;
                if (checkedCount > 0) allParentsUnChecked = false;
            }
        }
                
        if (nextLevelParents.length > 0) {
            tree.updateCheckBoxesStates(nextLevelParents);
        }
        else if (tree.items["allValue"] && allValueIsIndeterminate && !allParentsUnChecked) {
            tree.items["allValue"].setIndeterminate(true);
        }
    }

    return tree;
}

StiJsViewer.prototype.TreeViewElementSeparator = function (elementAttrs) {
    var sep = this.ListBoxElementSeparator(elementAttrs);
    sep.style.margin = "2px";

    return sep;
}

StiJsViewer.prototype.CreateTreeViewBoxElementContent = function (element) {
    var jsObject = this;
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;

    var mainButton = this.SmallButton(null, " ", null, null, "Down", null, contentAttrs.settings);
    jsObject.ApplyAttributesToObject(mainButton.innerTable, elementAttrs);
    mainButton.innerTable.style.minHeight = "auto";
    mainButton.style.height = mainButton.innerTable.style.height = "100%";
    mainButton.style.border = "0";
    mainButton.style.overflow = "hidden";
    mainButton.caption.style.width = "100%";
    mainButton.caption.style.padding = "0 4px 0 4px";

    element.contentPanel.appendChild(mainButton);
    element.contentPanel.style.overflow = "hidden";

    var menuName = elementAttrs.name + "TreeViewBoxMenu";
    var menu = this.controls.menus && this.controls.menus[menuName] ? this.controls.menus[menuName] : this.VerticalMenu(menuName, mainButton, "Down");
    menu.parentButton = mainButton;

    mainButton.action = function () {
        menu.changeVisibleState(!menu.visible);
    }
    
    var parentPanel = menu.innerContent;
    parentPanel.style.width = mainButton.offsetWidth + "px";
    parentPanel.style.backgroundColor = elementAttrs.backColor;
    parentPanel.style.height = "300px";
    parentPanel.style.padding = "4px";

    var actionFunction = function () {
        if (contentAttrs.selectionMode == "One") {
            menu.changeVisibleState(false);
        }
        mainButton.update();
    }

    jsObject.CreateTreeViewItemsContent(element, parentPanel, actionFunction);

    var tree = element.itemsPanel;
    tree.style.left = tree.style.right = tree.style.bottom = "4px";
    tree.style.top = (contentAttrs.showAllValue && contentAttrs.selectionMode == "Multi" ? elementAttrs.contentAttributes.settings.itemHeight + 9 : 4) + "px";

    mainButton.update = function () {
        if (contentAttrs.selectionMode == "One") {
            for (var itemKey in tree.items) {
                var item = tree.items[itemKey];
                if (item.isSelected) {
                    mainButton.caption.innerHTML = item.button.captionCell.innerHTML;
                }
            }
        }
        else {
            var onRemoveButton = function (button) {
                if (button.item.value == "StiUnCheckAll") {
                    element.setStatesForAllItems(false);
                    jsObject.ApplyFiltersToDashboardElement(element, element.getFilters());
                }
                else {
                    button.item.setChecked(false);
                    tree.onChecked(button.item);
                }
            }
            
            var checkItems = [];
            var unCheckItems = [];

            var items = tree.getItemsLastLevel();

            for (var i = 0; i < items.length; i++) {
                if (items[i].isChecked)
                    checkItems.push(items[i]);
                else
                    unCheckItems.push(items[i]);
            }
                        
            mainButton.caption.innerHTML = "";
            var captionWidth = mainButton.caption.offsetWidth;

            if (unCheckItems.length == 0) {
                mainButton.caption.innerHTML = "";
                mainButton.caption.appendChild(jsObject.ComboBoxCaptionButton(jsObject.collections.loc.All, { value: "StiUnCheckAll" }, onRemoveButton, contentAttrs.settings, elementAttrs));
            }
            else if (checkItems.length > 0) {
                var сaptionNotFit = false;

                for (var i = 0; i < checkItems.length; i++) {
                    mainButton.caption.appendChild(jsObject.ComboBoxCaptionButton(checkItems[i].button.captionCell.innerHTML, checkItems[i], onRemoveButton, contentAttrs.settings, elementAttrs));

                    if (mainButton.caption.offsetWidth > captionWidth) {
                        mainButton.caption.innerHTML = "";
                        сaptionNotFit = true;
                        break;
                    }
                }
                if (сaptionNotFit ) {
                    mainButton.caption.appendChild(jsObject.ComboBoxCaptionButton(jsObject.collections.loc.DashboardNSelected.replace("{0}", checkItems.length),
                        { value: "StiUnCheckAll" }, onRemoveButton, contentAttrs.settings, elementAttrs));
                }
            }
        }

        mainButton.setEnabled(jsObject.getCountObjects(tree.mainItem.childs));
    }
                
    mainButton.update();
}

StiJsViewer.prototype.AddInteractionsToHtmlContentDashboardElement = function (element, mainContainer) {
    var jsObject = this;
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;
    if (!contentAttrs) return;

    //Add interactive events
    var allGeoms = [];
    var findFilteringGeom = false;
    var geomOpacity = element.elementAttributes.type == "StiRegionMapElement" ? "0.3" : "0.4";

    element.resetAllSelectedGeoms = function () {
        for (var i = 0; i < allGeoms.length; i++) {
            allGeoms[i].isSelected = false;
            allGeoms[i].style.fillOpacity = allGeoms[i].getAttribute("defaultFillOpacity") || "1";
        }
    }

    element.removeStandartTooltip = function (geom) {
        for (var i = 0; i < geom.childNodes.length; i++) {
            if (geom.childNodes[i].tagName && geom.childNodes[i].tagName.toString().toLowerCase() == "title") {
                geom.removeChild(geom.childNodes[i]);
                break;
            }
        }
    }

    element.getFilters = function () {
        var filters = [];
        for (var i = 0; i < allGeoms.length; i++) {
            if (allGeoms[i].isSelected) {
                if (elementAttrs.type == "StiChartElement" && contentAttrs.isBubble) {
                    filters.push({ condition: "EqualTo", value: allGeoms[i].getAttribute("elementargument"), path: contentAttrs.bubleXColumnPath });
                    filters.push({ condition: "EqualTo", value: allGeoms[i].getAttribute("elementvalue"), path: contentAttrs.bubleYColumnPath });
                }
                else {
                    var value = allGeoms[i].getAttribute("elementargument") || allGeoms[i].getAttribute("elementvalue");
                    filters.push({ condition: "EqualTo", value: value, path: contentAttrs.columnPath });
                }
            }
        }
        return filters;
    }

    element.selectGeom = function (geom, multiFilter) {
        if (multiFilter) {
            geom.isSelected = !geom.isSelected;

            for (var i = 0; i < allGeoms.length; i++) {
                allGeoms[i].style.fillOpacity = allGeoms[i].isSelected ? "1" : (allGeoms[i].getAttribute("defaultFillOpacity") != "0" ? geomOpacity : "0");
            }

        }
        else {
            for (var i = 0; i < allGeoms.length; i++) {
                allGeoms[i].isSelected = allGeoms[i] == geom;
                allGeoms[i].style.fillOpacity = allGeoms[i].isSelected ? "1" : (allGeoms[i].getAttribute("defaultFillOpacity") != "0" ? geomOpacity : "0");
            }
        }
    }

    element.updateSelectedGeoms = function () {
        for (var i = 0; i < allGeoms.length; i++) {
            allGeoms[i].setSelected(this.elementAttributes.contentAttributes.filters.some(function (f) { return (f.condition == "EqualTo" && f.value == allGeoms[i].getAttribute("elementargument")) }));
        }
    }

    element.findGeoms = function (parent) {
        if (parent.childNodes.length > 0) {
            for (var i = 0; i < parent.childNodes.length; i++) {
                var child = parent.childNodes[i];

                //is geom
                if (child["getAttribute"] && (
                    child.getAttribute("elementargument") != null ||
                    child.getAttribute("elementvalue") != null ||
                    child.getAttribute("elementseries") != null ||
                    child.getAttribute("elementident") != null)) {
                    var geom = child;

                    if (geom.style && geom.style.fillOpacity) {
                        geom.setAttribute("defaultFillOpacity", geom.style.fillOpacity);
                    }

                    geom.replaceAllKeys = function (text) {
                        var keys = {
                            value: this.getAttribute("elementvalue"),
                            argument: this.getAttribute("elementargument"),
                            series: this.getAttribute("elementseries"),
                            ident: this.getAttribute("elementident")
                        }
                        return jsObject.ReplaceAllKeysInText(text, keys);
                    }

                    geom.getHyperlinkText = function () {
                        return (contentAttrs.interaction && contentAttrs.interaction.hyperlink ? this.replaceAllKeys(contentAttrs.interaction.hyperlink) : "");
                    }

                    geom.getTooltipText = function () {
                        return (contentAttrs.interaction ? jsObject.CorrectTooltipText(this.replaceAllKeys(contentAttrs.interaction.toolTip)) : "");
                    }

                    if (!contentAttrs.interaction || (contentAttrs.interaction && contentAttrs.interaction.onClick != "None")) {
                        geom.style.cursor = "pointer";

                        if (contentAttrs.interaction && contentAttrs.interaction.onClick == "DrillDown" && contentAttrs.interaction.drillDownCurrentLevel >= contentAttrs.interaction.drillDownLevelCount - 1)
                            geom.style.cursor = "default";
                    }

                    if (contentAttrs.interaction && contentAttrs.interaction.onHover == "None") {
                        geom.setAttribute("notShowTooltip", "true");
                    }

                    //Add hover events
                    if (contentAttrs.interaction && element.frame &&
                        ((contentAttrs.interaction.onHover == "ShowHyperlink" && contentAttrs.interaction.hyperlink) ||
                            (contentAttrs.interaction.onHover == "ShowToolTip" && contentAttrs.interaction.toolTip))) {

                        var toolTipText = contentAttrs.interaction.onHover == "ShowHyperlink" ? geom.getHyperlinkText() : geom.getTooltipText();

                        if (contentAttrs.interaction.onHover == "ShowHyperlink") {
                            toolTipText = "<font style=\"color: #0645ad; text-decoration: underline;\">" + toolTipText + "</font>";
                        }

                        geom.setAttribute("_text1", "");
                        geom.setAttribute("_text2", "");

                        if (toolTipText) {
                            geom.removeAttribute("notShowTooltip");
                            geom.setAttribute("_text1", toolTipText);
                            geom.setAttribute("isCustomTooltip", "true");
                            element.removeStandartTooltip(geom);
                        }

                        if (contentAttrs.interaction.ident == "Chart") {
                            //add chart tooltip
                            var frameDoc = element.frame.contentWindow.document;
                            if (frameDoc) {
                                if (geom.getAttribute("_color")) {
                                    var fillColor = geom.style.fill;
                                    if (fillColor != null && fillColor.toLowerCase().indexOf("rgb") >= 0) {
                                        var colors = fillColor.replace("rgb(", "").replace(")", "").split(",");
                                        if (colors.length >= 3)
                                            fillColor = jsObject.FullColorHex(parseInt(colors[0]), parseInt(colors[1]), parseInt(colors[2]));
                                    }
                                    if (fillColor) geom.setAttribute("_color", fillColor);
                                }
                                if (!frameDoc._stiTooltip) {
                                    jsObject.CreateCustomTooltip(frameDoc);
                                }
                                jsObject.AddCustomTooltip(geom, frameDoc, true);
                            }
                        }
                    }

                    //Add click events
                    geom.onclick = function () {
                        if (contentAttrs.interaction && contentAttrs.interaction.onClick == "OpenHyperlink" && contentAttrs.interaction.hyperlink && !element.isDrillSelectionActivated) {
                            jsObject.openNewWindow(this.getHyperlinkText());
                        }
                        else if (contentAttrs.interaction && contentAttrs.interaction.onClick == "ShowDashboard" && contentAttrs.interaction.drillDownPageKey && !element.isDrillSelectionActivated) {
                            var drillDownParameters = {
                                drillDownPageKey: contentAttrs.interaction.drillDownPageKey,
                                value: (elementAttrs.type == "StiRegionMapElement" ? this.getAttribute("elementident") : this.getAttribute("elementargument")) || "",
                                parameters: []
                            }
                            var parameters = contentAttrs.interaction.drillDownParameters;
                            if (parameters) {
                                for (var i = 0; i < parameters.length; i++) {
                                    drillDownParameters.parameters.push({
                                        key: parameters[i].name,
                                        value: this.replaceAllKeys(parameters[i].expression)
                                    });
                                }
                            }
                            jsObject.postInteraction({
                                action: "DashboardDrillDown",
                                drillDownParameters: drillDownParameters,
                                pageNumber: 0
                            });
                        }
                        else if (contentAttrs.interaction && contentAttrs.interaction.allowUserDrillDown && (contentAttrs.interaction.onClick == "DrillDown" || element.isDrillSelectionActivated)) {
                            if (contentAttrs.interaction.drillDownCurrentLevel < contentAttrs.interaction.drillDownLevelCount - 1) {

                                element.selectGeom(this, element.isDrillSelectionActivated);

                                var filters = element.getFilters();

                                if (element.isDrillSelectionActivated && filters.length == 0) {
                                    element.resetAllSelectedGeoms();
                                }

                                if (!element.isDrillSelectionActivated) {
                                    clearTimeout(element.actionTimer);
                                    element.actionTimer = setTimeout(function () {
                                        jsObject.ApplyDrillDownToDashboardElement(element, filters);
                                    }, 500);
                                }
                            }
                        }
                        else if (!contentAttrs.interaction || (contentAttrs.interaction && contentAttrs.interaction.onClick == "ApplyFilter")) {
                            element.selectGeom(this, element.buttons.multiFilter.isChecked);

                            var filters = element.getFilters();

                            if (element.buttons.multiFilter.isChecked && filters.length == 0) {
                                element.resetAllSelectedGeoms();
                            }

                            clearTimeout(element.actionTimer);
                            element.actionTimer = setTimeout(function () {
                                jsObject.ApplyFiltersToDashboardElement(element, filters);
                            }, 500);
                        }
                    }

                    geom.setSelected = function (state) {
                        this.isSelected = state;
                        this.style.fillOpacity = state ? "1" : (this.getAttribute("defaultFillOpacity") != "0" ? geomOpacity : "0");
                    }

                    if (contentAttrs.filters.some(function (f) { return (f.condition == "EqualTo" && f.value == geom.getAttribute("elementargument")) })) {
                        findFilteringGeom = true;
                        geom.setSelected(true);
                    }
                    else {
                        geom.setSelected(false);
                    }

                    allGeoms.push(geom);
                }

                element.findGeoms(child);
            }
        }
    }

    if (mainContainer) {
        element.findGeoms(mainContainer);
        if (!findFilteringGeom) element.resetAllSelectedGeoms();
    }
}

StiJsViewer.prototype.AddInteractionsToDashboardElement = function (element) {
    var jsObject = this;
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;
    if (!contentAttrs) return;
    var interaction = contentAttrs.interaction;

    if (interaction) {
        if ((interaction.onHover == "ShowToolTip" && interaction.toolTip) || (interaction.onHover == "ShowHyperlink" && interaction.hyperlink)) {
            var toolTipText = interaction.onHover == "ShowToolTip" ? interaction.toolTip : interaction.hyperlink;
            toolTipText = jsObject.CorrectTooltipText(jsObject.ReplaceAllKeysInText(toolTipText, {}));

            if (interaction.onHover == "ShowHyperlink") {
                toolTipText = "<font style=\"color: #0645ad; text-decoration: underline;\">" + toolTipText + "</font>";
            }

            element.setAttribute("_text1", toolTipText);

            if (!document._stiTooltip)
                jsObject.CreateCustomTooltip(document, jsObject.controls.mainPanel);

            jsObject.AddCustomTooltip(element, document);
        }

        if (interaction.onClick == "OpenHyperlink" && interaction.hyperlink) {
            element.style.cursor = "pointer";
            element.onclick = function () {
                jsObject.openNewWindow(interaction.hyperlink);
            }
        }       
        else if (interaction.onClick == "ShowDashboard" && interaction.drillDownPageKey) {
            element.style.cursor = "pointer";
            element.onclick = function () {
                if (document._stiTooltip) {
                    document._stiTooltip.cx = -0.2;
                }
                var drillDownParameters = {
                    drillDownPageKey: interaction.drillDownPageKey,
                    value: "",
                    parameters: []
                }
                var parameters = interaction.drillDownParameters;
                if (parameters) {
                    for (var i = 0; i < parameters.length; i++) {
                        drillDownParameters.parameters.push({
                            key: parameters[i].name,
                            value: (parameters[i].expression ? jsObject.ReplaceAllKeysInText(parameters[i].expression, {}) : "")
                        });
                    }
                }
                jsObject.postInteraction({
                    action: "DashboardDrillDown",
                    drillDownParameters: drillDownParameters,
                    pageNumber: 0
                });
            }
        }
    }
}

StiJsViewer.prototype.ReplaceAllKeysInText = function (text, keys) {
    var value = keys.value || "";
    var argument = keys.argument || "";
    var series = keys.series || "";
    var ident = keys.ident || "";

    if (text != null) {
        text = text.replace(/{value}/g, value).replace(/{Value}/g, value);
        text = text.replace(/{argument}/g, argument).replace(/{Argument}/g, argument);
        text = text.replace(/{series}/g, series).replace(/{Series}/g, series);
        text = text.replace(/{ident}/g, ident).replace(/{Ident}/g, ident);

        if (this.reportParams.variablesValues) {
            var currVarsValues = this.controls.parametersPanel ? this.controls.parametersPanel.getParametersValues() : {};
            for (var varName in this.reportParams.variablesValues) {
                var varValue = currVarsValues[varName] != null ? currVarsValues[varName] : this.reportParams.variablesValues[varName];
                text = text.replace(new RegExp("{" + varName + "}", 'g'), (varValue || ""));
            }
        }

        return text;
    }
    
    return "";
}

StiJsViewer.prototype.CorrectTooltipText = function (text) {
    if (text != null) {
        //replace to supported html tags
        text = text.replace(/<font-color/g, '<font color').replace(/<\/font-color>/g, '</font>');

        var sizes = ["8", "10", "12", "14", "18", "24", "36"];
        while (text.indexOf("size=") >= 0) {
            var newString = "style=\"font-size:";
            text = text.replace("size=\"", newString);
            var startIndex = text.indexOf(newString) + newString.length;

            var firstPart = text.substring(0, startIndex);
            var tempPart = text.substring(startIndex);
            var middlePart = tempPart.substring(0, tempPart.indexOf("\""));
            var lastPart = tempPart.substring(tempPart.indexOf("\""));

            if (parseInt(middlePart) <= 7 && parseInt(middlePart) > 0) {
                text = firstPart + sizes[parseInt(middlePart) - 1] + "pt" + lastPart;
            }
            else {
                text = firstPart + middlePart + "pt" + lastPart;
            }
        }
        return text;
    }
    return "";
}

StiJsViewer.prototype.CreateCustomTooltip = function (doc, owner) {
    var table = this.CreateHTMLTable();
    table.style.position = "absolute";
    table.style.opacity = "0";
    table.style.background = "white";
    table.style.padding = "5px";
    table.style.border = "1px solid #bebebe";
    table.style.fontFamily = "Arial";
    table.style.fontSize = "12px";
    table.style.color = "#111111";
    table.style.zIndex = "20000";
    table.style.pointerEvents = "none";
    table._text1 = table.addCell();
    table._text1.style.paddingTop = "3px";
    table._text2 = table.addCellInNextRow();
    table._text2.style.paddingTop = "3px";

    doc._stiTooltip = table;

    if (owner)
        owner.appendChild(table);
    else
        doc.body.appendChild(table);

    setInterval(function () {
        var t = doc._stiTooltip;
        var op = parseFloat(t.style.opacity);
        if ((t.cx > 0 && op < 1) || (t.cx < 0 && op > 0)) {
            op += t.cx;
            op = Math.min(1, Math.max(0, op));
            t.style.opacity = op;
        }
    }, 50);
}

StiJsViewer.prototype.AddCustomTooltip = function (el, doc, inFrame) {
    var jsObject = this;
    var t = doc._stiTooltip;

    el.onmouseover = function (event) {
        if (event.target.getAttribute("notShowTooltip") == "true")
            return;

        var text = event.target.getAttribute("_text1") || this.getAttribute("_text1");

        if (text == null) {
            //find on the top levels
            var level = 0;
            var currEl = event.target;
            while (currEl.parentElement != null && level < 3) {
                if (currEl.parentElement.getAttribute("_text1")) {
                    text = currEl.parentElement.getAttribute("_text1");
                    break;
                }
                else {
                    currEl = currEl.parentElement;
                }
                level++;
            }
        }

        if (!text) return;

        t.cx = 0.1;
        t._text1.innerHTML = text;

        var _color = event.target.getAttribute("_color");
        if (_color) event.target.style.fill = jsObject.LightenDarkenColor(_color, -35);

        if (inFrame) {
            var cx = Math.max(event.pageX + 1 + t.offsetWidth - window.outerWidth + 10, 0);
            var cy = Math.max(event.pageY + 1 + t.offsetHeight - window.outerHeight + 10, 0);
            cx = Math.max(cx, event.pageX + 1 + t.offsetWidth - doc.body.offsetWidth);
            cy = Math.max(cy, event.pageY + 1 + t.offsetHeight - doc.body.offsetHeight);
            t.style.left = (event.pageX + 1 - cx) + "px";
            t.style.top = (event.pageY + 1 - cy) + "px";
        }
        else {
            var point = jsObject.FindMousePosOnMainPanel(event);
            t.style.left = (point.xPixels + 5) + "px";
            t.style.top = (point.yPixels + 5) + "px";
        }
    }

    el.onmouseout = function (event) {
        t.cx = -0.2;
        var _color = event.target.getAttribute("_color");
        if (_color) event.target.style.fill = _color;
    }
}

StiJsViewer.prototype.PivotTable = function (width, height, settings) {
    var pivot = document.createElement("div");
    pivot.jsObject = this;
    pivot.style.userSelect = "none";
    pivot.width = width;
    pivot.height = height;
    pivot.settings = settings;    

    if (width) pivot.style.width = width + "px";
    if (height) pivot.style.height = height + "px";

    var jsObject = this;

    //create styles
    pivot.guid = Math.floor(Math.random() * 10000000);

    if (!jsObject.controls.css) {
        var css = document.getElementById(jsObject.options.viewerId + "Styles");
        if (!css) {
            css = document.createElement("STYLE");
            css.id = jsObject.options.viewerId + "Styles";
            css.setAttribute('type', 'text/css');
            jsObject.controls.head.appendChild(css);
            jsObject.controls.css = css;
        }
    }

    var sheet = jsObject.controls.css.styleSheet || jsObject.controls.css.sheet || document.styleSheets[0];

    sheet.insertRule(".pivotUnselectable {-webkit-user-select:none; -moz-user-select:none; -ms-user-select:none; user-select:none;}", 0);
    sheet.insertRule(".pivotTable" + pivot.guid + " {text-align:center; font-family:" + settings.fontName + "; font-size:" + settings.fontSize + "pt; line-height:" + (settings.cellHeight - 10) + "px; white-space: nowrap;" +
        "-webkit-user-select:none; -moz-user-select:none; -ms-user-select:none; user-select:none;}", 0);
    sheet.insertRule(".pivotColumnHeader" + pivot.guid + " {color:" + settings.columnHeaderForeColor + "; background-color:" + settings.columnHeaderBackColor + " }", 0);
    sheet.insertRule(".pivotColumnHeader" + pivot.guid + ":hover {background-color:" + settings.hotColumnHeaderBackColor + "}", 0);
    sheet.insertRule(".pivotRowHeader" + pivot.guid + " {color:" + settings.rowHeaderForeColor + "; background-color:" + settings.rowHeaderBackColor + " }", 0);
    sheet.insertRule(".pivotRowHeader" + pivot.guid + ":hover {background-color:" + settings.hotRowHeaderBackColor + "}", 0);
    sheet.insertRule(".pivotCell" + pivot.guid + "{text-align: right}", 0);
    sheet.insertRule(".pivotCellTable" + pivot.guid + "{}", 0);
    sheet.insertRule(".pivotCellTable" + pivot.guid + " tr{}", 0);
    sheet.insertRule(".pivotCellTable" + pivot.guid + " tr:nth-child(even){color:" + settings.alternatingCellForeColor + "; background-color:" + settings.alternatingCellBackColor + " }", 0);
    sheet.insertRule(".pivotCellTable" + pivot.guid + " tr:nth-child(odd){color:" + settings.cellForeColor + "; background-color:" + settings.cellBackColor + " }", 0);
    sheet.insertRule(".pivotSelectedCell" + pivot.guid + " {color:" + settings.selectedCellForeColor + "; background-color:" + settings.selectedCellBackColor + "; text-align: right}", 0);

    jsObject.AddProgressToControl(pivot);

    pivot.clear = function () {
        while (this.childNodes[0]) this.removeChild(this.childNodes[0]);
    }

    pivot.showData = function (data) {
        pivot.progress.show();
        setTimeout(function () {
            pivot.showDataInt(data)
        }, 0);
    }

    pivot.showDataInt = function (data) {
        pivot.data = data;
        if (!data || data.length == 0) return;

        var table = jsObject.CreateHTMLTable();
        this.appendChild(table);
        var td = table.addCell();
        td.style.verticalAlign = "top";
        var leftDiv = document.createElement("div");
        td.appendChild(leftDiv);
        this.cornerDiv = document.createElement("div");
        leftDiv.appendChild(this.cornerDiv);
        this.cornerTable = jsObject.CreateHTMLTable();
        this.cornerTable.className = "pivotTable" + pivot.guid;
        this.cornerDiv.appendChild(this.cornerTable);
        //populate left up corner
        for (var y = 0; y < data.headerHeight; y++) {
            if (y != 0) this.cornerTable.addRow();
            for (var x = 0; x < data.headerWidth; x++) {
                var cell = data.cells[x][y];
                if (cell.guid == cell.parentCellGuid)
                    this.td(cell, this.cornerTable, this.cornerTable.tr.length - 1, cell.colSpan, cell.rowSpan, ["Bottom", "Right"], undefined, "pivotRowHeader" + pivot.guid);
            }
        }
        this.cornerTable.addRow();
        for (var x = 0; x < data.headerWidth; x++) {
            this.cornerTable.addCellInLastRow().style.height = "0px";
        }

        //populate guids
        this.cellGuid = {};
        for (var y = 0; y < data.cells[0].length; y++) {
            for (var x = 0; x < data.cells.length; x++) {
                if ((x < data.headerWidth || y < data.headerHeight) && data.cells[x][y].guid == data.cells[x][y].parentCellGuid) {
                    var cell = data.cells[x][y];
                    this.cellGuid[cell.guid] = cell;
                }
            }
        }

        //left header rows
        this.headerRowsDiv = document.createElement("div");
        leftDiv.appendChild(this.headerRowsDiv);
        leftDiv.style.overflow = "hidden";
        this.headerRowsDiv.style.position = "relative";
        this.headerRowsDiv.style.overflow = "hidden";
        this.headerRowsDiv.style.zoom = "1";
        this.headerRowsTable = jsObject.CreateHTMLTable();
        this.headerRowsTable.className = "pivotTable" + pivot.guid;
        this.headerRowsTable.style.tableLayout = "fixed";
        this.addWheel(this.headerRowsTable);
        this.headerRowsDiv.appendChild(this.headerRowsTable);
        var y = data.headerHeight;
        this.hasTotalsColumn = false;
        if (data.headerWidth > 0) {
            while (y < data.cells[0].length) {
                if (y != data.headerHeight) this.headerRowsTable.addRow();
                var cell = data.cells[0][y];
                var colSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].colSpan + cell.colSpan : cell.colSpan;
                var rowSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].rowSpan : cell.rowSpan;
                this.td(cell, this.headerRowsTable, this.headerRowsTable.tr.length - 1, colSpan, rowSpan, ["Bottom", "Right"], "htd", "pivotColumnHeader" + pivot.guid);
                if (colSpan < data.headerWidth)
                    this.hasTotalsColumn = true;
                for (var yy = y; yy < y + rowSpan; yy++) {
                    if (yy != y) this.headerRowsTable.addRow();
                    for (var x = colSpan; x < data.headerWidth; x++) {
                        cell = data.cells[x][yy];
                        this.td(cell, this.headerRowsTable, this.headerRowsTable.tr.length - 1, cell.colSpan, cell.rowSpan, ["Bottom", "Right"], "htd", "pivotColumnHeader" + pivot.guid);
                    }
                }
                y += data.cells[0][y].rowSpan;
            }
            this.headerRowsTable.addRow();
            for (var x = 0; x < data.headerWidth; x++) {
                this.headerRowsTable.addCellInLastRow().style.height = "0px";
            }
        }
        

        //top header cols
        td = table.addCell();
        td.style.verticalAlign = "top";
        var rightDiv = document.createElement("div");
        td.appendChild(rightDiv);
        this.headerColsDiv = document.createElement("div");
        this.headerColsDiv.style.position = "relative";
        this.headerColsDiv.style.overflow = "hidden";
        this.headerColsDiv.style.zoom = "1";        

        rightDiv.appendChild(this.headerColsDiv);
        this.headerColsTable = jsObject.CreateHTMLTable();
        this.headerColsTable.className = "pivotTable" + pivot.guid;
        this.headerColsDiv.appendChild(this.headerColsTable);
        if (jsObject.getNavigatorName() == "Edge" || jsObject.getNavigatorName() == "MSIE") {
            this.headerColsTable.style.tableLayout = "fixed";
            this.headerRowsTable.style.tableLayout = "fixed";
            this.cornerTable.style.tableLayout = "fixed";
        }
            
        this.openedColumns = [];
        this.openedRows = [];
        var firstTotalRow = Math.min(data.headerHeight, data.pivotRowsCount == 0 ? 1 : 2) - 1;
        for (y = 0; y < firstTotalRow + 1; y++) {
            if (y != 0) this.headerColsTable.addRow();
            var x = data.headerWidth;
            while (x < data.cells.length) {
                var cell = data.cells[x][y];
                if (cell.guid == cell.parentCellGuid) {
                    var colSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].colSpan : cell.colSpan;
                    var rowSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].rowSpan + cell.rowSpan : cell.rowSpan;

                    this.td(cell, this.headerColsTable, this.headerColsTable.tr.length - 1, colSpan, rowSpan, y == firstTotalRow ? ["Bottom", "Right"] : ["Bottom"], "htd", "pivotRowHeader" + pivot.guid);

                    if (cell.totalCellGuid) this.openedColumns.push(this.cellGuid[cell.totalCellGuid].column);
                    else if (y == firstTotalRow) this.openedColumns.push(cell.column);
                }
                x += colSpan;
            }
        }

        for (y = (data.pivotRowsCount > 0 ? 2 : 1); y < data.headerHeight; y++) {
            var row = this.headerColsTable.addRow();
            row.style.height = "0px";
        }

        //cells
        this.contentDiv = document.createElement("div");
        this.contentDiv.style.position = "relative";
        this.contentDiv.style.overflow = "hidden";
        rightDiv.appendChild(this.contentDiv);
        this.cellsDiv = document.createElement("div");
        this.cellsDiv.style.position = "relative";
        this.cellsDiv.style.overflow = this.jsObject.options.isMobileDevice ? "auto" : "hidden";
        this.cellsDiv.style.zoom = "1";
        this.cellsDiv.style.width = "1000px";
        this.cellsDiv.style.height = "200px";
        
        this.contentDiv.appendChild(this.cellsDiv);
        this.cellsTable = jsObject.CreateHTMLTable();
        this.cellsDiv.appendChild(this.cellsTable);
        this.cellsTable.className = "pivotTable" + pivot.guid + " pivotCellTable" + pivot.guid;
        this.addWheel(this.cellsTable);

        y = 0;
        while (y < data.cells[0].length) {
            if (y > 0) this.cellsTable.addRow();

            if (y < data.headerHeight) {
                for (var x = 0; x < data.cells.length; x++)
                    if ((x < data.headerWidth || y < firstTotalRow + 1 || x == data.cells.length - 1) && data.cells[x][y].guid == data.cells[x][y].parentCellGuid) {
                        var cell = data.cells[x][y];
                        var colSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].colSpan : cell.colSpan;
                        var rowSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].rowSpan + cell.rowSpan : cell.rowSpan;

                        this.td(cell, this.cellsTable, this.cellsTable.tr.length - 1, colSpan, rowSpan, ["Bottom", "Right"], "td", "pivotColumnHeader" + pivot.guid);

                        if (cell.totalCellGuid)
                            this.setupArrow(cell);
                    }
                y++;
            } else {
                var cell = data.cells[0][y];
                var colSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].colSpan + cell.colSpan : cell.colSpan;
                var rowSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].rowSpan : cell.rowSpan;

                this.td(cell, this.cellsTable, this.cellsTable.tr.length - 1, colSpan, rowSpan, data.headerWidth > 0 ? ["Bottom", "Right"] : ["Right"], "td", (data.headerWidth > 0 || data.onlySummaries ? "pivotRowHeader" : "pivotCell") + pivot.guid);

                if (cell.totalCellGuid)
                    this.setupArrow(cell);
                y += (cell.rowSpan - rowSpan);
                for (var yy = y; yy < y + rowSpan; yy++) {
                    if (yy != y) this.cellsTable.addRow();
                    for (var x = colSpan; x < data.cells.length; x++)
                        if (x < data.headerWidth || this.openedColumns.indexOf(x) >= 0 || x == data.cells.length - 1) {
                            cell = data.cells[x][yy];
                            this.td(cell, this.cellsTable, this.cellsTable.tr.length - 1, cell.colSpan, cell.rowSpan, x < data.headerWidth && data.headerHeight > 0 ? ["Bottom", "Right"] : ["Right"], "td",
                                    x < data.headerWidth && data.headerHeight > 0 ? "pivotRowHeader" + pivot.guid : "pivotCell" + pivot.guid);
                            this.openedRows.push(yy);
                        }
                }
                y += rowSpan;
            }
        }
        this.cellsTable.addRow().style.height = "0px";
        for (var x = 0; x < data.cells.length; x++) {
            if (x < data.headerWidth || this.openedColumns.indexOf(x) >= 0)
                this.cellsTable.addCellInLastRow();
        }

        this.scrollHiddenColor = "rgba(191, 191, 191, 0)";
        this.scrollDivColor = "rgba(191, 191, 191, 0.1)";
        this.scrollColor = "rgba(191, 191, 191, 0.5)";
        this.scrollSelectedColor = "rgba(191, 191, 191, 0.8)";

        //horizontal scroll 
        this.cellsHScrollDiv = document.createElement("div");
        this.contentDiv.appendChild(this.cellsHScrollDiv);
        this.cellsHScrollDiv.style.bottom = "0";
        this.cellsHScrollDiv.style.left = "0";
        this.cellsHScrollDiv.style.width = "100%";
        this.cellsHScrollDiv.style.position = "absolute";
        this.cellsHScrollDiv.style.boxSizing = "border-box";
        this.cellsHScrollDiv.style.height = "8px";
        this.cellsHScrollDiv.style.touchAction = "none";
        this.cellsHScrollDiv.style.backgroundColor = this.scrollHiddenColor;
        this.cellsHScrollDiv.style.transition = "background-color 0.5s ease";
        this.cellsHScrollDiv.style.poinerEvents = "none";
        this.cellsHScrollDiv.className = "pivotUnselectable";


        this.cellHScroll = document.createElement("div");
        this.cellsHScrollDiv.appendChild(this.cellHScroll);
        this.cellHScroll.style.height = "100%";
        this.cellHScroll.style.width = "73%";
        this.cellHScroll.style.backgroundColor = this.scrollHiddenColor;
        this.cellHScroll.style.transition = "background-color 0.5s ease";
        this.cellHScroll.className = "pivotUnselectable";
        this.hScrollOffset = 0;
        this.hOffset = 1;


        //vertical scroll 
        this.cellsVScrollDiv = document.createElement("div");
        this.contentDiv.appendChild(this.cellsVScrollDiv);
        this.cellsVScrollDiv.style.top = "0";
        this.cellsVScrollDiv.style.right = "0";
        this.cellsVScrollDiv.style.height = "100%";
        this.cellsVScrollDiv.style.position = "absolute";
        this.cellsVScrollDiv.style.boxSizing = "border-box";
        this.cellsVScrollDiv.style.width = "8px";
        this.cellsVScrollDiv.style.touchAction = "none";
        this.cellsVScrollDiv.style.backgroundColor = this.scrollHiddenColor;
        this.cellsVScrollDiv.style.transition = "background-color 0.5s ease";
        this.cellsVScrollDiv.style.poinerEvents = "none";
        this.cellsVScrollDiv.className = "pivotUnselectable";

        this.cellVScroll = document.createElement("div");
        this.cellsVScrollDiv.appendChild(this.cellVScroll);
        this.cellVScroll.style.width = "100%";
        this.cellVScroll.style.height = "73%";
        this.cellVScroll.style.backgroundColor = this.scrollHiddenColor;
        this.cellVScroll.style.transition = "background-color 0.5s ease";
        this.cellVScroll.className = "pivotUnselectable";
        this.vScrollOffset = 0;
        this.vOffset = 1;

        this.cellsDiv.onscroll = function () {
            pivot.headerColsDiv.scrollLeft = pivot.cellsDiv.scrollLeft;
            pivot.headerRowsDiv.scrollTop = pivot.cellsDiv.scrollTop;
        }

        document.body.addEventListener("mousemove", function (event) {
            if (pivot.screenX) {
                var emptyWidth = (pivot.width - pivot.headerWidth) - (pivot.width - pivot.headerWidth) / pivot.hOffset;
                var offset = Math.max(0, Math.min(emptyWidth, event.screenX - pivot.screenX + pivot.startXOffset)) ;
                pivot.cellHScroll.style.transform = "translateX(" + offset + "px)";
                pivot.cellsDiv.scrollLeft = offset * pivot.hOffset;
                pivot.hScrollOffset = offset;
            }

            if (pivot.screenY) {
                var emptyHeight = (pivot.height - pivot.headerHeight) - (pivot.height - pivot.headerHeight) / pivot.vOffset;
                var offset = Math.max(0, Math.min(emptyHeight, event.screenY - pivot.screenY + pivot.startYOffset));
                pivot.cellVScroll.style.transform = "translateY(" + offset + "px)";
                pivot.cellsDiv.scrollTop = offset * pivot.vOffset;
                pivot.vScrollOffset = offset;
            }
        });

        document.body.addEventListener("mouseup", function (event) {
            pivot.screenX = null;
            pivot.screenY = null;
            if (!pivot.mouseOver) {
                pivot.cellsHScrollDiv.style.backgroundColor = pivot.scrollHiddenColor;
                pivot.cellHScroll.style.backgroundColor = pivot.scrollHiddenColor;
                pivot.cellsVScrollDiv.style.backgroundColor = pivot.scrollHiddenColor;
                pivot.cellVScroll.style.backgroundColor = pivot.scrollHiddenColor;
            } else {
                if (pivot.hOffset > 1) 
                    pivot.cellHScroll.style.backgroundColor = pivot.scrollColor;
                if (pivot.vOffset > 1) 
                    pivot.cellVScroll.style.backgroundColor = pivot.scrollColor;
            }
        });

        this.cellHScroll.onmousedown = function (event) {
            event.stopPropagation();
            if (pivot.hOffset > 1) {
                pivot.screenX = event.screenX;
                pivot.startXOffset = pivot.hScrollOffset;
                pivot.cellHScroll.style.backgroundColor = pivot.scrollSelectedColor;
            }   
        }

        this.cellVScroll.onmousedown = function (event) {
            event.stopPropagation();
            if (pivot.vOffset > 1) {
                pivot.screenY = event.screenY;
                pivot.startYOffset = pivot.vScrollOffset;
                pivot.cellVScroll.style.backgroundColor = pivot.scrollSelectedColor;
            }
        }

        this.cellsHScrollDiv.onmousedown = function (event) {
            var sWidth = (pivot.width - pivot.headerWidth) / pivot.hOffset;
            var emptyWidth = (pivot.width - pivot.headerWidth) - sWidth;
            
            if (pivot.cellHScroll.getBoundingClientRect().x > event.screenX) 
                sWidth *= -1;

            var offset = Math.max(0, Math.min(emptyWidth, sWidth + pivot.hScrollOffset));
            pivot.cellHScroll.style.transform = "translateX(" + offset + "px)";
            pivot.cellsDiv.scrollLeft = offset * pivot.hOffset;
            pivot.hScrollOffset = offset;            
        }

        this.cellsVScrollDiv.onmousedown = function (event) {
            var sHeight = (pivot.height - pivot.headerHeight) / pivot.vOffset;
            var emptyHeight = (pivot.height - pivot.headerHeight) - sHeight;

            if (pivot.cellVScroll.getBoundingClientRect().y > event.screenY)
                sHeight *= -1;

            var offset = Math.max(0, Math.min(emptyHeight, sHeight + pivot.vScrollOffset));
            pivot.cellVScroll.style.transform = "translateY(" + offset + "px)";
            pivot.cellsDiv.scrollTop = offset * pivot.vOffset;
            pivot.vScrollOffset = offset;
        }

        this.contentDiv.onmouseover = function () {
            pivot.mouseOver = true;
            if (pivot.hOffset > 1) {
                pivot.cellsHScrollDiv.style.backgroundColor = pivot.scrollDivColor;
                pivot.cellHScroll.style.backgroundColor = pivot.scrollColor;
            }
            if (pivot.vOffset > 1) {
                pivot.cellsVScrollDiv.style.backgroundColor = pivot.scrollDivColor;
                pivot.cellVScroll.style.backgroundColor = pivot.scrollColor;
            }
        }

        this.contentDiv.onmouseout = function () {
            pivot.mouseOver = false;
            if (!pivot.screenX) {
                pivot.cellsHScrollDiv.style.backgroundColor = pivot.scrollHiddenColor;
                pivot.cellHScroll.style.backgroundColor = pivot.scrollHiddenColor;
            }
            if (!pivot.screenY) {
                pivot.cellsVScrollDiv.style.backgroundColor = pivot.scrollHiddenColor;
                pivot.cellVScroll.style.backgroundColor = pivot.scrollHiddenColor;
            }
        }

        pivot.style.visibility = "hidden";
        setTimeout(function () {
            pivot.updateSizes();
            pivot.style.visibility = "";
        }, 100);
        
    }

    pivot.action = function () {

    }

    pivot.addWheel = function (elem) {
        if (elem.addEventListener) {
            if ('onwheel' in document) {
                elem.addEventListener("wheel", onWheel);
            } else if ('onmousewheel' in document) {
                elem.addEventListener("mousewheel", onWheel);
            } else {
                elem.addEventListener("MozMousePixelScroll", onWheel);
            }
        } else { // IE8-
            elem.attachEvent("onmousewheel", onWheel);
        }

        function onWheel(e) {
            e = e || window.event;
            var delta = e.wheelDelta || e.deltaY || e.detail;
            if (e.wheelDelta == null && e.deltaY != null) delta *= -40; //fix for firefox
            var info = document.getElementById('delta');
            e.preventDefault ? e.preventDefault() : (e.returnValue = false);
            var sHeight = (pivot.height - pivot.headerHeight) / pivot.vOffset;
            var emptyHeight = (pivot.height - pivot.headerHeight) - sHeight;
            var offset = Math.max(0, Math.min(emptyHeight, -delta / 5 + pivot.vScrollOffset));
            pivot.cellVScroll.style.transform = "translateY(" + offset + "px)";
            pivot.cellsDiv.scrollTop = offset * pivot.vOffset;
            pivot.vScrollOffset = offset;
        }
    }

    pivot.selectCell = function (cell) {
        if (pivot.selectedCell && pivot.selectedCell.td) {
            pivot.selectedCell.td.className = "pivotCell" + pivot.guid;;
            pivot.selectedCell = null;
        }
        if (cell) {
            pivot.selectedCell = cell;
            cell.td.className = "pivotSelectedCell" + pivot.guid;
        } else
            pivot.selectedCell = null;
    }

    pivot.updateSizes = function () {
        this.removeColGroup(this.cornerTable);
        this.removeColGroup(this.headerRowsTable);
        this.removeColGroup(this.headerColsTable);

        this.headerWidth = 0;
        this.headerWidths = [];
        for (var x = 0; x < this.cellsTable.rows[this.cellsTable.rows.length - 1].cells.length; x++) {
            var width = this.cellsTable.rows[this.cellsTable.rows.length - 1].cells[x].getBoundingClientRect().width;
            if (x < this.data.headerWidth) {
                this.headerWidth += width;
            }
            this.headerWidths.push(width);
        }

        this.headerHeight = 0;
        for (var y = 0; y < this.data.headerHeight; y++) {
            this.headerHeight += this.cellsTable.rows[y].getBoundingClientRect().height;
        }

        this.cellsDiv.style.transform = "translate(-" + (this.headerWidth) + "px,-" + (this.headerHeight) + "px)";

        var headerWidth = this.width - this.headerWidth;
        var headerHeight = this.height - this.headerHeight - this.data.headerHeight;

        this.cornerDiv.style.height = "100%";//(this.headerHeight) + "px";
        this.cornerDiv.style.width = this.headerWidth + "px";
        this.cornerTable.style.width = this.headerWidth + "px";

        this.headerColsDiv.style.height = "100%";//(this.headerHeight) + "px";
        this.headerColsDiv.style.width = headerWidth + "px";

        this.headerRowsDiv.style.height = headerHeight + "px";
        this.headerRowsDiv.style.width = this.headerWidth + "px";
        this.headerRowsTable.style.width = this.headerWidth + "px";

        this.cellsDiv.style.height = (this.height - this.data.headerHeight) + "px";
        this.cellsDiv.style.width = (this.width) + "px";

        this.contentDiv.style.height = headerHeight + "px";
        this.contentDiv.style.width = this.headerColsDiv.style.width;

        //top header height
        for (var y = 0; y < this.cellsTable.rows.length; y++) {
            if (y < this.data.headerHeight) {
                this.cornerTable.rows[y].style.height = this.cellsTable.rows[y].offsetHeight + "px"
                this.headerColsTable.rows[y].style.height = this.cellsTable.rows[y].offsetHeight + "px"
            }   
            else
                if (y - this.data.headerHeight < this.headerRowsTable.rows.length)
                    this.headerRowsTable.rows[y - this.data.headerHeight].style.height = this.cellsTable.rows[y].offsetHeight + "px";
        }

        this.headerColsTable.style.width = (this.cellsTable.offsetWidth - this.headerWidth) + "px";

        var offsetWidth = this.cellsTable.offsetWidth - this.headerWidth;
        var offsetHeight = this.cellsTable.offsetHeight - this.headerHeight;

        this.hOffset = offsetWidth / headerWidth;
        this.cellHScroll.style.width = ((headerWidth / offsetWidth) * headerWidth) + "px";

        this.vOffset = offsetHeight / headerHeight;
        this.cellVScroll.style.height = ((headerHeight / offsetHeight) * headerHeight) + "px";

        this.setColGroup(this.cornerTable, this.headerWidths, 0, this.data.headerWidth, 0);
        this.setColGroup(this.headerRowsTable, this.headerWidths, 0, this.data.headerWidth, 0);
        this.setColGroup(this.headerColsTable, this.headerWidths, this.data.headerWidth, this.headerWidths.length, 0);

        var offset = this.cellsDiv.scrollLeft / this.hOffset;
        pivot.cellHScroll.style.transform = "translateX(" + offset + "px)";
        this.hScrollOffset = offset;

        offset = this.cellsDiv.scrollTop / this.vOffset;
        pivot.cellVScroll.style.transform = "translateY(" + offset + "px)";
        this.vScrollOffset = offset;

        pivot.progress.hide();
    }

    pivot.setupArrow = function (cell) {
        var tds = [cell.htd, cell.td];
        var data = this.data;
        var pivot = this;
        var color = cell.isColumn ? pivot.settings.columnHeaderForeColor : pivot.settings.rowHeaderForeColor;
        for (var i in [0, 1]) {
            var ch = tds[i];
            if (!ch) continue;
            ch.innerHTML = "";
            var table = jsObject.CreateHTMLTable();
            table.style.width = "100%";
            var trClosed = document.createElement("div");
            trClosed.style.width = "0";
            trClosed.style.height = "0";
            trClosed.style.borderStyle = "solid";
            trClosed.style.borderWidth = "4px 0 4px 6px";
            trClosed.style.borderColor = "transparent transparent transparent " + color;
            trClosed.style.display = cell.opened ? "none" : "";
            trClosed.style.marginRight = "3px";

            var trOpened = document.createElement("div");
            trOpened.style.width = "0";
            trOpened.style.height = "0";
            trOpened.style.borderStyle = "solid";
            trOpened.style.borderWidth = "0 0 6px 6px";
            trOpened.style.borderColor = "transparent transparent " + color + " transparent";
            trOpened.style.marginRight = "3px";
            trOpened.style.display = !cell.opened ? "none" : "";

            table.addCell(trClosed).style.width = "6px";
            table.addCell(trOpened).style.width = "6px";
            table.addTextCell(ch.cell.text);

            ch.trOpened = trOpened;
            ch.trClosed = trClosed;

            ch.appendChild(table);

            if (i == 0) {
                ch.style.cursor = "pointer";
                ch.onclick = function (e) {
                    var cell = e.currentTarget.cell;
                    cell.htd.setOpened(!cell.opened);
                    cell.td.setOpened(!cell.opened);
                    pivot.progress.show();
                    setTimeout(function () {
                        pivot.openHeader(cell, !cell.opened);
                    }, 0);                    
                }
            }

            ch.setOpened = function (opened) {
                this.trOpened.style.display = opened ? "" : "none";
                this.trClosed.style.display = !opened ? "" : "none";
            }
        }
    }

    pivot.td = function (cell, table, rowIndex, colSpan, rowSpan, borders, tds, className) {
        var td;
        if (!isNaN(rowIndex)) {
            td = table.addCellInRow(rowIndex);
        } else {
            td = document.createElement("td");
            this.jsObject.clearStyles(td);
            rowIndex.parentNode.insertBefore(td, rowIndex);
        }

        for (var st in cell.style)
            td.style[st] = cell.style[st];

        td.className = className;
        td.style.padding = "3px";
        td.innerHTML = cell.text;
        td.colSpan = colSpan;
        td.rowSpan = rowSpan;
        for (var i in borders)
            if (!(borders[i] == "Right" && cell.column == pivot.data.cells.length - 1))
                td.style["border" + borders[i]] = "1px solid " + pivot.settings.lineColor;
        //td.style.color = "white";
        td.cell = cell;
        cell[tds] = td;
        cell.opened = false;

        if (cell.row >= pivot.data.headerHeight && cell.column >= pivot.data.headerWidth && tds == "td") {
            td.onmousedown = function (event) {
                pivot.selectCell(this.cell);
            }
        }

        return td;
    }

    pivot.updateSpan = function (cell, colSpan, rowSpan, table, row, td) {
        cell[td].colSpan += colSpan;
        cell[td].rowSpan += rowSpan;

        if (rowSpan > 0 && cell[td].parentNode.rowIndex == row + rowSpan)
            table.rows[row].insertBefore(cell[td], table.rows[row].cells[0]);

        if (rowSpan < 0 && cell[td].parentNode.rowIndex == row)
            table.rows[row - rowSpan].insertBefore(cell[td], table.rows[row - rowSpan].cells[0]);

        if (cell.parentCellGuid && pivot.cellGuid[cell.parentGuid])
            pivot.updateSpan(pivot.cellGuid[cell.parentGuid], colSpan, rowSpan, table, row, td);

    }

    pivot.openHeader = function (cell, open) {
        cell.opened = open;        
        var tds = ["htd", "td"];
        for (var ii in tds) {
            var td = tds[ii];
            if (!cell.isColumn) {
                var rowIndex = cell[td].parentNode.rowIndex;
                var table = cell[td].parentNode.parentNode.parentNode;
                var totalCell = pivot.cellGuid[cell.totalCellGuid];

                if (open) {
                    var total = pivot.td(totalCell, table, rowIndex, totalCell.colSpan, totalCell.rowSpan, ["Bottom", "Right"], td, "pivotRowHeader" + pivot.guid);
                    cell[td].parentNode.insertBefore(total, cell[td].nextSibling);

                    var span = 0;
                    var firstRow = rowIndex;
                    for (var i = 0; i < cell.dependedCellGuis.length; i++) {
                        var dependedCell = pivot.cellGuid[cell.dependedCellGuis[i]];

                        var colSpan = dependedCell.totalCellGuid ? pivot.cellGuid[dependedCell.totalCellGuid].colSpan + dependedCell.colSpan : dependedCell.colSpan;
                        var rowSpan = dependedCell.totalCellGuid ? pivot.cellGuid[dependedCell.totalCellGuid].rowSpan : dependedCell.rowSpan;
                        var row = dependedCell.totalCellGuid ? pivot.cellGuid[dependedCell.totalCellGuid].row : dependedCell.row;

                        table.insertRow(rowIndex);
                        pivot.td(dependedCell, table, rowIndex, colSpan, rowSpan, ["Bottom", "Right"], td, "pivotRowHeader" + pivot.guid);
                        if (dependedCell.totalCellGuid && ii == 1)
                            this.setupArrow(dependedCell);

                        span += rowSpan;
                        for (y = 0; y < rowSpan; y++) {
                            if (y != 0)
                                table.insertRow(rowIndex);

                            for (x = (pivot.hasTotalsColumn ? pivot.data.headerWidth - 1 : pivot.data.headerWidth); x < (ii == 0 ? pivot.data.headerWidth : pivot.data.cells.length); x++) {
                                if (x < pivot.data.headerWidth || pivot.openedColumns.indexOf(x) >= 0) {
                                    var cell2 = pivot.data.cells[x][row + y];
                                    pivot.td(cell2, table, rowIndex, cell2.colSpan, cell2.rowSpan, (x < pivot.data.headerWidth ? ["Bottom", "Right"] : ["Right"]), td, x < pivot.data.headerWidth ? "pivotRowHeader" + pivot.guid : "pivotCell" + pivot.guid);
                                }
                            }
                            this.openedRows.push(row + y);
                            rowIndex++;
                        }
                    }
                    cell[td].colSpan -= totalCell.colSpan;
                    this.updateSpan(cell, 0, span, table, firstRow, td);
                } else {
                    var span = cell[td].rowSpan;
                    var colSpan = cell[td].colSpan;
                    totalCell[td].innerHTML = cell.text;
                    cell[td] = totalCell[td];
                    totalCell[td].cell = cell;
                    span -= totalCell[td].rowSpan;
                    cell[td].rowSpan += span;
                    cell[td].colSpan += colSpan;
                    this.updateSpan(cell, 0, -span, table, rowIndex, td);

                    for (var y = rowIndex; y < rowIndex + span; y++) {
                        pivot.removeEl(this.openedRows, table.rows[rowIndex].cells[0].cell.row);
                        table.removeRow(rowIndex);
                    }                        

                    if (ii == 1)
                        this.setupArrow(cell);
                }
            } else {
                var rowIndex = cell.row;
                var table = cell[td].parentNode.parentNode.parentNode;
                var totalCell = pivot.cellGuid[cell.totalCellGuid];

                if (open) {
                    var span = 0;
                    var cl = null;
                    var columns = [];
                    for (var i = 0; i < cell.dependedCellGuis.length; i++) {
                        var dependedCell = pivot.cellGuid[cell.dependedCellGuis[i]];

                        var colSpan = dependedCell.totalCellGuid ? pivot.cellGuid[dependedCell.totalCellGuid].colSpan : dependedCell.colSpan;
                        var rowSpan = dependedCell.totalCellGuid ? pivot.cellGuid[dependedCell.totalCellGuid].rowSpan + dependedCell.rowSpan : dependedCell.rowSpan;
                        var column = dependedCell.totalCellGuid ? pivot.cellGuid[dependedCell.totalCellGuid].column : dependedCell.column;
                        columns.push(column);
                        var tCell = pivot.getNextCell(column, rowIndex + 1, td);

                        cl = pivot.td(dependedCell, table, rowIndex + 1, colSpan, rowSpan, ["Bottom", "Right"], td, "pivotColumnHeader" + pivot.guid);

                        table.rows[rowIndex + 1].insertBefore(cl, tCell);
                        if (dependedCell.totalCellGuid && ii == 1)
                            this.setupArrow(dependedCell);
                        span += colSpan;
                        this.openedColumns.push(column);

                        if (ii == 1)
                            table.addCellInLastRow();
                    }
                    var total = pivot.td(totalCell, table, rowIndex + 1, totalCell.colSpan, totalCell.rowSpan, ["Bottom", "Right"], td, "pivotColumnHeader" + pivot.guid);
                    table.rows[rowIndex + 1].insertBefore(total, cl != null ? cl.nextSibling : null);

                    cell[td].rowSpan = 1;
                    this.updateSpan(cell, span, 0, table, firstRow, td);

                    if (ii == 1 && columns.length > 0)
                        for (var y = pivot.data.headerHeight; y < pivot.data.cells[0].length; y++)
                            if (pivot.openedRows.indexOf(y) >= 0) {
                                var tCell = pivot.getNextCell(columns[0], y, td);
                                for (var i = columns.length - 1; i >= 0; i--) {
                                    var x = columns[i];
                                    var cell2 = pivot.data.cells[x][y];
                                    var cl = pivot.td(cell2, table, 0, cell2.colSpan, cell2.rowSpan, ["Right"], td, "pivotCell" + pivot.guid);
                                    tCell.parentNode.insertBefore(cl, tCell);
                                    tCell = cl;
                                }
                            }
                                
                } else {
                    var span = cell[td].colSpan;
                    for (var y = rowIndex + 1; y < (ii == 0 ? pivot.data.headerHeight : pivot.data.cells[0].length); y++) {
                        for (var x = cell.column; x < totalCell.column; x++) {                                                                                  
                            pivot.removeEl(this.openedColumns, x);
                            var tCell = pivot.data.cells[x][y][td];
                            if (tCell) {
                                tCell.parentNode.removeChild(tCell);
                                pivot.data.cells[x][y][td] = null;
                                if (ii == 1 && y == rowIndex + 1)
                                    table.tr[table.tr.length - 1].removeChild(table.tr[table.tr.length - 1].childNodes[0]);
                            }                                
                        }
                    }

                    var colSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].colSpan : cell.colSpan;
                    var rowSpan = cell.totalCellGuid ? this.cellGuid[cell.totalCellGuid].rowSpan + cell.rowSpan : cell.rowSpan;
                    totalCell[td].parentNode.removeChild(totalCell[td]);                    
                    totalCell[td] = null;

                    var tCell = cell[td];
                    var cl = this.td(cell, table, tCell, colSpan, rowSpan, ["Bottom", "Right"], td, "pivotColumnHeader" + pivot.guid);
                    tCell.parentNode.removeChild(tCell);
                    span -= cell[td].colSpan;
                    cell[td].colSpan += span;

                    this.updateSpan(cell, -span, 0, table, firstRow, td);
                    if (ii == 1)
                        this.setupArrow(cell);
                }
            }
        }
        this.updateSizes();
    }

    pivot.removeEl = function (array, value) {
        var index;
        while ((index = array.indexOf(value)) >= 0)
            array.splice(index, 1);
    }

    pivot.getNextCell = function (x, y, td) {
        x++;
        while (x < pivot.data.cells.length && !pivot.data.cells[x][y][td]) {
            x++;
        }
        return x < pivot.data.cells.length && pivot.data.cells[x][y][td] ? pivot.data.cells[x][y][td] : null;
    }

    pivot.getWidths = function (table, widths) {
        var ocells = {};
        for (var y = 0; y < table.rows.length; y++) {
            for (var x = 0; x < table.rows[y].cells.length; x++) {
                var cell = table.rows[y].cells[x];
                if (cell.colSpan == 1) {
                    var xx = x;
                    for (i = x; i >= 0; i--)
                        if (ocells[i + "," + y]) xx++;
                    widths[xx] = Math.max(widths[xx], cell.offsetWidth);
                }
                if (cell.colSpan > 1) {
                    for (xx = x + 1; xx < x + cell.colSpan; xx++) {
                        ocells[xx + "," + y] = true;
                    }
                }
                if (cell.rowSpan > 1) {
                    for (var xx = x; xx < x + cell.colSpan; xx++) {
                        for (var yy = y + 1; yy < y + cell.rowSpan; yy++) {
                            ocells[xx + "," + yy] = true;
                        }
                    }
                }
            }
        }            
    }

    pivot.removeColGroup = function (table) {
        if (table.getElementsByTagName("colgroup").length > 0) {
            table.removeChild(table.getElementsByTagName("colgroup")[0]);
        }
    }

    pivot.setColGroup = function (table, widths, start, end, cx) {        
        var colgroup = document.createElement("colgroup");
        for (var i = start; i < end; i++) {
            var col = document.createElement("col");
            col.style.width = (widths[i] + cx) != 0 ? (widths[i] + cx)+ "px" : "auto";
            colgroup.appendChild(col);
        }
        table.insertBefore(colgroup, table.firstChild);
    }

    return pivot;
}

StiJsViewer.prototype.CreatePivotTableElementContent = function (element) {
    var jsObject = this;
    
    var elementAttrs = element.elementAttributes;
    var contentAttrs = elementAttrs.contentAttributes;
    if (!contentAttrs) return;

    var panel = document.createElement("div");
    panel.style.position = "absolute";
    panel.style.left = panel.style.top = panel.style.right = panel.style.bottom =  "0px";
    panel.style.overflow = "hidden";
    element.contentPanel.appendChild(panel);

    var padding = elementAttrs.padding.split(",");                    
    var gridWidth = parseInt(element.style.width) - parseInt(padding[1]) - parseInt(padding[3]);
    var gridHeight = parseInt(element.style.height) - parseInt(padding[0]) - parseInt(padding[2]);

    var border = elementAttrs.border;
    if (border) {
        var horBorders = (border.left ? border.size : 0) + (border.right ? border.size : 0);
        var vertBorders = (border.top ? border.size : 0) + (border.bottom ? border.size : 0);
        gridWidth -= horBorders;
        gridHeight -= vertBorders;
    }

    if (element.titlePanel) {
        gridHeight -= element.titlePanel.offsetHeight;
    }

    var dataGrid = jsObject.PivotTable(gridWidth, gridHeight, contentAttrs.settings);
    panel.appendChild(dataGrid);

    dataGrid.showData(contentAttrs.data);
}

StiJsViewer.prototype.InitializeDashboardExportForm = function () {
    var form = this.BaseForm("dashboardExportForm", this.collections.loc["ExportFormTitle"], 1);
    form.container.style.padding = "0px";
    form.controls = {};
    form.defaultExportSettings = {};

    var properties = [
        ["PaperSize", this.collections.loc["PaperSize"], this.DropDownList("exportPaperSize", 200, null, this.GetPaperSizesItems(), true), "6px 12px 6px 12px"],
        ["Orientation", this.collections.loc["Orientation"], this.DropDownList("exportOrientation", 200, null, this.GetOrientationItems(), true), "6px 12px 6px 12px"],
        ["DataType", this.collections.loc["DataType"], this.DropDownList("exportDataType", 200, null, this.GetDataTypesItems(), true), "6px 12px 6px 12px"],
        ["ImageType", this.collections.loc["ImageFormat"], this.DropDownList("exportImageType", 200, null, this.GetImageTypesItems(), true), "6px 12px 6px 12px"],
        ["ImageQuality", this.collections.loc["ImageQuality"], this.DropDownList("exportImageQuality", 100, null, this.GetDashboardImageQualityItems()), "6px 12px 6px 12px"],
        ["Scale", this.collections.loc["Scale"], this.DropDownList("exportScale", 100, null, this.GetDashboardImageQualityItems()), "6px 12px 6px 12px"],
        ["ExportDataOnly", null, this.CheckBox("exportDataOnly", this.collections.loc["ExportDataOnly"]), "6px 12px 6px 12px"],
        ["OpenAfterExport", null, this.CheckBox("exportOpenAfterExport", this.collections.loc["OpenAfterExport"]), "6px 12px 6px 12px"]
    ];

    var proprtiesTable = this.CreateHTMLTable();
    proprtiesTable.style.margin = "6px 0px 6px 0px";
    form.container.appendChild(proprtiesTable);

    for (var i = 0; i < properties.length; i++) {
        form.addControlRow(proprtiesTable, properties[i][1], properties[i][0], properties[i][2], properties[i][3]);
    }

    form.controls.ImageType.action = function () {
        form.controls.Scale.setEnabled(this.key != "Svg" && this.key != "Svgz") ? "" : "none";
    }
    
    //Form Methods
    form.setDefaultValues = function () {
        var defaultExportSettings = this.defaultExportSettings[this.exportFormat] || this.jsObject.getDefaultExportSettings(this.exportFormat, true);
        if (!defaultExportSettings) return;

        for (var propertyName in this.controls) {
            var control = this.controls[propertyName];
            var value = defaultExportSettings[propertyName];
            if (control && value != null) {
                if (control.setKey != null) control.setKey(control.haveKey ? (control.haveKey(value) ? value : (control.items && control.items.length > 0 ? control.items[0].key : value)) : value);
                else if (control.setChecked != null) control.setChecked(value);
                else if (control.value != null) control.value = value;
            }
        }
    }

    form.showControlsByFormat = function () {
        this.controls.PaperSizeRow.style.display = this.controls.OrientationRow.style.display = this.exportFormat == "Pdf" ? "" : "none";
        this.controls.ImageQualityRow.style.display = this.exportFormat == "Pdf" || this.exportFormat == "Excel2007" ? "" : "none";
        this.controls.ImageTypeRow.style.display = this.controls.ScaleRow.style.display = this.exportFormat == "Image" ? "" : "none";
        this.controls.DataTypeRow.style.display = this.exportFormat == "Data" ? "" : "none";
        this.controls.OpenAfterExportRow.style.display = !this.jsObject.options.jsMode && (this.exportFormat == "Pdf" || this.exportFormat == "Image") ? "" : "none";
        this.controls.ExportDataOnlyRow.style.display = this.exportFormat == "Excel2007" && (this.elementType == "StiTableElement" || this.elementType == "StiPivotTableElement") ? "" : "none";
    }

    form.getExportSettingsValues = function () {
        var settings = {};
        for (var i = 0; i < properties.length; i++) {
            var propertyName = properties[i][0];
            if (this.controls[propertyName + "Row"].style.display == "") {
                var control = this.controls[propertyName];
                if (control.setKey != null) settings[propertyName] = control.key;
                else if (control.setChecked != null) settings[propertyName] = control.isChecked;
                else if (control.value != null) settings[propertyName] = control.value;
            }
        }
        return settings;
    }

    form.show = function (exportFormat, elementName, elementType) {
        this.exportFormat = exportFormat;
        this.elementName = elementName;
        this.elementType = elementType;
        this.showControlsByFormat();
        this.setDefaultValues();
        this.controls.ImageType.action();
        this.changeVisibleState(true);
    }

    form.action = function () {
        this.changeVisibleState(false);
        var resultSettings = this.getExportSettingsValues();
        this.defaultExportSettings[this.exportFormat] = resultSettings;
        this.jsObject.postExport(this.exportFormat, resultSettings, this.elementName, true);
    }

    return form;
}
